for pn,p in enumerate(pdf.pages):
    lines=[l for l in p.extract_text_lines() if l['top']<730 and not re.fullmatch(r'\d+',l['text'].strip()) and not any(s in l['text'] for s in SKIP)]
    xs=collections.Counter(round(l['x0']) for l in lines); bx=xs.most_common(1)[0][0]
    # units = groups of vertically overlapping images
    ims=sorted(p.images,key=lambda i:i['top']); units=[]
    for im in ims:
        if units and im['top']<units[-1]['bottom']-3: units[-1]['imgs'].append(im); units[-1]['bottom']=max(units[-1]['bottom'],im['bottom'])
        else: units.append({'top':im['top'],'bottom':im['bottom'],'imgs':[im],'lines':[],'sec':None})
    events=[]
    for l in lines:
        t=l['text'].strip()
        if abs(round(l['x0'])-bx)>4 and (t.upper()==t or len(t)<70):
            events.append((l['top'],'h',t)); continue
        c=(l['top']+l['bottom'])/2
        def d(u): return 0 if u['top']-3<=c<=u['bottom']+3 else min(abs(c-u['top']),abs(c-u['bottom']))
        u=min(units,key=d) if units else None
        if u is None or d(u)>14:
            events.append((l['top'],'o',t))
        else: u['lines'].append(t)
    for u in units: events.append((u['top'],'u',u))
    events.sort(key=lambda e:e[0])
    orph=[]
    for _,k,v in events:
        if k=='h': section=v
        elif k=='o': orph.append(v)
        else:
            if v['sec'] is None: v['sec']=section
    # orphans at top of page belong to pending; orphans elsewhere → log
    if pending and units:
        pass
    for _,k,v in events:
        pass
    for u in units:
        imgs=[]
        for im in sorted(u['imgs'],key=lambda i:i['x0']):
            crop=p.within_bbox((im['x0']-1,im['top']-1,im['x1']+1,im['bottom']+1)).to_image(resolution=200)
            buf=io.BytesIO(); crop.original.save(buf,'PNG'); imgs.append(base64.b64encode(buf.getvalue()).decode())
        sec=u['sec']; sec=sec.capitalize() if sec.isupper() else sec
        cards.append({'sec':sec,'text':' '.join(u['lines']),'imgs':imgs,'page':pn+1})
    if orph: log.append((pn+1,orph))
print(len(cards),sum(len(c['imgs']) for c in cards)); print('orphan lines',log)
for i,c in enumerate(cards):
    if not c['text'] or not c['text'][0].isupper(): print('BAD',i,c['page'],c['text'][:60])
