import pdfplumber, json, base64, io, collections, re
pdf=pdfplumber.open('/mnt/user-data/uploads/66e469ae-2005_bu3.pdf')
SKIP=('ПРИЛОЖЕНИЕ','Основные условные','применяемые в боевых')
cards=[]; section='Пункты управления и средства связи'; pending=None; problems=[]
def capword(t): return bool(re.match(r'[А-ЯЁ][а-яё]',t))
for pn,p in enumerate(pdf.pages):
    lines=[l for l in p.extract_text_lines() if not (pn==0 and l['top']>735) and not re.fullmatch(r'\d+',l['text'].strip()) and not any(s in l['text'] for s in SKIP)]
    bx=collections.Counter(round(l['x0']) for l in lines).most_common(1)[0][0]
    ims=sorted(p.images,key=lambda i:i['top']); units=[]
    for im in ims:
        if units and im['top']<units[-1]['bottom']-3: units[-1]['imgs'].append(im); units[-1]['bottom']=max(units[-1]['bottom'],im['bottom'])
        else: units.append({'top':im['top'],'bottom':im['bottom'],'imgs':[im],'para':None})
    paras=[]; heads=[]
    for l in lines:
        t=l['text'].strip()
        if abs(round(l['x0'])-bx)>4: heads.append((l['top'],t)); continue
        prev=paras[-1] if paras else None
        if prev and l['top']-prev['bottom']<5 and not (capword(t) and re.search(r'[).]$',prev['text'])):
            prev['text']+=' '+t; prev['bottom']=l['bottom']
        else: paras.append({'top':l['top'],'bottom':l['bottom'],'text':t})
    def sec_at(y):
        s=section
        for hy,ht in heads:
            if hy<y: s=ht
        return s
    for pa in paras:
        def ov(u): return min(u['bottom'],pa['bottom'])-max(u['top'],pa['top'])
        cand=[u for u in units if u['para'] is None]
        u=max(cand,key=ov) if cand else None
        if u is not None and ov(u)>-15: u['para']=pa
        else:
            if pending: problems.append(('double pending',pn+1,pa['text'][:40]))
            pending={'text':pa['text'],'sec':sec_at(pa['top']),'page':pn+1}
    for u in units:
        if u['para'] is None:
            if pending and u is units[0]: u['para']=pending; u['sec']=pending['sec']; pending=None
            else: problems.append(('img without text',pn+1,u['top'])); continue
        else: u['sec']=sec_at(u['top']+1)
        imgs=[]
        for im in sorted(u['imgs'],key=lambda i:i['x0']):
            crop=p.within_bbox((im['x0']-1,im['top']-1,im['x1']+1,im['bottom']+1)).to_image(resolution=200)
            buf=io.BytesIO(); crop.original.save(buf,'PNG'); imgs.append(base64.b64encode(buf.getvalue()).decode())
        s=u['sec']; s=s.capitalize() if s.isupper() else s
        txt=re.sub(r'(\w)- (\w)',r'\1-\2',u['para']['text']); txt=re.sub(r'\s+',' ',txt).replace('{','(')
        cards.append({'sec':s,'text':txt,'imgs':imgs,'page':pn+1})
    if heads: section=heads[-1][1]
print(len(cards),sum(len(c['imgs']) for c in cards),'problems',problems,'pending',pending)
print(collections.Counter(c['sec'] for c in cards))
json.dump(cards,open('cards3.json','w'),ensure_ascii=False)
EOF
