import numpy as np, subprocess, glob
UP = "/mnt/user-data/uploads"
FILES = sorted(glob.glob(UP + "/*ElevenLabs*.mp3"), key=lambda f: f.split("ElevenLabs_")[1])
SR = 44100

def load(f):
    raw = subprocess.run(["ffmpeg", "-v", "error", "-i", f, "-ac", "1", "-ar", str(SR), "-f", "f32le", "-"], capture_output=True).stdout
    return np.frombuffer(raw, np.float32).copy()

def analyze(x):
    hop = int(0.01 * SR); n = len(x) // hop
    rms = np.sqrt(np.mean(x[:n * hop].reshape(n, hop) ** 2, 1) + 1e-12)
    db = 20 * np.log10(rms / rms.max()); sp = db > -36
    idx = np.where(sp)[0]; s, e = idx[0] * 0.01, (idx[-1] + 1) * 0.01
    pauses = []; run = None
    for i in range(idx[0], idx[-1] + 1):
        if not sp[i]:
            if run is None: run = i
        else:
            if run is not None and i - run >= 10: pauses.append((run * 0.01, i * 0.01))
            run = None
    return s, e, pauses

def chunk_times(path, chunks, lead):
    x = load(path); s, e, pauses = analyze(x); dur = len(x) / SR
    if not chunks: return dur, []
    w = np.array([len(c) + 3 for c in chunks], float); cum = np.cumsum(w) / w.sum()
    mids = [(a + b) / 2 for a, b in pauses]
    bounds = []
    for c in cum[:-1]:
        b = s + (e - s) * c
        if mids:
            m = min(mids, key=lambda m_: abs(m_ - b))
