const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, ImageRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType,
  ShadingType, BorderStyle, LevelFormat, PageBreak, Footer, PageNumber, TableOfContents, ExternalHyperlink } = require('docx');
const SZ = JSON.parse(fs.readFileSync('/home/claude/out/sizes.json'));
const PNG = '/home/claude/out/png/';
const FONT = 'Times New Roman';

function runs(text, base = {}) {
  // **bold**, _italic_
  const out = []; const re = /(\*\*[^*]+\*\*|__[^_]+__)/g; let last = 0, m;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), ...base }));
    const t = m[0];
    if (t.startsWith('**')) out.push(new TextRun({ text: t.slice(2, -2), bold: true, ...base }));
    else out.push(new TextRun({ text: t.slice(2, -2), italics: true, ...base }));
    last = m.index + t.length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), ...base }));
  return out;
}
const P = (t, o = {}) => new Paragraph({ children: runs(t), alignment: AlignmentType.JUSTIFIED, spacing: { after: 120, line: 300 }, indent: { firstLine: 567 }, ...o });
const H1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(t)] });
const H2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(t)] });
const B = (t, lvl = 0) => new Paragraph({ numbering: { reference: 'bul', level: lvl }, children: runs(t), alignment: AlignmentType.JUSTIFIED, spacing: { after: 60, line: 288 } });
const N = t => new Paragraph({ numbering: { reference: 'num', level: 0 }, children: runs(t), alignment: AlignmentType.JUSTIFIED, spacing: { after: 60, line: 288 } });
let figN = 0;
function IMG(file, caption, widthIn = 6.6) {
  const [w, h] = SZ[file]; const W = widthIn * 96; const H = W * h / w; figN += 1;
  return [new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 40 }, keepNext: true,
            children: [new ImageRun({ type: 'png', data: fs.readFileSync(PNG + file), transformation: { width: Math.round(W), height: Math.round(H) },
              altText: { title: caption, description: caption, name: file } })] }),
          new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 200 }, children: [new TextRun({ text: `Рис. ${figN}. ${caption}`, italics: true, size: 20 })] })];
}
const border = { style: BorderStyle.SINGLE, size: 4, color: 'A6A6A6' };
const borders = { top: border, bottom: border, left: border, right: border };
function TBL(head, rows, widths, caption) {
  const total = widths.reduce((a, b) => a + b, 0);
  const mk = (t, hdr, i) => new TableCell({ borders, width: { size: widths[i], type: WidthType.DXA },
    shading: hdr ? { fill: '1F3864', type: ShadingType.CLEAR, color: 'auto' } : undefined, margins: { top: 40, bottom: 40, left: 80, right: 80 },
    children: [new Paragraph({ alignment: i === 0 ? AlignmentType.LEFT : AlignmentType.CENTER, children: runs(String(t), { size: 19, color: hdr ? 'FFFFFF' : undefined, bold: hdr || undefined }) })] });
  const out = [];
  if (caption) out.push(new Paragraph({ spacing: { before: 120, after: 60 }, keepNext: true, children: [new TextRun({ text: caption, italics: true, size: 20 })] }));
  out.push(new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    rows: [new TableRow({ tableHeader: true, children: head.map((t, i) => mk(t, true, i)) }), ...rows.map(r => new TableRow({ children: r.map((t, i) => mk(t, false, i)) }))] }));
  out.push(new Paragraph({ spacing: { after: 120 }, children: [] }));
  return out;
}
const link = (t, url) => new Paragraph({ numbering: { reference: 'num2', level: 0 }, spacing: { after: 60 },
  children: [new TextRun(t + ' — '), new ExternalHyperlink({ link: url, children: [new TextRun({ text: url, style: 'Hyperlink' })] })] });

const C = [];
// ---------- Title page ----------
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 600, after: 120 }, children: [new TextRun({ text: 'НИУ ВШЭ', size: 26 })] }));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 1800 }, children: [new TextRun({ text: 'Майнор «Финансовые рынки и финансовые институты»', size: 26 })] }));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 240 }, children: [new TextRun({ text: 'АНАЛИТИЧЕСКИЙ ОТЧЁТ', bold: true, size: 32 })] }));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 240 }, children: [new TextRun({ text: '«Всепогодный» портфель на российском финансовом рынке:', bold: true, size: 30 })] }));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 1600 }, children: [new TextRun({ text: 'паритет риска, обоснование весов и динамика с ребалансировкой (ноябрь 2023 – ноябрь 2026)', size: 28 })] }));
C.push(new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 80 }, children: [new TextRun({ text: 'Бонусное задание', size: 24 })] }));
C.push(new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 80 }, children: [new TextRun({ text: 'Выполнил(а): ____________________, группа ______', size: 24 })] }));
C.push(new Paragraph({ alignment: AlignmentType.RIGHT, spacing: { after: 2000 }, children: [new TextRun({ text: 'Приложение: файл Excel «AllWeather_RU_model.xlsx»', size: 24 })] }));
C.push(new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: 'Москва, ноябрь 2026', size: 24 })] }));
C.push(new Paragraph({ children: [new PageBreak()] }));
C.push(new Paragraph({ children: [new TextRun({ text: 'Содержание', bold: true, size: 28 })], spacing: { after: 200 } }));
C.push(new TableOfContents('Содержание', { hyperlink: true, headingStyleRange: '1-2' }));
C.push(new Paragraph({ children: [new PageBreak()] }));

// ---------- Summary ----------
C.push(H1('Краткие выводы'));
C.push(P('Цель работы — построить на российском рынке портфель по логике «всепогодного» (all-weather) подхода Р. Далио, включив инструменты всех сегментов финансового рынка (фондового, долгового, денежного, валютного, срочного и рынка драгметаллов) с разными сроками обращения и функциями, обосновать веса и показать динамику портфеля с ребалансировкой на реальных рыночных данных Московской биржи и Банка России.'));
C.push(B('**Состав:** 11 классов активов в четырёх «квадрантах» экономического цикла (Табл. 3 задания) плюс буфер ликвидности: акции, корпоративные облигации AA, длинные и среднесрочные ОФЗ, ОФЗ-ИН, золото, серебро, нефть Brent (фьючерс), юаневые облигации, короткие ОФЗ и денежный рынок.'));
C.push(B('**Веса** получены моделью равного вклада в риск (ERC) с ограничениями на окне ноябрь 2022 – ноябрь 2023 и округлены: 10% акции, 10% корп. облигации, 19,5% ОФЗ 10+, 20% ОФЗ 3–5, 7,5% золото, 7,5% ОФЗ-ИН, 3,5% нефть, 5% серебро, 7% юаневые облигации, 5% короткие ОФЗ, 5% LQDT.'));
C.push(B('**Результат за 3 года (12 ежеквартальных ребалансировок):** +43,6% (12,9% годовых) при волатильности 6,8% и максимальной просадке −6,9%. Индекс МосБиржи полной доходности за тот же период дал +1,6% с просадкой −33,4%, портфель 60/40 — +14,6%, «вечный портфель» Брауна — +40,5% с просадкой −13,9%. Отрицательным был лишь 1 квартал из 12 (−4,3%), у индекса акций — 6 из 12.'));
C.push(B('**Главное ограничение:** в режиме ключевой ставки 15–21% денежный рынок (LQDT, +64,3%) обогнал все рисковые стратегии, поэтому коэффициенты Шарпа отрицательны. Всепогодный подход выполнил свою функцию — защиту от разных сценариев, — но в период жёсткой ДКП разумно увеличивать долю ликвидности: вариант с 25% ликвидности дал +46,3% при просадке всего −5,0%.'));
C.push(B('**Частота ребалансировки** слабо влияет на доходность (42,6–43,8%), но отказ от неё увеличивает просадку до −8,6% и волатильность; оптимальным по соотношению риска и издержек выбран квартальный режим.'));

// ---------- 1 Theory ----------
C.push(H1('1. Концепция паритета риска и «всепогодного» портфеля'));
C.push(P('Классический подход к распределению капитала (например, 60% акций и 40% облигаций) равномерен по деньгам, но не по риску: волатильность акций в 3–4 раза выше, поэтому почти весь риск такого портфеля (обычно 85–90%) приходится на акции. Паритет риска (risk parity) переворачивает логику: веса подбираются так, чтобы каждый актив или группа активов вносили **одинаковый вклад в общий риск** портфеля.'));
C.push(P('Формально вклад актива i в риск равен RC(i) = w(i)·(Σw)(i) / σ²(p), где w — вектор весов, Σ — ковариационная матрица доходностей, σ(p) — волатильность портфеля. Сумма вкладов равна 100%. В портфеле паритета риска RC(i) равны между собой (или равны заданному «бюджету риска»).'));
C.push(P('Г. Браун в «вечном портфеле» (1987, Табл. 1) разделил капитал поровну между четырьмя активами, каждый из которых выигрывает в своём режиме экономики: акции — при процветании, долгосрочные облигации — при дефляции, золото — при инфляции, краткосрочные облигации (кэш) — при спаде. Р. Далио (Bridgewater Associates) развил идею: экономика определяется двумя факторами — ростом и инфляцией, — каждый из которых может оказаться выше или ниже ожиданий. Получаются **четыре квадранта** (Табл. 3), и портфель должен содержать равный риск в каждом из них. Поскольку облигации менее волатильны, в «всепогодном» портфеле (Табл. 2) на них приходится 55% капитала.'));
C.push(H2('1.1. Почему портфель Далио нельзя просто скопировать в России'));
C.push(B('**Доступ к активам.** Американские акции и казначейские облигации для российского инвестора после 2022 г. практически недоступны (блокировка инфраструктуры, санкционные риски). Нужны отечественные аналоги.'));
C.push(B('**Высокие ставки.** Институциональный risk parity использует кредитное плечо на облигационную часть. При ключевой ставке 15–21% стоимость фондирования выше доходности длинных ОФЗ, поэтому плечо экономически невыгодно — портфель строится без плеча, а роль «кэша» выполняет денежный рынок.'));
C.push(B('**Валютный риск.** Для российского инвестора ослабление рубля — один из главных источников инфляции. Поэтому в инфляционные квадранты добавлены активы с валютной составляющей: золото и серебро (цена в рублях), юаневые облигации, нефть.'));
C.push(B('**Инфляционные облигации.** В РФ есть ОФЗ-ИН с номиналом, индексируемым на ИПЦ, — аналог американских TIPS, которые Далио использует в расширенной версии стратегии.'));
C.push(B('**Сырьевые товары.** Широкого товарного ETF на Мосбирже нет, поэтому товарный блок собран из биржевого серебра и фьючерса на нефть Brent (срочный рынок).'));

// ---------- 2 Universe ----------
C.push(H1('2. Состав портфеля: инструменты всех сегментов рынка'));
C.push(P('В портфель включены 11 классов активов, которые различаются по сегменту рынка (фондовый, долговой государственный и корпоративный, денежный, валютный, рынок драгметаллов, срочный), сроку обращения (от одного дня до бессрочных) и функции в портфеле. Каждый класс отнесён к квадранту Табл. 3 задания по тому, в каком сценарии он даёт наибольшую доходность.'));
C.push(...IMG('s01_instr.png', 'Универсум инструментов (лист «Инструменты» файла Excel)'));
C.push(H2('2.1. Обоснование выбора по квадрантам'));
C.push(P('**Рост выше ожиданий, инфляция ниже (акции, корпоративные облигации).** Акции получают выгоду от роста прибыли компаний; используется БПИФ TMOS, который повторяет индекс МосБиржи с реинвестированием дивидендов, — это даёт широкую диверсификацию по 40+ эмитентам одной сделкой. Корпоративные облигации рейтинга AA дают кредитную премию к ОФЗ (около 1–3 п.п.) и выигрывают при стабильной экономике, когда кредитный риск снижается; используется БПИФ SBRB.'));
C.push(P('**Рост ниже ожиданий, инфляция ниже (длинные и среднесрочные ОФЗ).** При замедлении экономики и инфляции Банк России снижает ставку, и цены облигаций с большой дюрацией растут сильнее всего. Средняя ОФЗ 26251 (дюрация ≈ 3,1 года) — ядро квадранта по Табл. 3; длинная ОФЗ 26248 (2040 г., дюрация ≈ 5,8 года при доходности 16,7%) — «рычаг» на снижение ставок. Текущие доходности ОФЗ (15,5–16,7%) существенно выше ключевой ставки 14%, то есть рынок закладывает высокую премию за риск, что повышает потенциал этого блока при развороте ДКП.'));
C.push(P('**Рост ниже ожиданий, инфляция выше (золото, ОФЗ-ИН).** Это стагфляционный сценарий, в котором проигрывают и акции, и номинальные облигации. Золото исторически служит защитой от инфляции, девальвации и геополитических шоков; в рублях оно дополнительно хеджирует ослабление национальной валюты. ОФЗ-ИН 52005 защищают от инфляции напрямую: номинал индексируется на ИПЦ, а купон 2,5% является реальной доходностью.'));
C.push(P('**Рост выше ожиданий, инфляция выше (нефть, серебро, юаневые облигации).** Сырьевой цикл: при перегреве экономики растут цены на нефть и промышленные металлы. Нефть включена через фьючерс BR на срочном рынке Мосбиржи (полностью обеспеченная позиция: под номинал контракта держится LQDT), серебро — через биржевой контракт SLVRUB_TOM. Юаневые облигации (ОФЗ 29 CNY Минфина) дают процентный доход в валюте и выигрывают при ослаблении рубля, которое в российской экономике обычно сопровождает инфляционный импульс.'));
C.push(P('**Буфер ликвидности (короткие ОФЗ, денежный рынок).** 10% капитала держится в инструментах с минимальной дюрацией: короткая ОФЗ 26232 (погашение 2027 г.) и БПИФ LQDT, доходность которого следует за ставкой RUSFAR (ставка РЕПО с ЦК, близкая к ключевой). Эта часть нужна для ребалансировок без продажи других активов, для обеспечения по фьючерсу и как «кэш» вечного портфеля Брауна.'));

