 h2("Упражнение 1. Поставь знак ударения"),
 p("Поставь знак ударения над буквами, которые обозначают ударные гласные звуки.",{run:{italics:true}})];
A.forEach((g,i)=>ch.push(p([r(`${i+1}) `,{bold:true}),r(g.join("          "),{size:30})],{spacing:{after:200}})));
ch.push(pb(),h2("Упражнение 2. Найди ошибку"),p("Ударная гласная выделена большой буквой. В каждой строке в одном слове ударение поставлено неверно. Подчеркни это слово и запиши его правильно.",{run:{italics:true}}));
B.forEach((g,i)=>{ch.push(p([r(`${i+1}) `,{bold:true}),r(g.slice(0,4).join("        "),{size:28})],{spacing:{before:160,after:0}}));ch.push(line("Правильно: "));});
ch.push(h2("Упражнение 3. Распредели слова"),p("Распредели слова по столбикам: ударение на первом слоге или на втором.",{run:{italics:true}}));
ch.push(p("торты,  звонит,  банты,  щавель,  шарфы,  магазин,  кухонный,  портфель,  досуха,  квартал",{run:{size:28}}));
ch.push(table([["Ударение на 1-м слоге","Ударение на 2-м слоге"],["",""],["",""],["",""],["",""],["",""]],[4850,4850]));
ch.push(pb(),h2("Ответы (ударная гласная — большая буква)"));
K.forEach((g,i)=>ch.push(p([r(`Упр. 1, ${i+1}) `,{bold:true}),r(g.join(", "))],{spacing:{after:60}})));
B.forEach((g,i)=>ch.push(p([r(`Упр. 2, ${i+1}) `,{bold:true}),r(g[4])],{spacing:{after:60}})));
ch.push(p([r("Упр. 3: ",{bold:true}),r("на 1-м слоге — тОрты, бАнты, шАрфы, кУхонный, дОсуха; на 2-м слоге — звонИт, щавЕль, магазИн, портфЕль, квартАл.")]));
const doc=new D.Document({styles,sections:[{properties:{page},children:ch}]});
D.Packer.toBuffer(doc).then(b=>fs.writeFileSync("VPR_russkiy_4_klass_zadanie_4_udarenie.docx",b));
