const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, LevelFormat,
  ShadingType, BorderStyle, PageBreak, Footer, PageNumber } = require('docx');

const F = "Times New Roman";

// parse **bold** segments
function runs(text, extra = {}) {
  const parts = text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean);
  return parts.map(p => p.startsWith('**')
    ? new TextRun({ text: p.slice(2, -2), bold: true, font: F, ...extra })
    : new TextRun({ text: p, font: F, ...extra }));
}

const C = []; // content blocks
const h1 = t => C.push(['h1', t]);
const cond = t => C.push(['cond', t]);
const h2 = t => C.push(['h2', t]);
const p = t => C.push(['p', t]);
const b = (...ts) => ts.forEach(t => C.push(['b', t]));
const brk = () => C.push(['brk']);

// ---------------- ЗАДАЧА 1 ----------------
h1("Задача 1. Непослушный трёхлетний ребёнок");
cond("Молодые родители жалуются на непослушание своего 3-летнего ребёнка. Он слишком активный, подвижный, упрямый, настаивает на своём. Любые запреты вызывают у него протест, просьбы и уговоры не действуют. Не хочет подчиняться семейным правилам: отказывается обедать совместно со всеми, убирать игрушки; рвёт книжки, пытается ударить родителей. Супруги просят дать совет, как заставить ребёнка слушаться.");
h2("Анализ ситуации");
p("Описанное поведение характерно для **кризиса трёх лет** (Л.С. Выготский, Д.Б. Эльконин). В этом возрасте у ребёнка формируется центральное новообразование — «Я сам»: он впервые осознаёт себя отдельным человеком со своими желаниями и стремится утвердить свою самостоятельность. Отсюда типичные симптомы кризиса («семизвездие»): негативизм, упрямство, строптивость, своеволие, протест-бунт, обесценивание взрослых, деспотизм.");
p("Ребёнок поступает «наперекор» не потому, что он «плохой», а потому, что проверяет границы своих возможностей и прочность правил. Повышенная подвижность в этом возрасте также во многом соответствует норме.");
p("Ключевая ошибка — в самом запросе родителей: «как **заставить** ребёнка слушаться». Попытка силой подавить волю приводит либо к усилению протеста, либо (при «победе» взрослых) к формированию пассивности, неуверенности, зависимости от чужого мнения. Вероятно, в семье также есть непоследовательность требований: много запретов, которые то соблюдаются, то нет, а уговоры и просьбы показывают ребёнку, что правила можно обсуждать бесконечно.");
p("**Заключение:** поведение ребёнка — проявление нормативного возрастного кризиса, осложнённого неадекватной, вероятно авторитарно-непоследовательной, тактикой воспитания. Задача родителей не «сломать» ребёнка, а помочь ему пройти кризис, сохранив его самостоятельность и научив его соблюдать разумные границы.");
h2("Рекомендации родителям");
b("**Сократите число запретов.** Оставьте немного правил, касающихся безопасности и уважения к людям (нельзя бить, нельзя трогать плиту, нельзя выбегать на дорогу), и соблюдайте их всегда, оба родителя одинаково.",
  "**Давайте выбор вместо приказа:** «Ты будешь есть из синей или из зелёной тарелки?», «Сначала уберём машинки или кубики?». Ребёнок удовлетворяет потребность в самостоятельности, а действие всё равно выполняется.",
  "**Формулируйте правила позитивно:** не «не рви книжку», а «книжки мы листаем аккуратно». Ценные книги временно уберите, а для «разрывания» дайте старые журналы или бумагу — потребность в разрушительных действиях в этом возрасте естественна.",
  "**Превращайте обязанности в игру:** игрушки «идут спать в свой домик», уборка — соревнование «кто быстрее». Убирайте сначала вместе с ребёнком, постепенно уменьшая свою долю.",
  "**Совместный обед:** не заставляйте силой есть и сидеть. Приглашайте спокойно; если ребёнок ушёл из-за стола — еда убирается до следующего приёма пищи (без упрёков и перекусов). Это естественное последствие, а не наказание.",
  "**Агрессия:** спокойно и твёрдо останавливайте руку ребёнка, назовите его чувство и правило: «Ты злишься, потому что я не разрешила. Злиться можно, бить маму — нельзя». Предложите допустимые способы выплеснуть злость: потопать, побить подушку, порвать бумагу.",
  "**Не реагируйте бурно на истерики:** не кричите, не уступайте и не стыдите. Оставайтесь рядом, дождитесь, пока ребёнок успокоится, и только потом поговорите.",
  "**Поощряйте самостоятельность:** позвольте одеваться, наливать воду, помогать по хозяйству, даже если это медленно и неаккуратно. Хвалите за усилия.",
  "**Обеспечьте выход энергии:** ежедневные прогулки, подвижные игры, спортивный уголок дома.",
  "**Будьте примером:** ребёнок копирует поведение родителей. Если взрослые кричат и шлёпают, он учится тому же.");
h2("Связь с темой курса");
p("Жёсткое подавление автономии в период кризиса трёх лет формирует внешний локус контроля, неуверенность и привычку подчиняться чужой воле — черты, которые в дальнейшем являются почвой для созависимого поведения. Вседозволенность, напротив, лишает ребёнка навыков саморегуляции и переносимости запретов, что повышает риск аддиктивного поведения. Оптимальна позиция «тепло + последовательные границы».");
brk();

// ---------------- ЗАДАЧА 2 ----------------
h1("Задача 2. «Нехорошее» слово");
cond("Девочка 3 лет пришла из детского садика и сказала своему любимому, намного старшему брату (20 лет) «нехорошее» слово, которое услышала от кого-то из сверстников. Брат «опешил», в смятении… Как ему психологически правильно себя повести по отношению к своей маленькой, но неделикатной сестрёнке?");
h2("Анализ ситуации");
p("В три года идёт бурное развитие речи. Ребёнок активно копирует услышанные слова, часто **не понимая их смысла**. Он замечает, что некоторые слова вызывают сильную реакцию у окружающих, и это делает их особенно привлекательными: девочка, скорее всего, «проверяет» реакцию брата — значимого и любимого взрослого. Злого умысла здесь нет, это обычное речевое и социальное экспериментирование.");
p("Главное, что определит дальнейшее, — **реакция взрослого**. Если слово вызовет смех, бурное возмущение, крик или испуг, ребёнок запомнит, что это «волшебное» слово, которое привлекает внимание, и будет повторять его.");
h2("Рекомендации брату");
b("**Сохранить спокойствие.** Не показывать шока, не смеяться (даже если смешно) и не кричать. Сделать паузу, если нужно собраться с мыслями.",
  "**Коротко и спокойно обозначить правило:** «Это некрасивое слово. Им можно обидеть человека. Мы в нашей семье так не говорим». Без длинных нотаций и стыжения.",
  "**Можно спокойно спросить:** «Где ты его услышала? Как ты думаешь, что оно значит?» Это поможет понять ситуацию в садике и показать, что с братом можно говорить обо всём.",
  "**Предложить замену:** весёлое «ругательное» слово для моментов, когда сестра сердится («Ёлки-палки!», «Тысяча чертей!»). Ребёнку нужен способ выразить эмоции.",
  "**Если слово повторяется ради реакции** — переключить внимание на другое занятие и не давать эмоционального отклика.",
  "**Сохранить тёплый контакт:** не отстраняться и не обижаться. Девочка должна понимать, что осуждается слово, а не она сама.",
  "**Сообщить родителям** (спокойно, не как «жалобу»), чтобы все взрослые реагировали одинаково, а при необходимости — поговорить с воспитателем.",
  "**Следить за собственной речью:** для младшей сестры старший брат — образец, и его пример важнее любых запретов.");
brk();

// ---------------- ЗАДАЧА 3 ----------------
h1("Задача 3. Загруженность пятилетней девочки");
cond("Одинокая мама испытывает сомнения в правильности воспитания своей 5-летней дочери. Девочка посещает школу бальных танцев, учится рисованию, изучает английский язык и курсы подготовки к школе. Причём занимается везде с удовольствием. У мамы нет возможности водить ребёнка на занятия, поэтому её сопровождает бабушка, которая жалуется на слишком сильную загруженность девочки серьёзными занятиями. Мама просит дать рекомендации по дальнейшему развитию ребёнка, в частности по соответствию нагрузки возрасту.");
h2("Анализ ситуации");
p("Пять лет — **старший дошкольный возраст**. Ведущая деятельность — сюжетно-ролевая игра; именно в ней развиваются воображение, произвольность поведения, умение общаться и подчиняться правилам. Учебная деятельность ещё не является ведущей.");
p("**Положительные стороны:** девочка занимается с удовольствием, направления разнообразны и сочетают двигательную (танцы), творческую (рисование) и интеллектуальную (английский, подготовка к школе) активность. Мама заботится о развитии дочери.");
p("**Риски:** четыре регулярных направления плюс детский сад могут вытеснить свободную игру, прогулки и отдых; возможно накопление утомления, которое ребёнок пока не осознаёт. Важно учитывать мнение бабушки: она проводит с девочкой больше времени и видит её состояние после занятий. Стоит также задуматься о мотивах мамы: одинокие родители нередко компенсируют чувство вины за нехватку времени насыщенной программой «развития».");
p("**Заключение:** сама по себе нагрузка не обязательно чрезмерна, но требует проверки по объективным признакам и, скорее всего, корректировки в пользу свободного времени и игры.");
h2("Рекомендации маме");
b("**Оцените состояние дочери** по признакам переутомления: капризность и плаксивость к вечеру, нарушения сна и аппетита, частые простуды, головные боли, потеря интереса к занятиям, появление тиков или навязчивых движений. При их наличии нагрузку нужно снижать.",
  "**Сверьтесь с возрастными нормами.** Для детей 5–6 лет одно организованное занятие по санитарным нормам не должно превышать 25 минут, между занятиями нужны перерывы. Занятия в кружках по 45–60 минут подряд для пятилетнего ребёнка — большая нагрузка.",
  "**Оставьте 2–3 направления** (например, танцы и рисование, а подготовку к школе — в игровой форме), чтобы в неделе были свободные дни.",
  "**Ежедневно сохраняйте время для свободной игры** и прогулки на свежем воздухе (3–4 часа), полноценный сон 10–11 часов.",
  "**Подготовка к школе — через игру:** развивающие настольные игры, игры с правилами, чтение, рисование, а не «уроки».",
  "**Спросите саму девочку,** что ей нравится больше всего, от чего она устаёт.",
  "**Прислушайтесь к бабушке** и поблагодарите её: она важный ресурс семьи. Договоритесь об общем распорядке, чтобы бабушка не перегружалась сама.",
  "**Проводите с дочерью «качественное» время:** совместные игры, прогулки, разговоры в выходные. Для ребёнка близость с мамой важнее количества кружков.",
  "**Не превращайте занятия в гонку за результатом:** хвалите за интерес и старание, а не за победы и оценки.");
h2("Связь с темой курса");
