const fs = require('fs');
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, LevelFormat,
  ShadingType, BorderStyle, Table, TableRow, TableCell, WidthType, Footer, PageNumber } = require('docx');
const F = "Times New Roman";
function runs(text, extra = {}) {
  return text.split(/(\*\*[^*]+\*\*)/g).filter(Boolean).map(p => p.startsWith('**')
    ? new TextRun({ text: p.slice(2, -2), bold: true, font: F, ...extra })
    : new TextRun({ text: p, font: F, ...extra }));
}
const out = [];
const h1 = t => out.push(new Paragraph({ heading: HeadingLevel.HEADING_1, children: runs(t) }));
const h2 = t => out.push(new Paragraph({ heading: HeadingLevel.HEADING_2, children: runs(t) }));
const p = t => out.push(new Paragraph({ alignment: AlignmentType.JUSTIFIED, indent: { firstLine: 567 },
  spacing: { after: 100, line: 320 }, children: runs(t) }));
const b = (...ts) => ts.forEach(t => out.push(new Paragraph({ numbering: { reference: "bul", level: 0 },
  alignment: AlignmentType.JUSTIFIED, spacing: { after: 60, line: 320 }, children: runs(t) })));
const n = (ref, ...ts) => ts.forEach(t => out.push(new Paragraph({ numbering: { reference: ref, level: 0 },
  alignment: AlignmentType.JUSTIFIED, spacing: { after: 60, line: 320 }, children: runs(t) })));
const box = t => out.push(new Paragraph({
  shading: { type: ShadingType.CLEAR, fill: "EEF2F7", color: "auto" },
  border: { left: { style: BorderStyle.SINGLE, size: 18, color: "4A6A94", space: 8 } },
  indent: { left: 200 }, spacing: { before: 120, after: 160, line: 300 }, alignment: AlignmentType.JUSTIFIED,
  children: runs(t) }));
const center = (t, o = {}) => out.push(new Paragraph({ alignment: AlignmentType.CENTER,
  spacing: { after: 40 }, children: runs(t, o) }));

// ---- Шапка
out.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 80 },
  children: runs("КОНСПЕКТ", { size: 32, bold: true }) }));
out.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 80 },
  children: runs("К. Хорни. «Культура и невроз» (1936)", { size: 30, bold: true }) }));
out.push(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 300 },
  children: runs("Хрестоматия «Психология личности», с. 97–104. Дисциплина «Психология аддиктивного поведения и созависимости»", { italics: true, size: 24 }) }));

h1("Об авторе");
p("**Карен Хорни** (1885–1952) — немецко-американский психоаналитик, одна из ведущих представительниц неофрейдизма. Родилась в Германии, в 1932 г. переехала в США. Критиковала ряд положений Фрейда, но не отказывалась от психоанализа, а стремилась «усовершенствовать» его: заменить биологическую ориентацию социальной и культурной.");
p("Центральное понятие её теории — **базальная (изначальная) тревога**: переживаемое личностью чувство одиночества и беспомощности во враждебном мире. Источник этой тревоги Хорни видела в особенностях общественных отношений «западной цивилизации».");
p("Основные работы: «Невротическая личность нашего времени» (1937), «Новые пути в психоанализе» (1939), «Самоанализ» (1942), «Наши внутренние конфликты» (1945), «Невроз и развитие личности» (1950).");

h1("Исходные положения статьи");
b("В психоаналитическом понимании неврозов произошло **смещение акцентов**: от картины симптомов — к характеру. Истинная причина неврозов — **нарушения характера**; симптомы — результат конфликтующих черт характера. Без раскрытия и коррекции невротической структуры характера невроз вылечить нельзя.",
  "При всём разнообразии симптомов трудности характера у разных невротиков **сосредоточены вокруг одних и тех же базовых конфликтов**.",
  "Это сходство ставит вопрос: **не формируются ли неврозы процессами культуры** подобно «нормальным» образованиям характера? Если да, то это требует пересмотреть взгляды Фрейда на связь культуры и невроза.",
  "Автор стремится показать, как невротик попадает в **порочный круг**, и начинает с ключевой проблемы — **соперничества**.");

// ---- Часть 1
h1("I. Невротический механизм соперничества");
p("Соперничество — **неисчезающий центр невротических конфликтов**. Оно создаёт трудности каждому человеку в нашей культуре, но у невротика эти трудности достигают несравнимых размеров.");

h2("1. Три аспекта невротического соперничества");
n("n1",
  "**Постоянное сравнение себя с другими** — даже в ситуациях, которые этого не требуют. Невротик соревнуется и с людьми, у которых нет с ним общих целей и которые никак не могут быть его соперниками.",
  "**Стремление быть лучше всех.** Невротику мало сделать что-то стоящее: он должен превзойти всех. Эти притязания существуют в основном в фантазиях (осознанно или неосознанно) и **не подкреплены адекватными усилиями**, которые могли бы привести к их реализации. Отсюда: повышенная чувствительность к критике, подавленность или заторможенность после неудачи. **Любая неудача переживается как полный провал, а чужой успех — как собственная неудача.** Соперничество идёт и во внутреннем плане — с **идеальным Я**: к себе предъявляются чрезмерные и жёсткие требования, невыполнение которых вызывает подавленность и раздражение.",
  "**Враждебность.** Сильное соперничество скрыто содержит враждебность: **поражение соперника означает собственную победу**. Невротиком движет ненасытное ожидание, что никто, кроме него, не может быть умным, влиятельным, привлекательным, популярным (установка **«никто, кроме меня»**). Чужие достижения обесценивают его собственные старания. В психоанализе такой пациент воспринимает свой прогресс как «победу аналитика» и сопротивляется лечению, хотя оно в его интересах. Сам пациент эту установку, как правило, не осознаёт.");

h2("2. Страх возмездия и отказ от целей");
p("Враждебная установка порождает **страх возмездия**. Логика невротика: если я желаю уничтожить каждого, кто добился успеха, то и другие желают того же мне. Отсюда страх вызывает уже не только неудача, но и **успех**: путь к успеху грозит враждебностью окружающих, а малейшая неудача — уничтожением.");
p("В итоге **успех становится рискованным, а неудача — опасностью, которой надо избежать любой ценой**. Безопаснее оставаться в стороне, быть скромным и незаметным. Страх ведёт к **отказу от целей** — и этот отказ обеспечивается работой **процесса самоудерживания**.");

h2("3. Самоудерживание и самоуничижение");
b("**Самоудерживание** приводит к **заторможенности**, особенно в работе, и мешает любым шагам к цели: использовать свои возможности, показывать другим свои способности. Человек оказывается **неспособен бороться за собственные желания**, хотя может успешно бороться **за интересы других**.",
  "**Примеры из статьи:** играя с более слабым партнёром, такой человек невольно начинает играть хуже его; в разговоре с менее осведомлённым собеседником опускается до его уровня; предпочитает оставаться рядовым, даже в ущерб заработку, и придумывает рациональные объяснения. Даже в сновидениях он видит себя скромным и униженным, а не преуспевающим.",
  "**Самоуничижение** подрывает уверенность в себе — необходимое условие любого достижения — и тем самым **отстраняет человека от соперничества**. Сам человек этого обычно не осознаёт и видит только результат: он чувствует себя ниже других и считает это доказательством своей неполноценности.");

h2("4. Чувство неполноценности");
b("Хорни называет чувство неполноценности **одним из самых распространённых психических нарушений нашего времени и культуры**.",
  "Оно может иметь разные причины, но **всегда связано с отказом от соперничества и служит этой цели**: чувство неполноценности порождено отказом от соперничества в той мере, в какой оно выражает **разрыв между высокими идеалами и реальными достижениями**.",
  "О его защитной функции говорит то, как энергично невротик отстаивает свою неполноценность: никакие доказательства его способностей не убеждают, а попытки разубедить вызывают испуг или раздражение.");
p("**Внешние варианты проявления:**");
b("одни убеждены в своей исключительности и подчёркивают превосходство, но выдают неуверенность **крайней чувствительностью** к критике, несогласию, отсутствию восхищения;",
  "другие убеждены в своей никчёмности, но выдают скрытые большие притязания **открытой или скрытой враждебностью** к каждому препятствию;",
  "третьи **колеблются** между ощущением своей сверхважности и искренним удивлением, что на них вообще обращают внимание.");

h2("5. Порочный круг");
p("Хорни подчёркивает: невротические процессы нельзя упрощать до линейных «причина → следствие»; они образуют круг, в котором каждое звено усиливает остальные.");
n("n2",
  "Неудачи и переживание собственной слабости → **зависть** к более удачливым и уверенным.",
  "Зависть может проявляться открыто, подавляться тревожностью, вытесняться и проявляться в замещённом виде (**слепое восхищение**, **пренебрежение** к людям, неспособность желать другим того, в чём себе отказываешь).",
  "Зависть, явная или подавленная, усиливает **враждебность** к людям и, следовательно, **тревожность**.",
  "Тревожность принимает форму **иррационального страха чужой зависти**. Его иррациональность двоякая: он существует **независимо от реальной ситуации** и **несоразмерен** реальной опасности. Поскольку страх не вполне осознаётся, он не корректируется реальностью.",
  "Страх ещё больше укрепляет **установку на отказ от соперничества**.",
  "Растут чувство своей незначительности, враждебность и тревожность → появляются **фантазии** о превосходстве и мести («быть сильнее, умнее… разгромить их») → нарастают жестокость, фанатичность, враждебность.");
p("Процесс может приостановиться, но обычно ценой **утраты чувства реальности и жизненности**: отказ от притязаний снижает тревожность, но чувство неполноценности и заторможенность сохраняются.");

h2("6. Почему возникает тревожность: конфликт власти и любви");
p("Притязания «никто, кроме меня» сами по себе не всегда вызывают тревогу. Решающее условие: **эти люди одновременно хотят, чтобы их любили**. Невротик с установкой на соперничество обнаруживает **безграничную жажду любви и уважения**. Как только он делает шаг к самоутверждению, соперничеству или успеху, он начинает бояться утратить расположение окружающих и вынужден непроизвольно сдерживать свои агрессивные импульсы.");
box("**Конфликт между притязаниями и желанием любви и привязанности** — одна из наиболее типичных и тяжёлых дилемм невротика нашего времени. Оба стремления имеют **общий источник — тревожность** и служат **средством её снятия**: и власть, и привязанность обещают безопасность. Поэтому они порождают друг друга.");
p("**Истоки в истории жизни:** отсутствие теплоты и безопасности в детстве; ссоры между родителями, несправедливость, жестокость, **сверхопека** — всё это порождает **усиленную потребность в привязанности**. Её неудовлетворение ведёт к разочарованиям, затем — к откровенному соперничеству или к заторможенности, которая заканчивается **попытками найти привязанность через слабость, беспомощность, страдание**.");
p("Сильная **потребность в успокаивающей привязанности** особенно характерна для тех, у кого в раннем детстве **экспансивные и агрессивные желания подавлялись строгими запретами**. В поведении это проявляется так:");
b("уступки желаниям и мнению других вместо отстаивания своих;",
  "**переоценка значимости любви** окружающих и **зависимость** от её проявлений;",
  "переоценка признаков отвержения и реакция на них опасением и защитной враждебностью.");
p("**Схема порочного круга (по Хорни):**");
["Тревожность плюс подавленная враждебность", "↓", "Потребность в успокаивающей привязанности", "↓",
 "Предвосхищение отвержения, чувствительность к нему", "↓", "Враждебные реакции на переживание отвержения", "↺ (снова усиливают тревожность)"]
  .forEach(t => center(t, t.length > 2 && !t.startsWith('↺') ? { bold: true } : { color: "4A6A94" }));
p("Эмоциональный контакт, основанный на тревожности, — лишь **«шаткий мост»** к людям: он не выводит из эмоциональной изоляции. Он может помогать справляться с тревогой и прожить жизнь довольно гладко, но ценой отказа от развития личности и только при благополучных внешних обстоятельствах.");

// ---- Часть 2
h1("II. Как социальные ценности приводят к внутреннему противоречию");
h2("1. Культура соперничества и индивидуализма");
p("Отвечая на вопрос, какие свойства культуры порождают описанные невротические структуры, Хорни утверждает: **мы живём в культуре соперничества и индивидуализма**. Соперничество — не только движущая сила экономики: оно **пронизывает всю личную жизнь**, и характер всех человеческих отношений формируется более или менее открытым соперничеством:");
b("в семье и в отношениях между родственниками;",
  "в школе;",
  "в социальных отношениях («не отставать от Джонсов»);",
  "**в любви** — эротическое желание замещается целями соперничества: быть самым популярным, иметь больше свиданий и поклонников; супруги могут всю жизнь бороться за лидерство, не осознавая этого.");

h2("2. Последствия соперничества для отношений");
b("Соперничество порождает **зависть к сильным, презрение к слабым, недоверие ко всем**.",
  "Из-за этих враждебных установок ограничивается возможность получать удовлетворение и уверенность, которые обычно дают человеческие отношения; индивид становится **эмоционально изолированным**.",
  "Возникает **взаимное подкрепление**: неуверенность и неудовлетворённость в отношениях вынуждают искать удовлетворение и безопасность в **высоких притязаниях**, а те ещё больше усиливают соперничество.");

h2("3. Культурное отношение к успеху и неудаче");
p("Культура связывает успех с **положительными личными качествами** (умелость, смелость, предприимчивость), а религия — с «божьей милостью». Такая идеология игнорирует два существенных факта:");
n("n3",
  "**возможность успеха строго ограничена**: даже при равных условиях и качествах лишь немногие могут его добиться;",
  "**решающую роль могут сыграть другие факторы** — например, недобросовестность или случайные обстоятельства.");
p("Поэтому неудача не только ставит человека в невыгодное положение, но и **бьёт по его самооценке**: неуспех воспринимается как доказательство личной несостоятельности.");

h2("4. Двойственная мораль — источник внутреннего противоречия");
p("Запутанность ситуации усиливается **двойственной моралью** культуры: успехом восхищаются почти независимо от средств, которыми он достигнут, но одновременно скромность и бескорыстие считаются социальными и религиозными добродетелями и вознаграждаются похвалой и признанием.");
box("**Суть противоречия:** чтобы соперничать, человек должен обладать изрядной долей **агрессивности**, и в то же время от него требуются **скромность, бескорыстие и даже самопожертвование**.");

// table
const W = [4677, 4678];
const cell = (t, head) => new TableCell({ width: { size: head ? W[0] : W[0], type: WidthType.DXA },
  shading: head ? { type: ShadingType.CLEAR, fill: "DCE4EF", color: "auto" } : undefined,
  margins: { top: 80, bottom: 80, left: 120, right: 120 },
  children: [new Paragraph({ children: runs(t, { size: 26, bold: !!head }) })] });
const rows = [
  ["Культура требует…", "…и одновременно требует"],
  ["Соперничать, добиваться успеха, быть агрессивным и напористым", "Быть скромным, бескорыстным, жертвовать собой"],
  ["Восхищается успехом независимо от средств", "Вознаграждает похвалой за скромность и альтруизм"],
  ["Оценивать ценность личности по её успеху", "При этом успех ограничен и часто зависит от случая"],
  ["Соперничество усиливает потребность в безопасности (любви, дружбе)", "Но то же соперничество разрушает возможность найти безопасность в отношениях"],
];
out.push(new Table({ width: { size: 9355, type: WidthType.DXA }, columnWidths: W,
  rows: rows.map((r, i) => new TableRow({ tableHeader: i === 0, children: [cell(r[0], i === 0), cell(r[1], i === 0)] })) }));
out.push(new Paragraph({ spacing: { after: 120 }, children: [] }));
p("Таким образом, ситуация соперничества с её враждебными тенденциями **увеличивает потребность в безопасности**, а возможности обрести эту безопасность в любви, дружбе, социальных контактах **уменьшаются**. Оценка личной ценности слишком зависит от успеха, хотя успех ограничен и во многом случаен.");
p("**Связь с неврозом:** противоречивые культурные требования «нормальный» человек как-то сглаживает, а невротик переживает их в предельно обострённой форме. Конфликт **«притязания на превосходство ↔ жажда любви и одобрения»** — это внутреннее отражение культурного конфликта **«агрессивное соперничество ↔ мораль скромности и бескорыстия»**. Невротик, по Хорни, — это человек, в котором противоречия культуры проявились наиболее ярко.");

h1("Выводы");
n("n4",
  "Причина неврозов — в нарушениях структуры характера, а базовые невротические конфликты сходны у разных людей, потому что **формируются культурой**.",
  "Центральный невротический конфликт — **соперничество**: постоянное сравнение, фантастическое стремление быть лучше всех, скрытая враждебность.",
  "Враждебность порождает **страх возмездия**, страх — **отказ от целей**, самоудерживание, самоуничижение и **чувство неполноценности**, которые замыкаются в порочный круг через зависть, враждебность и тревожность.",
  "Тревожность возникает из-за конфликта **притязаний на власть и потребности в любви**; оба стремления — способы снять базальную тревогу.",
  "Культура соперничества и индивидуализма, идеализация успеха и **двойственная мораль** (агрессивность + скромность) создают **внутреннее противоречие**, которое в обострённой форме переживает невротическая личность.");

h1("Связь с темой курса");
p("Положения Хорни помогают понять психологические основы **созависимости и аддиктивного поведения**:");
b("**Потребность в успокаивающей привязанности** — уступки чужим желаниям, переоценка любви, зависимость от одобрения и страх отвержения — по сути описывает **созависимую личность**.",
  "**Поиск привязанности через слабость, беспомощность и страдание** напоминает роль «жертвы» в созависимых отношениях.",
  "Истоки — **отсутствие теплоты в детстве, ссоры родителей, жестокость, сверхопека, подавление желаний ребёнка** — совпадают с типичными характеристиками дисфункциональных, в том числе аддиктивных, семей.",
  "**Перфекционизм и соперничество с идеальным Я**, оценка себя только по успеху — почва для **трудоголизма** и других социально одобряемых аддикций; а невыносимая тревога и чувство неполноценности могут «сниматься» с помощью психоактивных веществ.");

const doc = new Document({
  styles: {
    default: { document: { run: { font: F, size: 28 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: F, size: 30, bold: true, color: "1F3A5F" },
        paragraph: { spacing: { before: 320, after: 160 }, keepNext: true, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { font: F, size: 28, bold: true, color: "2E5A8A" },
        paragraph: { spacing: { before: 200, after: 100 }, keepNext: true, outlineLevel: 1 } },
    ],
  },
  numbering: { config: [
    { reference: "bul", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
      style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] },
    ...["n1", "n2", "n3", "n4"].map(r => ({ reference: r, levels: [{ level: 0, format: LevelFormat.DECIMAL, text: "%1)",
      alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 720, hanging: 360 } } } }] })),
  ] },
  sections: [{
    properties: { page: { size: { width: 11906, height: 16838 }, margin: { top: 1134, bottom: 1134, left: 1701, right: 850 } } },
    footers: { default: new Footer({ children: [new Paragraph({ alignment: AlignmentType.CENTER,
      children: [new TextRun({ children: [PageNumber.CURRENT], font: F, size: 24 })] })] }) },
    children: out,
  }],
});
Packer.toBuffer(doc).then(buf => fs.writeFileSync("Конспект_Хорни_Культура_и_невроз.docx", buf));

content.text:
Конспект «Конспект_Хорни_Культура_и_невроз.docx» готов, 7 страниц, шрифт Times New Roman 14. Конспект сделан по страницам 97–104 с ваших фото.

Обе нужные темы вынесены в отдельные разделы:

- **I. Невротический механизм соперничества:**
  - три аспекта соперничества: постоянное сравнение с другими, стремление быть лучше всех, враждебность («никто, кроме меня»);
  - страх возмездия и отказ от целей;
  - самоудерживание и самоуничижение;
  - чувство неполноценности;
  - порочный круг «зависть → враждебность → тревожность»;
  - конфликт между стремлением к власти и потребностью в любви, со схемой Хорни.
- **II. Как социальные ценности приводят к внутреннему противоречию:**
  - культура соперничества и индивидуализма;
  - как соперничество влияет на отношения;
  - культурное отношение к успеху и неудаче;
  - двойственная мораль: от человека требуют агрессивности и одновременно скромности. Это противоречие сведено в таблицу «культура требует… и одновременно требует…».

В конце есть короткие выводы и абзац о связи с темой курса. Там показано, что описанная Хорни «потребность в успокаивающей привязанности» по сути описывает созависимую личность.

На первом фото слева — окончание предыдущей статьи, про барьеры и наказания, она не про Хорни. Её в конспект я не включал.

