const refs=[];
const box=t=>o.push(new Paragraph({shading:{type:ShadingType.CLEAR,fill:"EEF2F7",color:"auto"},border:{left:{style:BorderStyle.SINGLE,size:18,color:"4A6A94",space:8}},indent:{left:200},spacing:{before:80,after:120,line:300},alignment:AlignmentType.JUSTIFIED,children:runs(t)}));
