      self.refreshtable()
      messagebox.showinfo("Успех", f"Запись с ID {rid} успешно обновлена!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guideleterecord(self):
    selected = self.tree.selection()
    if not selected:
      rid = self.entries["id"].get().strip()
      if not rid:
        messagebox.showwarning("Внимание", "Выберите строку в таблице или введите ID в поле для удаления!")
