    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guisearch(self):
    query = (
        self.entries["name"].get().strip()
        or self.entries["id"].get().strip()
        or self.entries["muscle"].get().strip()
        or self.entries["load"].get().strip()
    )
    if not query:
      messagebox.showwarning("Внимание", "Заполните хотя бы одно поле для поиска!")
      return

    results = self.db.search(query)
    for row in self.tree.get_children():
      self.tree.delete(row)
    for record in results:
      self.tree.insert("", "end", values=record)
    messagebox.showinfo("Результаты", f"Найдено записей: {len(results)}")

  def guiopendb(self):
    chosenfile = filedialog.askopenfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
