import csv
import math
import os
import shutil
from collections import defaultdict

DEFAULT_DB = "workout.dat"
SEP = "|"
FIELDS = ("id", "name", "muscle", "load")
TEXT_FIELDS = ("name", "muscle")
TITLES = {
    "id": "ID (ключ)",
    "name": "Название упражнения",
    "muscle": "Группа мышц",
    "load": "Нагрузка (кг)",
}
AUTO_COMPACT_MIN = 1000  # автосжатие файла, если «мёртвых» строк >= этого числа и их больше, чем живых


class DatabaseError(Exception):
    """Ошибка работы с БД (показывается пользователю как есть)."""


# ---------------------------------------------------------------- проверка данных
def _format_float(value):
    return str(int(value)) if value.is_integer() else repr(value)


def canonical(field, raw):
    """Проверяет значение поля и приводит его к каноническому текстовому виду."""
    raw = str(raw).strip()
    if not raw:
        raise DatabaseError(f"Поле «{TITLES[field]}» не заполнено")
    if field == "id":
        try:
            number = int(raw)
        except ValueError:
            raise DatabaseError("ID должен быть целым числом") from None
        if number <= 0:
            raise DatabaseError("ID должен быть положительным числом")
        return str(number)
    if field == "load":
        try:
            number = float(raw.replace(",", "."))
        except ValueError:
            raise DatabaseError("Нагрузка должна быть числом (например, 52.5)") from None
        if not math.isfinite(number) or not 0 <= number <= 1000:
            raise DatabaseError("Нагрузка должна быть в диапазоне от 0 до 1000 кг")
        return _format_float(number)
    if SEP in raw or "\n" in raw or "\r" in raw:
        raise DatabaseError(f"Поле «{TITLES[field]}» содержит недопустимый символ «{SEP}» или перевод строки")
    return raw


def _key(field, value):
    """Ключ вторичного индекса: текстовые поля сравниваются без учёта регистра."""
    return value.casefold() if field in TEXT_FIELDS else value


def _search_key(field, raw):
    if field in TEXT_FIELDS:
        raw = str(raw).strip()
        if not raw:
            raise DatabaseError("Введите значение для поиска")
        return raw.casefold()
    return canonical(field, raw)


def _parse(body):
    return tuple(body.decode("utf-8").split(SEP)[:4])


# ---------------------------------------------------------------- сама БД
class FileDatabase:
    def __init__(self):
        self.filename = None
        self.index = {}
        self.secondary = {field: defaultdict(set) for field in FIELDS[1:]}
        self.deleted_count = 0

    # --- служебное
    @property
    def is_open(self):
        return self.filename is not None

    @property
    def backup_path(self):
        return None if self.filename is None else self.filename + ".bak"

    def __len__(self):
        return len(self.index)

    def _require_open(self):
        if not self.is_open:
            raise DatabaseError("База данных не открыта. Создайте или откройте файл БД (меню «БД»).")

    def _reset(self):
        self.index.clear()
        for table in self.secondary.values():
            table.clear()
        self.deleted_count = 0

    def _index_add(self, record, pos):
        self.index[record[0]] = pos
        for field, value in zip(FIELDS[1:], record[1:]):
            self.secondary[field][_key(field, value)].add(record[0])

    def _index_remove(self, record):
        del self.index[record[0]]
        for field, value in zip(FIELDS[1:], record[1:]):
            table = self.secondary[field]
            bucket = table[_key(field, value)]
            bucket.discard(record[0])
            if not bucket:
                del table[_key(field, value)]

    def _load_index(self):
        """Один последовательный проход по файлу: O(n). Выполняется при открытии."""
        self._reset()
        last = b""
        try:
            with open(self.filename, "rb") as f:
                pos = 0
                for number, raw in enumerate(f, 1):
                    start, pos, last = pos, pos + len(raw), raw
                    body = raw.rstrip(b"\r\n")
                    if not body.strip():
                        continue
                    parts = body.decode("utf-8").split(SEP)
                    if len(parts) != 5 or parts[4] not in ("0", "1"):
                        raise DatabaseError(f"Файл не является БД: неверная строка {number}")
                    if parts[4] == "1":
                        self.deleted_count += 1
                        continue
                    if parts[0] in self.index:
                        raise DatabaseError(f"Файл повреждён: повторяется ID {parts[0]} (строка {number})")
                    self._index_add(tuple(parts[:4]), start)
        except UnicodeDecodeError:
            self._reset()
            raise DatabaseError("Файл не является БД: неверная кодировка (нужна UTF-8)") from None
        except DatabaseError:
            self._reset()
            raise
        if last and not last.endswith(b"\n"):  # чиним файл, отредактированный вручную
            with open(self.filename, "ab") as f:
                f.write(b"\n")

    # --- создание / открытие / сохранение / удаление / очистка БД
    def create(self, path):
        with open(path, "wb"):
            pass
        self.filename = path
        self._reset()

    def open(self, path, create=False):
        if not os.path.exists(path):
            if not create:
                raise DatabaseError(f"Файл не найден: {path}")
            self.create(path)
            return
        previous = self.filename
        self.filename = path
        try:
            self._load_index()
        except (DatabaseError, OSError):
            self.filename = previous
            if previous:
                self._load_index()
            raise

    def _write_compacted(self, dest):
        tmp = dest + ".tmp"
        with open(self.filename, "rb") as src, open(tmp, "wb") as out:
            for raw in src:
                body = raw.rstrip(b"\r\n")
                if body and not body.endswith(SEP.encode() + b"1"):
                    out.write(body + b"\n")
        os.replace(tmp, dest)

    def save(self):
        """Сохранение: физически убирает помеченные удалёнными строки."""
        self._require_open()
        self._write_compacted(self.filename)
        self._load_index()

    def save_as(self, path):
        self._require_open()
        self._write_compacted(path)
        self.filename = path
        self._load_index()

    def clear(self):
        self._require_open()
        with open(self.filename, "wb"):
            pass
        self._reset()

    def delete_db(self):
        self._require_open()
        os.remove(self.filename)
        self.filename = None
        self._reset()

    # --- backup
    def create_backup(self):
        self._require_open()
        shutil.copy2(self.filename, self.backup_path)
        return self.backup_path

    def restore_backup(self):
        self._require_open()
        if not os.path.exists(self.backup_path):
            raise DatabaseError(f"Бэкап-файл не найден: {self.backup_path}")
        shutil.copy2(self.backup_path, self.filename)
        self._load_index()

    # --- записи
    def _validate(self, rid, name, muscle, load):
        return tuple(canonical(f, v) for f, v in zip(FIELDS, (rid, name, muscle, load)))

    def _append(self, record):
        line = (SEP.join(record) + SEP + "0\n").encode("utf-8")
        with open(self.filename, "ab") as f:
            f.seek(0, os.SEEK_END)
            pos = f.tell()
            f.write(line)
        self._index_add(record, pos)

    def add_record(self, rid, name, muscle, load):
        """O(1): проверка уникальности ключа по хеш-индексу + запись в конец файла."""
        self._require_open()
        record = self._validate(rid, name, muscle, load)
        if record[0] in self.index:
            raise DatabaseError(f"Запись с ID {record[0]} уже существует")
        self._append(record)

    def _delete(self, ids):
        removed = 0
        with open(self.filename, "r+b") as f:
            for rid in ids:
                pos = self.index.get(rid)
                if pos is None:
                    continue
                f.seek(pos)
                body = f.readline().rstrip(b"\r\n")
                record = _parse(body)
                f.seek(pos + len(body) - 1)  # последний символ строки - флаг удаления
                f.write(b"1")
                self._index_remove(record)
                self.deleted_count += 1
                removed += 1
        return removed

    def _maybe_compact(self):
        if self.deleted_count >= AUTO_COMPACT_MIN and self.deleted_count > len(self.index):
            self.save()

    def delete_ids(self, ids):
        """Логическое удаление по списку ID: O(k) для k записей."""
        self._require_open()
        removed = self._delete(list(ids))
        self._maybe_compact()
        return removed

    def delete_by(self, field, value, partial=False):
        """Удаление всех записей, у которых поле совпало со значением."""
        return self.delete_ids(self.find_ids(field, value, partial))

    def update_record(self, rid, name, muscle, load):
        self._require_open()
        record = self._validate(rid, name, muscle, load)
        if record[0] not in self.index:
            raise DatabaseError(f"Запись с ID {record[0]} не найдена")
        self._delete([record[0]])
        self._append(record)
        self._maybe_compact()

    def find_ids(self, field, value, partial=False):
        """Точный поиск - O(1) по хеш-индексу; частичный - O(m), m = число различных значений."""
        self._require_open()
        if field not in FIELDS:
            raise DatabaseError(f"Неизвестное поле: {field}")
        if not partial:
            key = _search_key(field, value)
            if field == "id":
                return [key] if key in self.index else []
            return list(self.secondary[field].get(key, ()))
        needle = str(value).strip().casefold()
        if not needle:
            raise DatabaseError("Введите значение для поиска")
        if field == "id":
            return [k for k in self.index if needle in k]
        found = []
        for key, ids in self.secondary[field].items():
            if needle in key:
                found.extend(ids)
        return found

    def _read_records(self, ids):
        positions = sorted(self.index[i] for i in ids if i in self.index)
        records = []
        with open(self.filename, "rb") as f:
            for pos in positions:
                f.seek(pos)
                records.append(_parse(f.readline().rstrip(b"\r\n")))
        records.sort(key=lambda r: int(r[0]))
        return records

    def search(self, field, value, partial=False):
        return self._read_records(self.find_ids(field, value, partial))

    def get_by_id(self, rid):
        found = self._read_records([str(rid)]) if self.is_open else []
        return found[0] if found else None

    def iter_all(self):
        """Последовательное чтение файла (для отображения таблицы на экране)."""
        if not self.is_open:
            return
        with open(self.filename, "rb") as f:
            for raw in f:
                body = raw.rstrip(b"\r\n")
                if body and not body.endswith(SEP.encode() + b"1"):
                    yield _parse(body)

    # --- экспорт в сторонний формат
    def export(self, path):
        self._require_open()
        if path.lower().endswith(".xlsx"):
            return self._export_xlsx(path)
        return self._export_csv(path)

    def _export_csv(self, path):
        count = 0
        with open(path, "w", encoding="utf-8-sig", newline="") as f:
            writer = csv.writer(f, delimiter=";")
            writer.writerow([TITLES[x] for x in FIELDS])
            for record in self.iter_all():
                writer.writerow(record)
                count += 1
        return count

    def _export_xlsx(self, path):
        try:
            from openpyxl import Workbook
        except ImportError:
            raise DatabaseError("Для экспорта в .xlsx установите библиотеку: pip install openpyxl") from None
        book = Workbook()
        sheet = book.active
        sheet.title = "Упражнения"
        sheet.append([TITLES[x] for x in FIELDS])
        count = 0
        for rid, name, muscle, load in self.iter_all():
            sheet.append([int(rid), name, muscle, float(load)])
            count += 1
        book.save(path)
        return count

