"""GUI для файловой БД «Сервис программ тренировок» (лабораторная №2). Запуск: python workout_gui.py"""
import functools
import itertools
import os
import time
import tkinter as tk
from tkinter import filedialog, messagebox, ttk

from workout_db import DEFAULT_DB, FIELDS, TITLES, DatabaseError, FileDatabase

DISPLAY_LIMIT = 5000
DB_TYPES = [("Файлы БД (*.dat)", "*.dat"), ("Все файлы", "*.*")]
MUSCLES = ["Грудь", "Спина", "Ноги", "Плечи", "Бицепс", "Трицепс", "Пресс", "Кардио"]


def guarded(method):
    """Любая ошибка БД/файловой системы показывается окном, а не роняет программу."""
    @functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        try:
            return method(self, *args, **kwargs)
        except (DatabaseError, OSError) as exc:
            messagebox.showerror("Ошибка", str(exc))
    return wrapper


class DatabaseApp:
    def __init__(self, root):
        self.root = root
        self.db = FileDatabase()
        self.status = tk.StringVar()
        root.title("Сервис программ тренировок — файловая БД (лаб. №2)")
        root.geometry("1000x660")
        self._build_menu()
        self._build_widgets()
        self._open_default()
        self.refresh_table()

    # ------------------------------------------------------------ построение окна
    def _build_menu(self):
        menubar = tk.Menu(self.root)
        menu = tk.Menu(menubar, tearoff=0)
        items = [
            ("Создать…", self.gui_create), ("Открыть…", self.gui_open),
            ("Сохранить", self.gui_save), ("Сохранить как…", self.gui_save_as), None,
            ("Создать backup", self.gui_backup), ("Восстановить из backup", self.gui_restore),
            ("Экспорт в CSV / XLSX…", self.gui_export), None,
            ("Очистить БД", self.gui_clear), ("Удалить файл БД", self.gui_delete_db), None,
            ("Выход", self.root.destroy),
        ]
        for item in items:
            if item is None:
                menu.add_separator()
            else:
                menu.add_command(label=item[0], command=item[1])
        menubar.add_cascade(label="БД", menu=menu)
        self.root.config(menu=menubar)

    def _build_widgets(self):
        form = tk.LabelFrame(self.root, text=" Запись ", font=("Arial", 10, "bold"))
        form.pack(fill="x", padx=10, pady=(10, 4))
        self.entries = {}
        layout = [("id", 0, 0), ("name", 0, 2), ("muscle", 1, 0), ("load", 1, 2)]
        for field, row, col in layout:
            tk.Label(form, text=TITLES[field] + ":").grid(row=row, column=col, padx=8, pady=5, sticky="e")
            if field == "muscle":
                widget = ttk.Combobox(form, values=MUSCLES, width=23)
            else:
                widget = tk.Entry(form, width=26)
            widget.grid(row=row, column=col + 1, padx=8, pady=5, sticky="w")
            self.entries[field] = widget

        buttons = tk.Frame(form)
        buttons.grid(row=0, column=4, rowspan=2, padx=12)
        tk.Button(buttons, text="Добавить", bg="#d4edda", width=14, command=self.gui_add).pack(pady=1)
        tk.Button(buttons, text="Править (по ID)", bg="#fff3cd", width=14, command=self.gui_edit).pack(pady=1)
        tk.Button(buttons, text="Очистить поля", width=14, command=self.clear_form).pack(pady=1)

        find = tk.LabelFrame(self.root, text=" Поиск и удаление по значению поля ", font=("Arial", 10, "bold"))
        find.pack(fill="x", padx=10, pady=4)
        tk.Label(find, text="Поле:").pack(side="left", padx=(8, 2), pady=6)
        self.field_box = ttk.Combobox(find, values=[TITLES[f] for f in FIELDS], state="readonly", width=22)
        self.field_box.current(1)
        self.field_box.pack(side="left", padx=4)
        tk.Label(find, text="Значение:").pack(side="left", padx=(10, 2))
        self.value_entry = tk.Entry(find, width=24)
        self.value_entry.pack(side="left", padx=4)
        self.partial_var = tk.BooleanVar(value=False)
        tk.Checkbutton(find, text="частичное совпадение", variable=self.partial_var).pack(side="left", padx=6)
        tk.Button(find, text="Найти", bg="#d1ecf1", width=8, command=self.gui_search).pack(side="left", padx=2)
        tk.Button(find, text="Удалить найденное", bg="#f8d7da", command=self.gui_delete_by_value).pack(side="left", padx=2)
        tk.Button(find, text="Показать все", command=self.refresh_table).pack(side="left", padx=2)

        frame = tk.Frame(self.root)
        frame.pack(fill="both", expand=True, padx=10, pady=(4, 4))
        self.tree = ttk.Treeview(frame, columns=FIELDS, show="headings", selectmode="extended")
        widths = {"id": 90, "name": 320, "muscle": 220, "load": 140}
        for field in FIELDS:
            self.tree.heading(field, text=TITLES[field])
            self.tree.column(field, width=widths[field], anchor="w" if field in ("name", "muscle") else "center")
        scroll = ttk.Scrollbar(frame, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scroll.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scroll.pack(side="right", fill="y")
        self.tree.bind("<<TreeviewSelect>>", self.on_row_select)

        tk.Button(self.root, text="Удалить выбранные строки", bg="#f8d7da",
                  command=self.gui_delete_selected).pack(anchor="w", padx=10, pady=2)
        tk.Label(self.root, textvariable=self.status, anchor="w", relief="sunken").pack(fill="x", side="bottom")

    # ------------------------------------------------------------ вспомогательное
    @guarded
    def _open_default(self):
        self.db.open(DEFAULT_DB, create=True)

    @staticmethod
    def _timed(func, *args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        return result, (time.perf_counter() - start) * 1000

    def _form_values(self):
        return [self.entries[f].get() for f in FIELDS]

    def clear_form(self):
        for widget in self.entries.values():
            widget.delete(0, tk.END)

    def _set_status(self, text=""):
        name = os.path.basename(self.db.filename) if self.db.is_open else "БД не открыта"
        self.status.set(f" {name}  |  записей: {len(self.db)}  |  {text}")

    def _fill_table(self, records):
        self.tree.delete(*self.tree.get_children())
        for record in records:
            self.tree.insert("", "end", iid=record[0], values=record)  # iid = ID (строка, без потери нулей)

    def refresh_table(self):
        shown = list(itertools.islice(self.db.iter_all(), DISPLAY_LIMIT))
        self._fill_table(shown)
        note = f"показаны первые {DISPLAY_LIMIT}" if len(self.db) > DISPLAY_LIMIT else ""
        self._set_status(note)

    def on_row_select(self, _event):
        selected = self.tree.selection()
        if len(selected) != 1:
            return
        record = self.db.get_by_id(selected[0])  # читаем из файла, а не из виджета
        if record:
            self.clear_form()
            for field, value in zip(FIELDS, record):
                self.entries[field].insert(0, value)

    def _field(self):
        return FIELDS[self.field_box.current()]

    # ------------------------------------------------------------ операции с записями
    @guarded
    def gui_add(self):
        _, ms = self._timed(self.db.add_record, *self._form_values())
        self.refresh_table()
        self._set_status(f"запись добавлена за {ms:.3f} мс")

    @guarded
    def gui_edit(self):
        _, ms = self._timed(self.db.update_record, *self._form_values())
        self.refresh_table()
        self._set_status(f"запись изменена за {ms:.3f} мс")

    @guarded
    def gui_delete_selected(self):
        selected = list(self.tree.selection())
        if not selected:
            messagebox.showwarning("Внимание", "Выберите строки в таблице")
            return
        if not messagebox.askyesno("Подтверждение", f"Удалить выбранные записи: {len(selected)}?"):
            return
        count, ms = self._timed(self.db.delete_ids, selected)
        self.refresh_table()
        self._set_status(f"удалено записей: {count} за {ms:.3f} мс")

    @guarded
    def gui_search(self):
        value = self.value_entry.get()
        results, ms = self._timed(self.db.search, self._field(), value, self.partial_var.get())
        self._fill_table(results[:DISPLAY_LIMIT])
        self._set_status(f"найдено записей: {len(results)} за {ms:.3f} мс")

    @guarded
    def gui_delete_by_value(self):
        field, value, partial = self._field(), self.value_entry.get(), self.partial_var.get()
        ids = self.db.find_ids(field, value, partial)
        if not ids:
            messagebox.showinfo("Результат", "Записей с таким значением нет")
            return
        if not messagebox.askyesno("Подтверждение", f"Найдено записей: {len(ids)}. Удалить все?"):
            return
        count, ms = self._timed(self.db.delete_ids, ids)
        self.refresh_table()
        self._set_status(f"удалено записей: {count} за {ms:.3f} мс")

    # ------------------------------------------------------------ операции с БД
    @guarded
    def gui_create(self):
        path = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=DB_TYPES, title="Создать БД")
        if path:
            self.db.create(path)
            self.clear_form()
            self.refresh_table()

    @guarded
    def gui_open(self):
        path = filedialog.askopenfilename(defaultextension=".dat", filetypes=DB_TYPES, title="Открыть БД")
        if path:
            _, ms = self._timed(self.db.open, path)
            self.refresh_table()
            self._set_status(f"БД открыта, индекс построен за {ms:.1f} мс")

    @guarded
    def gui_save(self):
        _, ms = self._timed(self.db.save)
        self.refresh_table()
        self._set_status(f"БД сохранена (файл сжат) за {ms:.1f} мс")

    @guarded
    def gui_save_as(self):
        path = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=DB_TYPES, title="Сохранить как")
        if path:
            self.db.save_as(path)
            self.refresh_table()

    @guarded
    def gui_backup(self):
        path = self.db.create_backup()
        self._set_status(f"backup создан: {path}")

    @guarded
    def gui_restore(self):
        if messagebox.askyesno("Подтверждение", "Заменить текущую БД содержимым backup-файла?"):
            self.db.restore_backup()
            self.refresh_table()
            self._set_status("БД восстановлена из backup")

    @guarded
    def gui_export(self):
        path = filedialog.asksaveasfilename(
            defaultextension=".csv", title="Экспорт",
            filetypes=[("CSV (Excel)", "*.csv"), ("Excel (.xlsx)", "*.xlsx")])
        if path:
            count = self.db.export(path)
            self._set_status(f"экспортировано записей: {count}")

    @guarded
    def gui_clear(self):
        if messagebox.askyesno("Подтверждение", "Полностью очистить базу данных?"):
            self.db.clear()
            self.refresh_table()

    @guarded
    def gui_delete_db(self):
        if messagebox.askyesno("Подтверждение", "Удалить файл БД с диска? Действие необратимо."):
            self.db.delete_db()
            self.clear_form()
            self.refresh_table()


def main():
    root = tk.Tk()
    DatabaseApp(root)
    root.mainloop()


if __name__ == "__main__":
    main()

