import os
import shutil
import tkinter as tk
from tkinter import messagebox, ttk, filedialog

dbname = "workout.dat"
backupname = "workoutbackup.dat"
exportname = "workoutexport.csv"

class filedatabase:
  def __init__(self, filename=dbname):
    self.filename = filename
    self.index = {}
    if not os.path.exists(self.filename):
      self.createnewdb()
    else:
      self.loadindex()

  def createnewdb(self):
    with open(self.filename, "w", encoding="utf-8") as f:
      pass
    self.index = {}

  def newfile(self, newfilename):
    self.filename = newfilename
    self.createnewdb()

  def openfile(self, newfilename):
    self.filename = newfilename
    self.loadindex()

  def cleardb(self):
    with open(self.filename, "w", encoding="utf-8") as f:
      pass
    self.index = {}

  def deletedb(self):
    if os.path.exists(self.filename):
      os.remove(self.filename)
    self.index = {}

  def savedb(self):
    if not os.path.exists(self.filename):
      return
    tmpname = self.filename + ".tmp"
    with open(self.filename, "r", encoding="utf-8") as src, open(tmpname, "w", encoding="utf-8") as dst:
      for line in src:
        parts = line.strip().split("|")
        if len(parts) >= 5 and parts[4] == "0":
          dst.write(line.strip() + "\n")
    os.replace(tmpname, self.filename)
    self.loadindex()

  def loadindex(self):
    self.index = {}
    if not os.path.exists(self.filename):
      return
    with open(self.filename, "r", encoding="utf-8") as f:
      while True:
        pos = f.tell()
        line = f.readline()
        if not line:
          break
        line = line.strip()
        if not line:
          continue
        parts = line.split("|")
        if len(parts) >= 5:
          recordid = parts[0]
          isdeleted = parts[4] == "1"
          if not isdeleted:
            self.index[recordid] = pos

  def getall(self):
    records = []
    if not os.path.exists(self.filename):
      return records
    with open(self.filename, "r", encoding="utf-8") as f:
      for recordid, pos in self.index.items():
        f.seek(pos)
        line = f.readline().strip()
        parts = line.split("|")
        if len(parts) >= 5:
          records.append((parts[0], parts[1], parts[2], parts[3]))
    return records

  def addrecord(self, recordid, name, musclegroup, loadval):
    if recordid in self.index:
      raise ValueError(f"Запись с ID '{recordid}' уже существует!")
    line = f"{recordid}|{name}|{musclegroup}|{loadval}|0\n"

    with open(self.filename, "a", encoding="utf-8") as f:
      f.seek(0, os.SEEK_END)
      pos = f.tell()
      f.write(line)
      self.index[recordid] = pos

  def updaterecord(self, recordid, name, musclegroup, loadval):
    if recordid not in self.index:
      raise ValueError(f"Запись с ID '{recordid}' не найдена!")
    self.deleterecord(recordid)
    self.addrecord(recordid, name, musclegroup, loadval)

  def deleterecord(self, recordid):
    if recordid not in self.index:
      raise ValueError(f"Запись с ID '{recordid}' не найдена!")
    pos = self.index[recordid]
    with open(self.filename, "r+", encoding="utf-8") as f:
      f.seek(pos)
      line = f.readline()
      parts = line.strip().split("|")
      parts[4] = "1"
      f.seek(pos)
      f.write("|".join(parts) + "\n")
    del self.index[recordid]

  def findids(self, fieldindex, value):
    if fieldindex == 0:
      return [value] if value in self.index else []
    ids = []
    if not os.path.exists(self.filename):
      return ids
    with open(self.filename, "r", encoding="utf-8") as f:
      for recordid, pos in self.index.items():
        f.seek(pos)
        parts = f.readline().strip().split("|")
        if parts[fieldindex].lower() == value.lower():
          ids.append(recordid)
    return ids

  def deletebyvalue(self, fieldindex, value):
    ids = self.findids(fieldindex, value)
    for recordid in ids:
      self.deleterecord(recordid)
    return len(ids)

  def search(self, fieldindex, value):
    results = []
    if not os.path.exists(self.filename):
      return results
    ids = self.findids(fieldindex, value)
    with open(self.filename, "r", encoding="utf-8") as f:
      for recordid in ids:
        f.seek(self.index[recordid])
        parts = f.readline().strip().split("|")
        results.append((parts[0], parts[1], parts[2], parts[3]))
    return results

  def createbackup(self):
    shutil.copy(self.filename, backupname)

  def restorebackup(self):
    if os.path.exists(backupname):
      shutil.copy(backupname, self.filename)
      self.loadindex()
    else:
      raise FileNotFoundError("Бэкап-файл не найден!")

  def exporttocsv(self):
    records = self.getall()
    with open(exportname, "w", encoding="utf-8-sig") as f:
      f.write("ID;Название упражнения;Целевая группа мышц;Нагрузка (кг)\n")
      for r in records:
        f.write(f"{r[0]};{r[1]};{r[2]};{r[3]}\n")


class databaseapp:
  def __init__(self, root):
    self.db = filedatabase()
    self.root = root
    self.root.title("База данных: Сервис программ тренировок (Лабораторная №2)")
    self.root.geometry("920x640")

    self.createwidgets()
    self.refreshtable()

  def createwidgets(self):
    inputframe = tk.LabelFrame(self.root, text=" Управление записью ", font=("Arial", 10, "bold"))
    inputframe.pack(fill="x", padx=10, pady=10)

    fieldslayout = [
        ("id", "ID (Ключ):", 0, 0),
        ("name", "Название упражнения:", 0, 2),
        ("muscle", "Группа мышц:", 1, 0),
        ("load", "Нагрузка (кг):", 1, 2)
    ]

    self.entries = {}
    for key, labeltext, r, c in fieldslayout:
      lbl = tk.Label(inputframe, text=labeltext)
      lbl.grid(row=r, column=c, padx=10, pady=6, sticky="e")
      ent = tk.Entry(inputframe, width=25)
      ent.grid(row=r, column=c+1, padx=10, pady=6, sticky="w")
      self.entries[key] = ent

    btnframe = tk.Frame(self.root)
    btnframe.pack(fill="x", padx=10, pady=5)

    tk.Button(btnframe, text="Добавить", bg="#d4edda", command=self.guiaddrecord, width=10).pack(side="left", padx=2)
    tk.Button(btnframe, text="Править", bg="#fff3cd", command=self.guileditrecord, width=9).pack(side="left", padx=2)
    tk.Button(btnframe, text="Удалить", bg="#f8d7da", command=self.guideleterecord, width=9).pack(side="left", padx=2)
    tk.Button(btnframe, text="Поиск", bg="#d1ecf1", command=self.guisearch, width=8).pack(side="left", padx=2)
    tk.Button(btnframe, text="Сброс", command=self.refreshtable, width=8).pack(side="left", padx=2)
    tk.Button(btnframe, text="Экспорт", command=self.guiexport, width=8).pack(side="right", padx=2)
    tk.Button(btnframe, text="Восстановить", command=self.guirestore, width=11).pack(side="right", padx=2)
    tk.Button(btnframe, text="Бэкап", command=self.guibackup, width=7).pack(side="right", padx=2)

    btnframe2 = tk.Frame(self.root)
    btnframe2.pack(fill="x", padx=10, pady=5)

    tk.Label(btnframe2, text="Поле для поиска/удаления:").pack(side="left", padx=2)
    self.fieldkeys = ["id", "name", "muscle", "load"]
    self.fieldbox = ttk.Combobox(btnframe2, values=["ID", "Название", "Группа мышц", "Нагрузка"], state="readonly", width=14)
    self.fieldbox.current(1)
    self.fieldbox.pack(side="left", padx=2)
    tk.Button(btnframe2, text="Удалить по полю", bg="#f8d7da", command=self.guideletebyvalue, width=15).pack(side="left", padx=2)
    tk.Button(btnframe2, text="Создать БД", command=self.guinewdb, width=10).pack(side="left", padx=2)
    tk.Button(btnframe2, text="Открыть", command=self.guiopendb, width=8).pack(side="left", padx=2)
    tk.Button(btnframe2, text="Сохранить", command=self.guisavedb, width=9).pack(side="left", padx=2)
    tk.Button(btnframe2, text="Очистить", bg="#ffcccc", command=self.guicleardb, width=9).pack(side="left", padx=2)
    tk.Button(btnframe2, text="Удалить БД", bg="#ffcccc", command=self.guideletedb, width=10).pack(side="left", padx=2)

    tableframe = tk.Frame(self.root)
    tableframe.pack(fill="both", expand=True, padx=10, pady=10)

    self.tree = ttk.Treeview(tableframe, columns=("ID", "Name", "Muscle", "Load"), show="headings")
    self.tree.heading("ID", text="ID (Ключ)")
    self.tree.heading("Name", text="Название упражнения")
    self.tree.heading("Muscle", text="Целевая группа мышц")
    self.tree.heading("Load", text="Нагрузка / Вес (кг)")

    self.tree.column("ID", width=100, anchor="center")
    self.tree.column("Name", width=280, anchor="w")
    self.tree.column("Muscle", width=200, anchor="w")
    self.tree.column("Load", width=140, anchor="center")

    self.tree.bind("<ButtonRelease-1>", self.onrowselect)

    scrollbar = ttk.Scrollbar(tableframe, orient="vertical", command=self.tree.yview)
    self.tree.configure(yscrollcommand=scrollbar.set)

    self.tree.pack(side="left", fill="both", expand=True)
    scrollbar.pack(side="right", fill="y")

  def refreshtable(self):
    for row in self.tree.get_children():
      self.tree.delete(row)
    for record in self.db.getall():
      self.tree.insert("", "end", values=record)

  def onrowselect(self, event):
    selected = self.tree.selection()
    if selected:
      item = self.tree.item(selected)
      values = item["values"]
      for i, key in enumerate(["id", "name", "muscle", "load"]):
        self.entries[key].delete(0, tk.END)
        self.entries[key].insert(0, values[i])

  def readfields(self):
    rid = self.entries["id"].get().strip()
    name = self.entries["name"].get().strip()
    muscle = self.entries["muscle"].get().strip()
    load = self.entries["load"].get().strip().replace(",", ".")

    if not rid or not name or not muscle or not load:
      messagebox.showerror("Ошибка", "Заполните все поля!")
      return None
    if not rid.isdecimal():
      messagebox.showerror("Ошибка", "ID должен быть целым числом!")
      return None
    try:
      float(load)
    except ValueError:
      messagebox.showerror("Ошибка", "Нагрузка должна быть числом!")
      return None
    if "|" in name or "|" in muscle:
      messagebox.showerror("Ошибка", "Символ | использовать нельзя!")
      return None
    return str(int(rid)), name, muscle, load

  def guiaddrecord(self):
    fields = self.readfields()
    if not fields:
      return
    try:
      self.db.addrecord(*fields)
      self.refreshtable()
      messagebox.showinfo("Успех", "Запись успешно добавлена!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guileditrecord(self):
    fields = self.readfields()
    if not fields:
      return
    try:
      self.db.updaterecord(*fields)
      self.refreshtable()
      messagebox.showinfo("Успех", f"Запись с ID {fields[0]} успешно обновлена!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guideleterecord(self):
    selected = self.tree.selection()
    if not selected:
      rid = self.entries["id"].get().strip()
      if not rid:
        messagebox.showwarning("Внимание", "Выберите строку в таблице или введите ID в поле для удаления!")
        return
    else:
      item = self.tree.item(selected)
      rid = item["values"][0]

    try:
      self.db.deleterecord(str(rid))
      self.refreshtable()
      messagebox.showinfo("Успех", f"Запись с ID {rid} удалена!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guideletebyvalue(self):
    fieldindex = self.fieldbox.current()
    value = self.entries[self.fieldkeys[fieldindex]].get().strip()
    if not value:
      messagebox.showwarning("Внимание", "Заполните поле, по значению которого нужно удалить!")
      return
    try:
      count = len(self.db.findids(fieldindex, value))
      if count == 0:
        messagebox.showinfo("Результат", "Записей с таким значением нет")
        return
      if messagebox.askyesno("Подтверждение", f"Найдено записей: {count}. Удалить все?"):
        self.db.deletebyvalue(fieldindex, value)
        self.refreshtable()
        messagebox.showinfo("Успех", f"Удалено записей: {count}")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guisearch(self):
    fieldindex = self.fieldbox.current()
    query = self.entries[self.fieldkeys[fieldindex]].get().strip()
    if not query:
      messagebox.showwarning("Внимание", "Заполните поле, по значению которого нужно искать!")
      return

    try:
      results = self.db.search(fieldindex, query)
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))
      return
    for row in self.tree.get_children():
      self.tree.delete(row)
    for record in results:
      self.tree.insert("", "end", values=record)
    messagebox.showinfo("Результаты", f"Найдено записей: {len(results)}")

  def guinewdb(self):
    chosenfile = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
    if chosenfile:
      try:
        self.db.newfile(chosenfile)
        self.refreshtable()
        messagebox.showinfo("Успех", f"Создана новая база данных {chosenfile}!")
      except Exception as e:
        messagebox.showerror("Ошибка", str(e))

  def guiopendb(self):
    chosenfile = filedialog.askopenfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
    if chosenfile:
      try:
        self.db.openfile(chosenfile)
        self.refreshtable()
        messagebox.showinfo("Успех", f"База данных открыта из файла {chosenfile}!")
      except Exception as e:
        messagebox.showerror("Ошибка", str(e))

  def guisavedb(self):
    try:
      self.db.savedb()
      self.refreshtable()
      messagebox.showinfo("Успех", "База данных сохранена!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guicleardb(self):
    if messagebox.askyesno("Подтверждение", "Вы действительно хотите полностью очистить базу данных?"):
      try:
        self.db.cleardb()
        self.refreshtable()
        messagebox.showinfo("Успех", "База данных полностью очищена!")
      except Exception as e:
        messagebox.showerror("Ошибка", str(e))

  def guideletedb(self):
    if messagebox.askyesno("Подтверждение", "Удалить файл базы данных с диска? Действие необратимо."):
      try:
        self.db.deletedb()
        self.refreshtable()
        messagebox.showinfo("Успех", "Файл базы данных удалён!")
      except Exception as e:
        messagebox.showerror("Ошибка", str(e))

  def guibackup(self):
    try:
      self.db.createbackup()
      messagebox.showinfo("Успех", "Бэкап успешно создан!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guirestore(self):
    try:
      self.db.restorebackup()
      self.refreshtable()
      messagebox.showinfo("Успех", "База данных восстановлена из бэкапа!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

  def guiexport(self):
    try:
      self.db.exporttocsv()
      messagebox.showinfo("Успех", f"Данные успешно экспортированы в файл {exportname}!")
    except Exception as e:
      messagebox.showerror("Ошибка", str(e))

if __name__ == "__main__":
  root = tk.Tk()
