import os
import shutil
import tkinter as tk
from tkinter import messagebox, ttk, filedialog

DB_NAME = "workout.dat"
BACKUP_NAME = "workout_backup.dat"
EXPORT_NAME = "workout_export.csv"
FIELDS = ["id", "name", "muscle", "load"]
TITLES = ["ID (ключ)", "Название упражнения", "Группа мышц", "Нагрузка (кг)"]


class Database:
    def __init__(self, filename=DB_NAME):
        self.filename = filename
        self.reset_index()
        if os.path.exists(filename):
            self.load_index()
        else:
            self.create_db(filename)

    def reset_index(self):
        self.index = {}
        self.search_index = {"name": {}, "muscle": {}, "load": {}}

    def add_to_index(self, parts, pos):
        self.index[parts[0]] = pos
        for i in (1, 2, 3):
            key = parts[i].lower()
            self.search_index[FIELDS[i]].setdefault(key, set()).add(parts[0])

    def remove_from_index(self, parts):
        del self.index[parts[0]]
        for i in (1, 2, 3):
            self.search_index[FIELDS[i]][parts[i].lower()].discard(parts[0])

    def load_index(self):
        self.reset_index()
        with open(self.filename, "r", encoding="utf-8") as f:
            while True:
                pos = f.tell()
                line = f.readline()
                if not line:
                    break
                parts = line.strip().split("|")
                if len(parts) == 5 and parts[4] == "0":
                    self.add_to_index(parts, pos)

    def create_db(self, filename):
        self.filename = filename
        open(filename, "w", encoding="utf-8").close()
        self.reset_index()

    def open_db(self, filename):
        self.filename = filename
        self.load_index()

    def clear_db(self):
        self.create_db(self.filename)

    def delete_db(self):
        if os.path.exists(self.filename):
            os.remove(self.filename)
        self.reset_index()

    def save_db(self):
        tmp_name = self.filename + ".tmp"
        with open(self.filename, "r", encoding="utf-8") as src, open(tmp_name, "w", encoding="utf-8") as dst:
            for line in src:
                if line.strip().endswith("|0"):
                    dst.write(line.strip() + "\n")
        os.replace(tmp_name, self.filename)
        self.load_index()

    def get_all(self):
        records = []
        if not os.path.exists(self.filename):
            return records
        with open(self.filename, "r", encoding="utf-8") as f:
            for pos in self.index.values():
                f.seek(pos)
                parts = f.readline().strip().split("|")
                records.append(parts[:4])
        return records

    def add_record(self, record_id, name, muscle, load):
        if record_id in self.index:
            raise ValueError(f"Запись с ID {record_id} уже существует!")
        with open(self.filename, "a", encoding="utf-8") as f:
            pos = f.tell()
            f.write(f"{record_id}|{name}|{muscle}|{load}|0\n")
        self.add_to_index([record_id, name, muscle, load], pos)

    def delete_record(self, record_id):
        if record_id not in self.index:
            raise ValueError(f"Запись с ID {record_id} не найдена!")
        pos = self.index[record_id]
        with open(self.filename, "r+", encoding="utf-8") as f:
            f.seek(pos)
            parts = f.readline().strip().split("|")
            f.seek(pos)
            f.write("|".join(parts[:4]) + "|1\n")
        self.remove_from_index(parts)

    def update_record(self, record_id, name, muscle, load):
        if record_id not in self.index:
            raise ValueError(f"Запись с ID {record_id} не найдена!")
        self.delete_record(record_id)
        self.add_record(record_id, name, muscle, load)

    def find_ids(self, field, value):
        try:
            if field == "id":
                value = str(int(value))
            elif field == "load":
                value = str(float(value.replace(",", ".")))
        except ValueError:
            return []
        if field == "id":
            return [value] if value in self.index else []
        return list(self.search_index[field].get(value.lower(), []))

    def search(self, field, value):
        records = []
        with open(self.filename, "r", encoding="utf-8") as f:
            for record_id in sorted(self.find_ids(field, value), key=int):
                f.seek(self.index[record_id])
                records.append(f.readline().strip().split("|")[:4])
        return records

    def delete_by_value(self, field, value):
        ids = self.find_ids(field, value)
        for record_id in ids:
            self.delete_record(record_id)
        return len(ids)

    def create_backup(self):
        shutil.copy(self.filename, BACKUP_NAME)

    def restore_backup(self):
        if not os.path.exists(BACKUP_NAME):
            raise FileNotFoundError("Бэкап-файл не найден!")
        shutil.copy(BACKUP_NAME, self.filename)
        self.load_index()

    def export_csv(self):
        with open(EXPORT_NAME, "w", encoding="utf-8-sig") as f:
            f.write(";".join(TITLES) + "\n")
            for record in self.get_all():
                f.write(";".join(record) + "\n")


class App:
    def __init__(self, root):
        self.db = Database()
        self.root = root
        self.root.title("База данных: Сервис программ тренировок (Лабораторная №2)")
        self.root.geometry("950x620")
        self.create_widgets()
        self.refresh_table()

    def create_widgets(self):
        form = tk.LabelFrame(self.root, text=" Запись ")
        form.pack(fill="x", padx=10, pady=10)
        self.entries = {}
        for i, field in enumerate(FIELDS):
            tk.Label(form, text=TITLES[i] + ":").grid(row=i // 2, column=i % 2 * 2, padx=10, pady=6, sticky="e")
            entry = tk.Entry(form, width=25)
            entry.grid(row=i // 2, column=i % 2 * 2 + 1, padx=10, pady=6, sticky="w")
            self.entries[field] = entry

        row1 = tk.Frame(self.root)
        row1.pack(fill="x", padx=10, pady=3)
        buttons = [
            ("Добавить", self.add_record), ("Править", self.edit_record),
            ("Удалить выбранные", self.delete_selected), ("Показать все", self.refresh_table),
            ("Бэкап", self.backup), ("Восстановить", self.restore), ("Экспорт в CSV", self.export),
        ]
        for text, command in buttons:
            tk.Button(row1, text=text, command=command).pack(side="left", padx=2)

        row2 = tk.Frame(self.root)
        row2.pack(fill="x", padx=10, pady=3)
        tk.Label(row2, text="Поле для поиска и удаления:").pack(side="left")
        self.field_box = ttk.Combobox(row2, values=TITLES, state="readonly", width=20)
        self.field_box.current(1)
        self.field_box.pack(side="left", padx=4)
        buttons = [
            ("Поиск", self.search), ("Удалить по значению", self.delete_by_value),
            ("Создать БД", self.new_db), ("Открыть БД", self.open_db), ("Сохранить БД", self.save_db),
            ("Очистить БД", self.clear_db), ("Удалить БД", self.delete_db),
        ]
        for text, command in buttons:
            tk.Button(row2, text=text, command=command).pack(side="left", padx=2)

        table_frame = tk.Frame(self.root)
        table_frame.pack(fill="both", expand=True, padx=10, pady=10)
        self.tree = ttk.Treeview(table_frame, columns=FIELDS, show="headings")
        for i, field in enumerate(FIELDS):
            self.tree.heading(field, text=TITLES[i])
        self.tree.bind("<<TreeviewSelect>>", self.on_select)
        scrollbar = ttk.Scrollbar(table_frame, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scrollbar.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

    def run(self, action, text):
        try:
            action()
            self.refresh_table()
            messagebox.showinfo("Успех", text)
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def fill_table(self, records):
        for row in self.tree.get_children():
            self.tree.delete(row)
        for record in records:
            self.tree.insert("", "end", iid=record[0], values=record)

    def refresh_table(self):
        self.fill_table(self.db.get_all())

    def on_select(self, event):
        selected = self.tree.selection()
        if len(selected) == 1:
            values = self.tree.item(selected[0], "values")
            for field, value in zip(FIELDS, values):
                self.entries[field].delete(0, tk.END)
                self.entries[field].insert(0, value)

    def get_fields(self):
        record_id, name, muscle, load = [self.entries[f].get().strip() for f in FIELDS]
        if not record_id or not name or not muscle or not load:
            messagebox.showerror("Ошибка", "Заполните все поля!")
            return None
        if not record_id.isdecimal():
            messagebox.showerror("Ошибка", "ID должен быть целым числом!")
            return None
        try:
            load = str(float(load.replace(",", ".")))
        except ValueError:
            messagebox.showerror("Ошибка", "Нагрузка должна быть числом!")
            return None
        if "|" in name or "|" in muscle:
            messagebox.showerror("Ошибка", "Символ | использовать нельзя!")
            return None
        return str(int(record_id)), name, muscle, load

    def get_search_data(self):
        field = FIELDS[self.field_box.current()]
        value = self.entries[field].get().strip()
        if not value:
            messagebox.showwarning("Внимание", "Заполните выбранное поле!")
        return field, value

    def add_record(self):
        fields = self.get_fields()
        if fields:
            self.run(lambda: self.db.add_record(*fields), "Запись добавлена!")

    def edit_record(self):
        fields = self.get_fields()
        if fields:
            self.run(lambda: self.db.update_record(*fields), "Запись обновлена!")

    def delete_selected(self):
        selected = self.tree.selection()
        if not selected:
            messagebox.showwarning("Внимание", "Выберите строки в таблице!")
        elif messagebox.askyesno("Подтверждение", f"Удалить выбранные записи: {len(selected)}?"):
            self.run(lambda: [self.db.delete_record(i) for i in selected], "Записи удалены!")

    def search(self):
        field, value = self.get_search_data()
        if value:
            try:
                records = self.db.search(field, value)
            except Exception as e:
                messagebox.showerror("Ошибка", str(e))
                return
            self.fill_table(records)
            messagebox.showinfo("Результаты", f"Найдено записей: {len(records)}")

    def delete_by_value(self):
        field, value = self.get_search_data()
        if value:
            count = len(self.db.find_ids(field, value))
            if count == 0:
                messagebox.showinfo("Результат", "Записей с таким значением нет")
            elif messagebox.askyesno("Подтверждение", f"Найдено записей: {count}. Удалить все?"):
                self.run(lambda: self.db.delete_by_value(field, value), f"Удалено записей: {count}")

    def new_db(self):
        filename = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat")])
        if filename:
            self.run(lambda: self.db.create_db(filename), "База данных создана!")

    def open_db(self):
        filename = filedialog.askopenfilename(filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
        if filename:
            self.run(lambda: self.db.open_db(filename), "База данных открыта!")

    def save_db(self):
        self.run(self.db.save_db, "База данных сохранена!")

    def clear_db(self):
        if messagebox.askyesno("Подтверждение", "Очистить базу данных?"):
            self.run(self.db.clear_db, "База данных очищена!")

    def delete_db(self):
        if messagebox.askyesno("Подтверждение", "Удалить файл базы данных?"):
            self.run(self.db.delete_db, "Файл базы данных удалён!")

    def backup(self):
        self.run(self.db.create_backup, "Бэкап создан!")

    def restore(self):
        self.run(self.db.restore_backup, "База данных восстановлена из бэкапа!")

    def export(self):
        self.run(self.db.export_csv, f"Данные экспортированы в файл {EXPORT_NAME}!")


if __name__ == "__main__":
    root = tk.Tk()
    app = App(root)
    root.mainloop()

