                messagebox.showerror("Ошибка", str(e))
                return
            self.fill_table(records)
            messagebox.showinfo("Результаты", f"Найдено записей: {len(records)}")

    def delete_by_value(self):
        field, value = self.get_search_data()
        if value:
            count = len(self.db.find_ids(field, value))
            if count == 0:
                messagebox.showinfo("Результат", "Записей с таким значением нет")
            elif messagebox.askyesno("Подтверждение", f"Найдено записей: {count}. Удалить все?"):
                self.run(lambda: self.db.delete_by_value(field, value), f"Удалено записей: {count}")

    def new_db(self):
        filename = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat")])
        if filename:
            self.run(lambda: self.db.create_db(filename), "База данных создана!")

    def open_db(self):
        filename = filedialog.askopenfilename(filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
        if filename:
            self.run(lambda: self.db.open_db(filename), "База данных открыта!")

    def save_db(self):
        self.run(self.db.save_db, "База данных сохранена!")

    def clear_db(self):
        if messagebox.askyesno("Подтверждение", "Очистить базу данных?"):
            self.run(self.db.clear_db, "База данных очищена!")

    def delete_db(self):
        if messagebox.askyesno("Подтверждение", "Удалить файл базы данных?"):
            self.run(self.db.delete_db, "Файл базы данных удалён!")

    def backup(self):
        self.run(self.db.create_backup, "Бэкап создан!")

    def restore(self):
        self.run(self.db.restore_backup, "База данных восстановлена из бэкапа!")

    def export(self):
        self.run(self.db.export_csv, f"Данные экспортированы в файл {EXPORT_NAME}!")


if __name__ == "__main__":
    root = tk.Tk()
    app = App(root)
    root.mainloop()

