import os
import shutil
import tkinter as tk
from tkinter import messagebox, ttk, filedialog

DB_NAME = "workout.dat"
BACKUP_NAME = "workout_backup.dat"
EXPORT_NAME = "workout_export.csv"


class Database:
    def __init__(self, filename=DB_NAME):
        self.filename = filename
        self.reset_index()
        if os.path.exists(filename):
            self.build_index()
        else:
            self.create_db(filename)

    def reset_index(self):
        self.index = {}
        self.name_index = {}
        self.muscle_index = {}
        self.load_index = {}

    def add_to_index(self, parts, pos):
        record_id = parts[0]
        self.index[record_id] = pos
        self.name_index.setdefault(parts[1].lower(), set()).add(record_id)
        self.muscle_index.setdefault(parts[2].lower(), set()).add(record_id)
        self.load_index.setdefault(parts[3], set()).add(record_id)

    def remove_from_index(self, parts):
        record_id = parts[0]
        del self.index[record_id]
        self.name_index[parts[1].lower()].discard(record_id)
        self.muscle_index[parts[2].lower()].discard(record_id)
        self.load_index[parts[3]].discard(record_id)

    def build_index(self):
        self.reset_index()
        with open(self.filename, "r", encoding="utf-8") as f:
            while True:
                pos = f.tell()
                line = f.readline()
                if not line:
                    break
                parts = line.strip().split("|")
                if len(parts) == 5 and parts[4] == "0":
                    self.add_to_index(parts, pos)

    def create_db(self, filename):
        self.filename = filename
        with open(filename, "w", encoding="utf-8") as f:
            pass
        self.reset_index()

    def open_db(self, filename):
        self.filename = filename
        self.build_index()

    def clear_db(self):
        with open(self.filename, "w", encoding="utf-8") as f:
            pass
        self.reset_index()

    def delete_db(self):
        if os.path.exists(self.filename):
            os.remove(self.filename)
        self.reset_index()

    def save_db(self):
        tmp_name = self.filename + ".tmp"
        with open(self.filename, "r", encoding="utf-8") as src:
            with open(tmp_name, "w", encoding="utf-8") as dst:
                for line in src:
                    line = line.strip()
                    if line.endswith("|0"):
                        dst.write(line + "\n")
        os.replace(tmp_name, self.filename)
        self.build_index()

    def get_all(self):
        records = []
        if not os.path.exists(self.filename):
            return records
        with open(self.filename, "r", encoding="utf-8") as f:
            for pos in self.index.values():
                f.seek(pos)
                parts = f.readline().strip().split("|")
                records.append(parts[:4])
        return records

    def add_record(self, record_id, name, muscle, load):
        if record_id in self.index:
            raise ValueError("Запись с ID " + record_id + " уже существует!")
        line = record_id + "|" + name + "|" + muscle + "|" + load + "|0\n"
        with open(self.filename, "a", encoding="utf-8") as f:
            f.seek(0, os.SEEK_END)
            pos = f.tell()
            f.write(line)
        self.add_to_index([record_id, name, muscle, load], pos)

    def delete_record(self, record_id):
        if record_id not in self.index:
            raise ValueError("Запись с ID " + record_id + " не найдена!")
        pos = self.index[record_id]
        with open(self.filename, "r+", encoding="utf-8") as f:
            f.seek(pos)
            parts = f.readline().strip().split("|")
            f.seek(pos)
            f.write(parts[0] + "|" + parts[1] + "|" + parts[2] + "|" + parts[3] + "|1\n")
        self.remove_from_index(parts)

    def update_record(self, record_id, name, muscle, load):
        if record_id not in self.index:
            raise ValueError("Запись с ID " + record_id + " не найдена!")
        self.delete_record(record_id)
        self.add_record(record_id, name, muscle, load)

    def find_ids(self, field, value):
        if field == "id":
            try:
                value = str(int(value))
            except ValueError:
                return []
            if value in self.index:
                return [value]
            return []
        if field == "name":
            return list(self.name_index.get(value.lower(), []))
        if field == "muscle":
            return list(self.muscle_index.get(value.lower(), []))
        if field == "load":
            try:
                value = str(float(value.replace(",", ".")))
            except ValueError:
                return []
            return list(self.load_index.get(value, []))
        return []

    def search(self, field, value):
        records = []
        ids = self.find_ids(field, value)
        ids.sort(key=int)
        with open(self.filename, "r", encoding="utf-8") as f:
            for record_id in ids:
                f.seek(self.index[record_id])
                parts = f.readline().strip().split("|")
                records.append(parts[:4])
        return records

    def delete_by_value(self, field, value):
        ids = self.find_ids(field, value)
        for record_id in ids:
            self.delete_record(record_id)
        return len(ids)

    def create_backup(self):
        shutil.copy(self.filename, BACKUP_NAME)

    def restore_backup(self):
        if not os.path.exists(BACKUP_NAME):
            raise FileNotFoundError("Бэкап-файл не найден!")
        shutil.copy(BACKUP_NAME, self.filename)
        self.build_index()

    def export_csv(self):
        records = self.get_all()
        with open(EXPORT_NAME, "w", encoding="utf-8-sig") as f:
            f.write("ID;Название упражнения;Группа мышц;Нагрузка (кг)\n")
            for r in records:
                f.write(r[0] + ";" + r[1] + ";" + r[2] + ";" + r[3] + "\n")


