        self.load_entry = tk.Entry(form, width=25)
        self.id_entry.grid(row=0, column=1, padx=10, pady=6, sticky="w")
        self.name_entry.grid(row=0, column=3, padx=10, pady=6, sticky="w")
        self.muscle_entry.grid(row=1, column=1, padx=10, pady=6, sticky="w")
        self.load_entry.grid(row=1, column=3, padx=10, pady=6, sticky="w")
        self.entries = [self.id_entry, self.name_entry, self.muscle_entry, self.load_entry]

        row1 = tk.Frame(self.root)
        row1.pack(fill="x", padx=10, pady=3)
        tk.Button(row1, text="Добавить", command=self.add_record).pack(side="left", padx=2)
        tk.Button(row1, text="Править", command=self.edit_record).pack(side="left", padx=2)
        tk.Button(row1, text="Удалить выбранные", command=self.delete_selected).pack(side="left", padx=2)
        tk.Button(row1, text="Показать все", command=self.refresh_table).pack(side="left", padx=2)
        tk.Button(row1, text="Бэкап", command=self.backup).pack(side="left", padx=2)
        tk.Button(row1, text="Восстановить", command=self.restore).pack(side="left", padx=2)
        tk.Button(row1, text="Экспорт в CSV", command=self.export).pack(side="left", padx=2)

        row2 = tk.Frame(self.root)
        row2.pack(fill="x", padx=10, pady=3)
        tk.Label(row2, text="Поле для поиска и удаления:").pack(side="left")
        self.field_box = ttk.Combobox(row2, values=["ID", "Название", "Группа мышц", "Нагрузка"], state="readonly", width=14)
        self.field_box.current(1)
        self.field_box.pack(side="left", padx=4)
        tk.Button(row2, text="Поиск", command=self.search).pack(side="left", padx=2)
        tk.Button(row2, text="Удалить по значению", command=self.delete_by_value).pack(side="left", padx=2)

        row3 = tk.Frame(self.root)
        row3.pack(fill="x", padx=10, pady=3)
        tk.Button(row3, text="Создать БД", command=self.new_db).pack(side="left", padx=2)
        tk.Button(row3, text="Открыть БД", command=self.open_db).pack(side="left", padx=2)
        tk.Button(row3, text="Сохранить БД", command=self.save_db).pack(side="left", padx=2)
        tk.Button(row3, text="Очистить БД", command=self.clear_db).pack(side="left", padx=2)
        tk.Button(row3, text="Удалить БД", command=self.delete_db).pack(side="left", padx=2)

        table_frame = tk.Frame(self.root)
        table_frame.pack(fill="both", expand=True, padx=10, pady=10)
        self.tree = ttk.Treeview(table_frame, columns=("ID", "Name", "Muscle", "Load"), show="headings")
        self.tree.heading("ID", text="ID (ключ)")
        self.tree.heading("Name", text="Название упражнения")
        self.tree.heading("Muscle", text="Группа мышц")
        self.tree.heading("Load", text="Нагрузка (кг)")
        self.tree.bind("<<TreeviewSelect>>", self.on_select)
        scrollbar = ttk.Scrollbar(table_frame, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=scrollbar.set)
        self.tree.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

    def fill_table(self, records):
        for row in self.tree.get_children():
            self.tree.delete(row)
        for record in records:
            self.tree.insert("", "end", iid=record[0], values=record)

    def refresh_table(self):
        self.fill_table(self.db.get_all())

    def on_select(self, event):
        selected = self.tree.selection()
        if len(selected) == 1:
            values = self.tree.item(selected[0], "values")
            for i in range(4):
                self.entries[i].delete(0, tk.END)
                self.entries[i].insert(0, values[i])

    def get_fields(self):
        record_id = self.id_entry.get().strip()
        name = self.name_entry.get().strip()
        muscle = self.muscle_entry.get().strip()
        load = self.load_entry.get().strip()

        if not record_id or not name or not muscle or not load:
            messagebox.showerror("Ошибка", "Заполните все поля!")
            return None
        if not record_id.isdecimal():
            messagebox.showerror("Ошибка", "ID должен быть целым числом!")
            return None
        try:
            load = str(float(load.replace(",", ".")))
        except ValueError:
            messagebox.showerror("Ошибка", "Нагрузка должна быть числом!")
            return None
        if "|" in name or "|" in muscle:
            messagebox.showerror("Ошибка", "Символ | использовать нельзя!")
            return None
        return str(int(record_id)), name, muscle, load

    def add_record(self):
        fields = self.get_fields()
        if fields is None:
            return
        try:
            self.db.add_record(fields[0], fields[1], fields[2], fields[3])
            self.refresh_table()
            messagebox.showinfo("Успех", "Запись добавлена!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def edit_record(self):
        fields = self.get_fields()
        if fields is None:
            return
        try:
            self.db.update_record(fields[0], fields[1], fields[2], fields[3])
            self.refresh_table()
            messagebox.showinfo("Успех", "Запись обновлена!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def delete_selected(self):
        selected = self.tree.selection()
        if len(selected) == 0:
            messagebox.showwarning("Внимание", "Выберите строки в таблице!")
            return
        if not messagebox.askyesno("Подтверждение", "Удалить выбранные записи: " + str(len(selected)) + "?"):
            return
        try:
            for record_id in selected:
                self.db.delete_record(record_id)
            self.refresh_table()
            messagebox.showinfo("Успех", "Записи удалены!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def search(self):
        index = self.field_box.current()
        field = self.field_names[index]
        value = self.entries[index].get().strip()
        if not value:
            messagebox.showwarning("Внимание", "Заполните выбранное поле!")
            return
        try:
            records = self.db.search(field, value)
            self.fill_table(records)
            messagebox.showinfo("Результаты", "Найдено записей: " + str(len(records)))
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def delete_by_value(self):
        index = self.field_box.current()
        field = self.field_names[index]
        value = self.entries[index].get().strip()
        if not value:
            messagebox.showwarning("Внимание", "Заполните выбранное поле!")
            return
        count = len(self.db.find_ids(field, value))
        if count == 0:
            messagebox.showinfo("Результат", "Записей с таким значением нет")
            return
        if not messagebox.askyesno("Подтверждение", "Найдено записей: " + str(count) + ". Удалить все?"):
            return
        try:
            self.db.delete_by_value(field, value)
            self.refresh_table()
            messagebox.showinfo("Успех", "Удалено записей: " + str(count))
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def new_db(self):
        filename = filedialog.asksaveasfilename(defaultextension=".dat", filetypes=[("Data files", "*.dat")])
        if not filename:
            return
        try:
            self.db.create_db(filename)
            self.refresh_table()
            messagebox.showinfo("Успех", "База данных создана!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def open_db(self):
        filename = filedialog.askopenfilename(filetypes=[("Data files", "*.dat"), ("All files", "*.*")])
        if not filename:
            return
        try:
            self.db.open_db(filename)
            self.refresh_table()
            messagebox.showinfo("Успех", "База данных открыта!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def save_db(self):
        try:
            self.db.save_db()
            self.refresh_table()
            messagebox.showinfo("Успех", "База данных сохранена!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def clear_db(self):
        if not messagebox.askyesno("Подтверждение", "Очистить базу данных?"):
            return
        try:
            self.db.clear_db()
            self.refresh_table()
            messagebox.showinfo("Успех", "База данных очищена!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def delete_db(self):
        if not messagebox.askyesno("Подтверждение", "Удалить файл базы данных?"):
            return
        try:
            self.db.delete_db()
            self.refresh_table()
            messagebox.showinfo("Успех", "Файл базы данных удалён!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def backup(self):
        try:
            self.db.create_backup()
            messagebox.showinfo("Успех", "Бэкап создан!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def restore(self):
        try:
            self.db.restore_backup()
            self.refresh_table()
            messagebox.showinfo("Успех", "База данных восстановлена из бэкапа!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))

    def export(self):
        try:
            self.db.export_csv()
            messagebox.showinfo("Успех", "Данные экспортированы в файл " + EXPORT_NAME + "!")
        except Exception as e:
            messagebox.showerror("Ошибка", str(e))


if __name__ == "__main__":
    root = tk.Tk()
    app = App(root)
    root.mainloop()

