/*
 * Лабораторная работа: Файловая база данных с GUI
 * Предметная область: Сервис составления программ тренировок и ведения журнала
 * Организация файла: Прямая файловая хеш-таблица методом цепочек (O(1) в среднем)
 * Работа ведется напрямую с бинарным файлом через fseek / fread / fwrite без загрузки БД в ОЗУ.
 */

#define _CRT_SECURE_NO_WARNINGS

#include <windows.h>
#include <commctrl.h>
#include <commdlg.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>

// ============================================================================
// ПОМОЩНИКИ ДЛЯ РАБОТЫ С РУССКИМ ТЕКСТОМ (UTF-8 <-> WinAPI Unicode)
// ============================================================================

void utf8ToWide(const char* utf8Str, wchar_t* wideBuf, int maxWideChars) {
    if (!utf8Str || maxWideChars <= 0) return;
    MultiByteToWideChar(CP_UTF8, 0, utf8Str, -1, wideBuf, maxWideChars);
}

void wideToUtf8(const wchar_t* wideStr, char* utf8Buf, int maxUtf8Bytes) {
    if (!wideStr || maxUtf8Bytes <= 0) return;
    WideCharToMultiByte(CP_UTF8, 0, wideStr, -1, utf8Buf, maxUtf8Bytes, NULL, NULL);
}

HWND createControlUtf8(DWORD exStyle, const char* className, const char* titleUtf8,
                       DWORD style, int x, int y, int w, int h, HWND parent, int id) {
    wchar_t wClass[64];
    wchar_t wTitle[256];
    utf8ToWide(className, wClass, 64);
    utf8ToWide(titleUtf8, wTitle, 256);
    return CreateWindowExW(exStyle, wClass, wTitle, style, x, y, w, h, parent, (HMENU)(INT_PTR)id, GetModuleHandle(NULL), NULL);
}

void setWindowTextUtf8(HWND hwnd, const char* textUtf8) {
    wchar_t wText[512];
    utf8ToWide(textUtf8, wText, 512);
    SetWindowTextW(hwnd, wText);
}

void getWindowTextUtf8(HWND hwnd, char* outUtf8, int maxBytes) {
    wchar_t wText[512];
    GetWindowTextW(hwnd, wText, 512);
    wideToUtf8(wText, outUtf8, maxBytes);
}

void msgBoxUtf8(HWND hwnd, const char* textUtf8, const char* captionUtf8, UINT type) {
    wchar_t wText[1024];
    wchar_t wCap[128];
    utf8ToWide(textUtf8, wText, 1024);
    utf8ToWide(captionUtf8, wCap, 128);
    MessageBoxW(hwnd, wText, wCap, type);
}


// ============================================================================
// ЧАСТЬ 1. СТРУКТУРА ФАЙЛОВОЙ БАЗЫ ДАННЫХ И АЛГОРИТМЫ (БЕЗ ХРАНЕНИЯ В ОЗУ)
// ============================================================================

const int HASH_SIZE = 1009;
const int DB_MAGIC = 0x57444231;

struct FileHeader {
    int magic;                  // Сигнатура файла
    int activeCount;            // Количество активных записей
    long freeHeadOffset;        // Смещение первой удаленной записи (-1 если нет)
    long buckets[HASH_SIZE];    // Хеш-таблица смещений в файле
};

struct WorkoutRecord {
    int id;                     // Ключевое поле: ID записи (int)
    char clientAndGoal[96];     // Клиент, уровень и цель (char[])
    char exerciseInfo[96];      // Упражнение, мышцы и инвентарь (char[])
    int setsCount;              // Количество подходов (int)
    double workingWeight;       // Рабочий вес в кг (double)
    bool isCompleted;           // Выполнено в журнале (bool)

    // Служебные поля для файловой хеш-таблицы
    bool isDeleted;
    long nextOffset;
};

char g_currentDbPath[MAX_PATH] = "workouts_plan.db";
bool g_isDbOpen = false;

int hashFunction(int key) {
    int positiveKey = (key < 0) ? -key : key;
    return positiveKey % HASH_SIZE;
}

long getBucketFileOffset(int bucketIndex) {
    return (long)offsetof(FileHeader, buckets) + (long)bucketIndex * (long)sizeof(long);
}

// Создание новой пустой БД — O(1)
bool dbCreate(const char* filepath) {
    FILE* f = fopen(filepath, "wb");
    if (!f) return false;

    FileHeader header;
    header.magic = DB_MAGIC;
    header.activeCount = 0;
    header.freeHeadOffset = -1L;
    for (int i = 0; i < HASH_SIZE; i++) {
        header.buckets[i] = -1L;
    }

    size_t written = fwrite(&header, sizeof(FileHeader), 1, f);
    fclose(f);

    if (written == 1) {
        strncpy(g_currentDbPath, filepath, MAX_PATH - 1);
        g_isDbOpen = true;
        return true;
    }
    return false;
}

// Открытие существующей БД — O(1)
bool dbOpen(const char* filepath) {
    FILE* f = fopen(filepath, "rb");
    if (!f) return false;

    FileHeader header;
    size_t readCount = fread(&header, sizeof(FileHeader), 1, f);
    fclose(f);

    if (readCount != 1 || header.magic != DB_MAGIC) {
        return false;
    }

    strncpy(g_currentDbPath, filepath, MAX_PATH - 1);
    g_isDbOpen = true;
    return true;
}

// Очистка БД — O(1)
bool dbClear() {
    if (!g_isDbOpen) return false;
    return dbCreate(g_currentDbPath);
}

// Удаление файла БД с диска — O(1)
bool dbDropFile() {
    if (!g_isDbOpen) return false;
    if (remove(g_currentDbPath) == 0) {
        g_isDbOpen = false;
        return true;
    }
    return false;
}

// Поиск записи по ключу внутри открытого файла — O(1) в среднем
long findRecordOffsetByKeyInFile(FILE* f, int keyId, WorkoutRecord* outRecord) {
    int bucket = hashFunction(keyId);
    long bucketPos = getBucketFileOffset(bucket);

    long currOffset = -1L;
    fseek(f, bucketPos, SEEK_SET);
    fread(&currOffset, sizeof(long), 1, f);

    WorkoutRecord temp;
    while (currOffset != -1L) {
        fseek(f, currOffset, SEEK_SET);
        if (fread(&temp, sizeof(WorkoutRecord), 1, f) != 1) {
            break;
        }
        if (!temp.isDeleted && temp.id == keyId) {
            if (outRecord != NULL) {
                *outRecord = temp;
            }
            return currOffset;
        }
        currOffset = temp.nextOffset;
    }
    return -1L;
}

// Поиск записи по ключевому полю (id) — O(1) в среднем
bool dbSearchByKey(int keyId, WorkoutRecord* outRecord) {
    if (!g_isDbOpen) return false;
    FILE* f = fopen(g_currentDbPath, "rb");
    if (!f) return false;

    long offset = findRecordOffsetByKeyInFile(f, keyId, outRecord);
    fclose(f);
    return (offset != -1L);
}

// Добавление записи в открытый файл — O(1) в среднем
bool addRecordInFile(FILE* f, WorkoutRecord newRec) {
    if (findRecordOffsetByKeyInFile(f, newRec.id, NULL) != -1L) {
        return false; // Ключ уже существует
    }

    int activeCount = 0;
    long freeHeadOffset = -1L;
    fseek(f, offsetof(FileHeader, activeCount), SEEK_SET);
    fread(&activeCount, sizeof(int), 1, f);
    fread(&freeHeadOffset, sizeof(long), 1, f);

    int bucket = hashFunction(newRec.id);
    long bucketPos = getBucketFileOffset(bucket);
    long oldBucketHead = -1L;
    fseek(f, bucketPos, SEEK_SET);
    fread(&oldBucketHead, sizeof(long), 1, f);

    newRec.isDeleted = false;
    newRec.nextOffset = oldBucketHead;

    long targetOffset = -1L;
    if (freeHeadOffset != -1L) {
        targetOffset = freeHeadOffset;

        WorkoutRecord deletedSlot;
        fseek(f, targetOffset, SEEK_SET);
        fread(&deletedSlot, sizeof(WorkoutRecord), 1, f);

        freeHeadOffset = deletedSlot.nextOffset;
        fseek(f, offsetof(FileHeader, freeHeadOffset), SEEK_SET);
        fwrite(&freeHeadOffset, sizeof(long), 1, f);
    } else {
        fseek(f, 0, SEEK_END);
        targetOffset = ftell(f);
    }

    fseek(f, targetOffset, SEEK_SET);
    fwrite(&newRec, sizeof(WorkoutRecord), 1, f);

    fseek(f, bucketPos, SEEK_SET);
    fwrite(&targetOffset, sizeof(long), 1, f);

    activeCount++;
    fseek(f, offsetof(FileHeader, activeCount), SEEK_SET);
    fwrite(&activeCount, sizeof(int), 1, f);

    return true;
}

// Добавление новой записи в БД — O(1) в среднем
bool dbAddRecord(WorkoutRecord newRec) {
    if (!g_isDbOpen) return false;
    FILE* f = fopen(g_currentDbPath, "r+b");
    if (!f) return false;

    bool ok = addRecordInFile(f, newRec);
    fflush(f);
    fclose(f);
    return ok;
}

// Удаление записи по ключу в открытом файле — O(1) в среднем
bool deleteRecordByKeyInFile(FILE* f, int keyId) {
    int bucket = hashFunction(keyId);
    long bucketPos = getBucketFileOffset(bucket);

    long currOffset = -1L;
    fseek(f, bucketPos, SEEK_SET);
    fread(&currOffset, sizeof(long), 1, f);

    long prevOffset = -1L;
    WorkoutRecord currRec;

    while (currOffset != -1L) {
        fseek(f, currOffset, SEEK_SET);
        if (fread(&currRec, sizeof(WorkoutRecord), 1, f) != 1) {
            return false;
        }

        if (!currRec.isDeleted && currRec.id == keyId) {
            if (prevOffset == -1L) {
                fseek(f, bucketPos, SEEK_SET);
                fwrite(&currRec.nextOffset, sizeof(long), 1, f);
            } else {
                long prevNextFieldPos = prevOffset + (long)offsetof(WorkoutRecord, nextOffset);
                fseek(f, prevNextFieldPos, SEEK_SET);
                fwrite(&currRec.nextOffset, sizeof(long), 1, f);
            }

            int activeCount = 0;
            long freeHeadOffset = -1L;
            fseek(f, offsetof(FileHeader, activeCount), SEEK_SET);
            fread(&activeCount, sizeof(int), 1, f);
            fread(&freeHeadOffset, sizeof(long), 1, f);

            currRec.isDeleted = true;
            currRec.nextOffset = freeHeadOffset;
            fseek(f, currOffset, SEEK_SET);
            fwrite(&currRec, sizeof(WorkoutRecord), 1, f);

            freeHeadOffset = currOffset;
            activeCount = (activeCount > 0) ? (activeCount - 1) : 0;
            fseek(f, offsetof(FileHeader, activeCount), SEEK_SET);
            fwrite(&activeCount, sizeof(int), 1, f);
            fwrite(&freeHeadOffset, sizeof(long), 1, f);

            return true;
        }

        prevOffset = currOffset;
        currOffset = currRec.nextOffset;
    }

    return false;
}

// Удаление записи по ключевому полю — O(1) в среднем
bool dbDeleteByKey(int keyId) {
    if (!g_isDbOpen) return false;
    FILE* f = fopen(g_currentDbPath, "r+b");
    if (!f) return false;

    bool ok = deleteRecordByKeyInFile(f, keyId);
    fflush(f);
    fclose(f);
    return ok;
}

// Проверка совпадения по неключевому полю
bool recordMatchesNonKeyField(const WorkoutRecord& rec, int fieldType, const char* strVal, int intVal, double dblVal, bool boolVal) {
    if (rec.isDeleted) return false;
    switch (fieldType) {
        case 1:
            return (strcmp(rec.clientAndGoal, strVal) == 0 || strstr(rec.clientAndGoal, strVal) != NULL);
        case 2:
            return (strcmp(rec.exerciseInfo, strVal) == 0 || strstr(rec.exerciseInfo, strVal) != NULL);
        case 3:
            return (rec.setsCount == intVal);
        case 4:
            return (fabs(rec.workingWeight - dblVal) < 0.001);
        case 5:
            return (rec.isCompleted == boolVal);
        default:
            return false;
    }
}

// Удаление всех записей по неключевому полю — O(N)
int dbDeleteByNonKeyField(int fieldType, const char* strVal, int intVal, double dblVal, bool boolVal) {
    if (!g_isDbOpen) return 0;
    FILE* f = fopen(g_currentDbPath, "r+b");
    if (!f) return 0;

    fseek(f, 0, SEEK_END);
    long fileSize = ftell(f);

    int deletedCount = 0;
    WorkoutRecord rec;

    for (long pos = (long)sizeof(FileHeader); pos + (long)sizeof(WorkoutRecord) <= fileSize; pos += (long)sizeof(WorkoutRecord)) {
        fseek(f, pos, SEEK_SET);
        if (fread(&rec, sizeof(WorkoutRecord), 1, f) != 1) break;

        if (!rec.isDeleted && recordMatchesNonKeyField(rec, fieldType, strVal, intVal, dblVal, boolVal)) {
            if (deleteRecordByKeyInFile(f, rec.id)) {
                deletedCount++;
            }
        }
    }

    fflush(f);
    fclose(f);
    return deletedCount;
}

// Редактирование записи — O(1) в среднем
bool dbEditRecord(int oldKeyId, WorkoutRecord updatedRec) {
    if (!g_isDbOpen) return false;
    FILE* f = fopen(g_currentDbPath, "r+b");
    if (!f) return false;

    if (oldKeyId == updatedRec.id) {
        WorkoutRecord existingRec;
        long offset = findRecordOffsetByKeyInFile(f, oldKeyId, &existingRec);
        if (offset == -1L) {
            fclose(f);
            return false;
        }

        updatedRec.isDeleted = false;
        updatedRec.nextOffset = existingRec.nextOffset;

        fseek(f, offset, SEEK_SET);
        fwrite(&updatedRec, sizeof(WorkoutRecord), 1, f);
        fflush(f);
        fclose(f);
        return true;
    } else {
        if (findRecordOffsetByKeyInFile(f, updatedRec.id, NULL) != -1L) {
            fclose(f);
            return false;
        }
        if (findRecordOffsetByKeyInFile(f, oldKeyId, NULL) == -1L) {
            fclose(f);
            return false;
        }
        deleteRecordByKeyInFile(f, oldKeyId);
        addRecordInFile(f, updatedRec);
        fflush(f);
        fclose(f);
        return true;
    }
}

// Сохранение копии файла БД
bool copyBinaryFile(const char* srcPath, const char* dstPath) {
    FILE* src = fopen(srcPath, "rb");
    if (!src) return false;
    FILE* dst = fopen(dstPath, "wb");
    if (!dst) {
        fclose(src);
        return false;
    }

    char buffer[4096];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), src)) > 0) {
        fwrite(buffer, 1, bytesRead, dst);
    }

    fclose(src);
    fclose(dst);
    return true;
}


