}

// Обновление таблицы напрямую из бинарного файла БД
void refreshTableFromFile() {
    SendMessageW(hListView, LVM_DELETEALLITEMS, 0, 0);

    if (!g_isDbOpen) {
        setStatusText("  База данных не открыта. Нажмите «Создать БД» или «Открыть БД».");
        return;
    }

    FILE* f = fopen(g_currentDbPath, "rb");
    if (!f) {
        setStatusText("  Ошибка открытия файла базы данных.");
        return;
    }

    FileHeader hdr;
    if (fread(&hdr, sizeof(FileHeader), 1, f) != 1 || hdr.magic != DB_MAGIC) {
        fclose(f);
        setStatusText("  Некорректный формат файла базы данных.");
        return;
    }

    fseek(f, 0, SEEK_END);
    long fileSize = ftell(f);

    SendMessageW(hListView, WM_SETREDRAW, FALSE, 0);

    int row = 0;
    WorkoutRecord rec;
    for (long pos = (long)sizeof(FileHeader); pos + (long)sizeof(WorkoutRecord) <= fileSize; pos += (long)sizeof(WorkoutRecord)) {
        fseek(f, pos, SEEK_SET);
        if (fread(&rec, sizeof(WorkoutRecord), 1, f) != 1) break;
        if (!rec.isDeleted) {
            addRowToListView(row++, rec);
        }
    }

    SendMessageW(hListView, WM_SETREDRAW, TRUE, 0);
    InvalidateRect(hListView, NULL, TRUE);

    fclose(f);

    char status[256];
    sprintf(status, "  Файл БД: %s   |   Записей в базе: %d", g_currentDbPath, hdr.activeCount);
    setStatusText(status);
}

bool readWorkoutFromForm(WorkoutRecord* outRec, HWND hwndParent) {
    char bufId[32], bufClient[96], bufEx[96], bufSets[32], bufWeight[32];
    getWindowTextUtf8(hEditId, bufId, sizeof(bufId));
    getWindowTextUtf8(hEditClient, bufClient, sizeof(bufClient));
    getWindowTextUtf8(hEditExercise, bufEx, sizeof(bufEx));
    getWindowTextUtf8(hEditSets, bufSets, sizeof(bufSets));
    getWindowTextUtf8(hEditWeight, bufWeight, sizeof(bufWeight));

    if (strlen(bufId) == 0 || strlen(bufClient) == 0 || strlen(bufEx) == 0 || strlen(bufSets) == 0 || strlen(bufWeight) == 0) {
        msgBoxUtf8(hwndParent, "Пожалуйста, заполните все поля записи!", "Внимание", MB_OK | MB_ICONWARNING);
        return false;
    }

    int id = atoi(bufId);
    int sets = atoi(bufSets);
    for (char* p = bufWeight; *p; ++p) {
        if (*p == ',') *p = '.';
    }
    double weight = atof(bufWeight);

    if (id <= 0) {
        msgBoxUtf8(hwndParent, "ID записи должен быть положительным целым числом!", "Ошибка ввода", MB_OK | MB_ICONWARNING);
        return false;
    }
    if (sets < 1 || sets > 30) {
        msgBoxUtf8(hwndParent, "Количество подходов должно быть от 1 до 30!", "Ошибка ввода", MB_OK | MB_ICONWARNING);
        return false;
    }
    if (weight < 0.0 || weight > 500.0) {
        msgBoxUtf8(hwndParent, "Рабочий вес должен быть от 0 до 500 кг!", "Ошибка ввода", MB_OK | MB_ICONWARNING);
        return false;
    }

    memset(outRec, 0, sizeof(WorkoutRecord));
    outRec->id = id;
    strncpy(outRec->clientAndGoal, bufClient, sizeof(outRec->clientAndGoal) - 1);
    strncpy(outRec->exerciseInfo, bufEx, sizeof(outRec->exerciseInfo) - 1);
    outRec->setsCount = sets;
    outRec->workingWeight = weight;
    outRec->isCompleted = (SendMessageW(hChkCompleted, BM_GETCHECK, 0, 0) == BST_CHECKED);
    return true;
}

