bool showFileDialog(HWND hwnd, char* outPath, bool isSave, const wchar_t* filterWide, const wchar_t* defExtWide) {
    OPENFILENAMEW ofn;
    wchar_t wFile[MAX_PATH];
    wFile[0] = L'\0';
    ZeroMemory(&ofn, sizeof(ofn));

    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = hwnd;
    ofn.lpstrFilter = filterWide;
    ofn.lpstrFile = wFile;
    ofn.nMaxFile = MAX_PATH;
    ofn.lpstrDefExt = defExtWide;
    ofn.Flags = OFN_EXPLORER | OFN_NOCHANGEDIR | (isSave ? OFN_OVERWRITEPROMPT : OFN_FILEMUSTEXIST);

    BOOL res = isSave ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn);
    if (res) {
        WideCharToMultiByte(CP_ACP, 0, wFile, -1, outPath, MAX_PATH, NULL, NULL);
        return true;
    }
    return false;
}

void handleSearchAction(HWND hwnd) {
    if (!g_isDbOpen) {
        msgBoxUtf8(hwnd, "База данных не открыта!", "Ошибка", MB_OK | MB_ICONERROR);
        return;
    }

    int fieldIdx = (int)SendMessageW(hCmbField, CB_GETCURSEL, 0, 0);
    char query[128];
    getWindowTextUtf8(hEditQuery, query, sizeof(query));

    if (strlen(query) == 0) {
        msgBoxUtf8(hwnd, "Введите значение для поиска!", "Внимание", MB_OK | MB_ICONWARNING);
        return;
    }

    SendMessageW(hListView, LVM_DELETEALLITEMS, 0, 0);
    int foundCount = 0;

    if (fieldIdx == 0) {
        int keyId = atoi(query);
        WorkoutRecord rec;
        if (dbSearchByKey(keyId, &rec)) {
            addRowToListView(0, rec);
            foundCount = 1;
        }
    } else {
        int intVal = atoi(query);
        char weightBuf[64];
        strncpy(weightBuf, query, sizeof(weightBuf) - 1);
        for (char* p = weightBuf; *p; ++p) if (*p == ',') *p = '.';
        double dblVal = atof(weightBuf);
        bool boolVal = (strcmp(query, "1") == 0 || strcmp(query, "Да") == 0 || strcmp(query, "да") == 0);

        FILE* f = fopen(g_currentDbPath, "rb");
        if (f) {
            fseek(f, 0, SEEK_END);
            long fileSize = ftell(f);
            WorkoutRecord rec;

            for (long pos = (long)sizeof(FileHeader); pos + (long)sizeof(WorkoutRecord) <= fileSize; pos += (long)sizeof(WorkoutRecord)) {
                fseek(f, pos, SEEK_SET);
                if (fread(&rec, sizeof(WorkoutRecord), 1, f) != 1) break;
                if (!rec.isDeleted && recordMatchesNonKeyField(rec, fieldIdx, query, intVal, dblVal, boolVal)) {
                    addRowToListView(foundCount++, rec);
                }
            }
            fclose(f);
        }
    }

    char status[256];
    sprintf(status, "  Найдено записей: %d. Нажмите «Показать все», чтобы вернуться ко всему списку.", foundCount);
    setStatusText(status);
}

void handleDeleteAction(HWND hwnd) {
    if (!g_isDbOpen) {
        msgBoxUtf8(hwnd, "База данных не открыта!", "Ошибка", MB_OK | MB_ICONERROR);
        return;
    }

    int fieldIdx = (int)SendMessageW(hCmbField, CB_GETCURSEL, 0, 0);
    char query[128];
    getWindowTextUtf8(hEditQuery, query, sizeof(query));

    if (strlen(query) == 0) {
        msgBoxUtf8(hwnd, "Введите значение для удаления!", "Внимание", MB_OK | MB_ICONWARNING);
        return;
    }

    int deletedCount = 0;

    if (fieldIdx == 0) {
        int keyId = atoi(query);
        if (dbDeleteByKey(keyId)) {
            deletedCount = 1;
        }
    } else {
        int intVal = atoi(query);
        char weightBuf[64];
        strncpy(weightBuf, query, sizeof(weightBuf) - 1);
        for (char* p = weightBuf; *p; ++p) if (*p == ',') *p = '.';
        double dblVal = atof(weightBuf);
        bool boolVal = (strcmp(query, "1") == 0 || strcmp(query, "Да") == 0 || strcmp(query, "да") == 0);

        deletedCount = dbDeleteByNonKeyField(fieldIdx, query, intVal, dblVal, boolVal);
    }

    refreshTableFromFile();

    char status[256];
    sprintf(status, "  Удалено записей: %d.", deletedCount);
    setStatusText(status);

    if (deletedCount == 0) {
        msgBoxUtf8(hwnd, "Записи с таким значением не найдены!", "Удаление", MB_OK | MB_ICONINFORMATION);
    }
}

