            hCmbField = createControlUtf8(0, "COMBOBOX", "", WS_VISIBLE | WS_CHILD | CBS_DROPDOWNLIST,
                30, 488, 310, 200, hwnd, ID_CMB_FIELD);

            addComboStringUtf8(hCmbField, "ID записи (ключевое поле)");
            addComboStringUtf8(hCmbField, "Клиент (Имя, уровень, цель)");
            addComboStringUtf8(hCmbField, "Упражнение (Мышцы и инвентарь)");
            addComboStringUtf8(hCmbField, "Количество подходов");
            addComboStringUtf8(hCmbField, "Рабочий вес (кг)");
            addComboStringUtf8(hCmbField, "Выполнено (Да / Нет)");
            SendMessageW(hCmbField, CB_SETCURSEL, 0, 0);

            createControlUtf8(0, "STATIC", "Значение:", WS_VISIBLE | WS_CHILD, 30, 522, 280, 20, hwnd, 0);
            hEditQuery = createModernEdit(30, 544, 310, 26, hwnd, ID_EDIT_QUERY);

            createModernButton("Найти",   30, 580, 150, 32, hwnd, ID_BTN_SEARCH);
            createModernButton("Удалить", 190, 580, 150, 32, hwnd, ID_BTN_DELETE);

            // --- ПРАВАЯ КАРТОЧКА: Таблица базы данных ---
            createModernButton("Показать все", 890, 98, 130, 28, hwnd, ID_BTN_SHOW_ALL);

            hListView = CreateWindowExW(0, L"SysListView32", L"",
                WS_VISIBLE | WS_CHILD | WS_BORDER | LVS_REPORT | LVS_SINGLESEL | LVS_SHOWSELALWAYS,
                386, 134, 634, 478, hwnd, (HMENU)ID_LISTVIEW_TABLE, GetModuleHandle(NULL), NULL);

            SendMessageW(hListView, LVM_SETEXTENDEDLISTVIEWSTYLE, 0,
                LVS_EX_FULLROWSELECT | LVS_EX_GRIDLINES | LVS_EX_DOUBLEBUFFER);

            HIMAGELIST hRowHeightList = ImageList_Create(1, 26, ILC_COLOR, 1, 1);
            SendMessageW(hListView, LVM_SETIMAGELIST, LVSIL_SMALL, (LPARAM)hRowHeightList);

            const char* colTitles[] = { "ID", "Клиент (Уровень и Цель)", "Упражнение [Мышцы | Инвентарь]", "Подходы", "Вес (кг)", "Выполнено" };
            int colWidths[] = { 55, 190, 200, 62, 62, 60 };
            for (int i = 0; i < 6; i++) {
                wchar_t wCol[64];
                utf8ToWide(colTitles[i], wCol, 64);
                LVCOLUMNW lvc;
                memset(&lvc, 0, sizeof(lvc));
                lvc.mask = LVCF_TEXT | LVCF_WIDTH | LVCF_SUBITEM;
                lvc.cx = colWidths[i];
                lvc.pszText = wCol;
                lvc.iSubItem = i;
                SendMessageW(hListView, LVM_INSERTCOLUMNW, i, (LPARAM)&lvc);
            }

            // Нижняя строка состояния
            hStatusLabel = createControlUtf8(0, "STATIC", "  Готово к работе.",
                WS_VISIBLE | WS_CHILD | SS_CENTERIMAGE, 16, 634, 1020, 24, hwnd, 0);

            EnumChildWindows(hwnd, SetChildFontProc, (LPARAM)hFontRegular);

            // Открываем файл БД или создаем стартовый пример
            if (!dbOpen(g_currentDbPath)) {
                dbCreate(g_currentDbPath);
                WorkoutRecord demo[] = {
                    { 101, "Алексей, 23г (Средний | Набор массы)", "Жим штанги лежа [Грудь | Штанга]", 4, 75.0, true, false, -1 },
                    { 102, "Алексей, 23г (Средний | Набор массы)", "Приседания со штангой [Ноги | Штанга]", 4, 92.5, true, false, -1 },
                    { 103, "Екатерина, 21г (Новичок | Похудение)", "Тяга верхнего блока [Спина | Тренажер]", 3, 30.0, true, false, -1 },
                    { 104, "Екатерина, 21г (Новичок | Похудение)", "Выпады с гантелями [Ноги | Гантели]", 4, 12.5, false, false, -1 },
                    { 105, "Дмитрий, 28л (Профи | Выносливость)", "Становая тяга [Спина | Штанга]", 5, 130.0, false, false, -1 }
                };
                for (int i = 0; i < 5; i++) {
                    dbAddRecord(demo[i]);
                }
            }
            refreshTableFromFile();
            break;
        }

        // Отрисовка современных белых карточек с мягкими рамками вместо старых GroupBox
        case WM_PAINT: {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hwnd, &ps);

            drawCardPanel(hdc, 14, 8,   1022, 72,  "Файл базы данных");
            drawCardPanel(hdc, 14, 90,  342,  332, "Запись (Добавление / Редактирование)");
            drawCardPanel(hdc, 14, 432, 342,  194, "Поиск и удаление");
            drawCardPanel(hdc, 368, 90, 668,  536, "Таблица записей программы тренировок");

            EndPaint(hwnd, &ps);
            return 0;
        }

        // Современная отрисовка плоских скругленных кнопок (без выпуклых рамок Windows 95)
        case WM_DRAWITEM: {
            LPDRAWITEMSTRUCT dis = (LPDRAWITEMSTRUCT)lParam;
            if (dis->CtlType == ODT_BUTTON) {
                HDC hdc = dis->hDC;
                RECT rc = dis->rcItem;
                bool isPressed = (dis->itemState & ODS_SELECTED) != 0;

                // Определяем цвет кнопки по её назначению
                COLORREF bgClr = CLR_SOFT_BTN;
                COLORREF txtClr = CLR_TEXT_DARK;
                COLORREF borderClr = RGB(205, 215, 228);

                if (dis->CtlID == ID_BTN_ADD_RECORD || dis->CtlID == ID_BTN_SEARCH) {
                    bgClr = isPressed ? RGB(37, 99, 235) : CLR_ACCENT_BLUE;
                    txtClr = RGB(255, 255, 255);
                    borderClr = bgClr;
                } else if (dis->CtlID == ID_BTN_DELETE || dis->CtlID == ID_BTN_DROP_DB) {
                    bgClr = isPressed ? RGB(220, 38, 38) : CLR_DANGER_BTN;
                    txtClr = RGB(255, 255, 255);
                    borderClr = bgClr;
                } else if (isPressed) {
                    bgClr = RGB(222, 229, 238);
                }

                // Стираем уголки под цвет карточки
                FillRect(hdc, &rc, hCardBgBrush);

                HBRUSH hBtnBrush = CreateSolidBrush(bgClr);
                HPEN hBtnPen = CreatePen(PS_SOLID, 1, borderClr);
                HGDIOBJ oldBrush = SelectObject(hdc, hBtnBrush);
                HGDIOBJ oldPen = SelectObject(hdc, hBtnPen);

                RoundRect(hdc, rc.left, rc.top, rc.right, rc.bottom, 8, 8);

                SelectObject(hdc, oldBrush);
                SelectObject(hdc, oldPen);
                DeleteObject(hBtnBrush);
                DeleteObject(hBtnPen);

                wchar_t wText[128];
                GetWindowTextW(dis->hwndItem, wText, 128);
                SetBkMode(hdc, TRANSPARENT);
                SetTextColor(hdc, txtClr);
                HGDIOBJ oldFont = SelectObject(hdc, hFontRegular);
                DrawTextW(hdc, wText, -1, &rc, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
                SelectObject(hdc, oldFont);

                return TRUE;
            }
            break;
        }

        // Чистый белый фон для подписей внутри карточек
        case WM_CTLCOLORSTATIC: {
            HDC hdcStatic = (HDC)wParam;
            HWND hwndCtrl = (HWND)lParam;
            SetTextColor(hdcStatic, CLR_TEXT_DARK);
            if (hwndCtrl == hStatusLabel) {
                SetBkColor(hdcStatic, CLR_APP_BG);
                return (INT_PTR)hAppBgBrush;
            }
            SetBkColor(hdcStatic, CLR_CARD_BG);
            return (INT_PTR)hCardBgBrush;
        }

        case WM_CTLCOLOREDIT: {
            HDC hdcEdit = (HDC)wParam;
            SetTextColor(hdcEdit, CLR_TEXT_DARK);
            SetBkColor(hdcEdit, CLR_INPUT_BG);
            return (INT_PTR)hInputBgBrush;
        }

        case WM_NOTIFY: {
            LPNMHDR nmhdr = (LPNMHDR)lParam;

            if (nmhdr->idFrom == ID_LISTVIEW_TABLE && nmhdr->code == NM_CUSTOMDRAW) {
                LPNMLVCUSTOMDRAW lvcd = (LPNMLVCUSTOMDRAW)lParam;
                if (lvcd->nmcd.dwDrawStage == CDDS_PREPAINT) {
                    return CDRF_NOTIFYITEMDRAW;
                }
                if (lvcd->nmcd.dwDrawStage == CDDS_ITEMPREPAINT) {
                    int row = (int)lvcd->nmcd.dwItemSpec;
                    lvcd->clrTextBk = (row % 2 == 0) ? CLR_ROW_EVEN : CLR_ROW_ODD;
                    lvcd->clrText = CLR_TEXT_DARK;
                    return CDRF_NEWFONT;
                }
            }

            if (nmhdr->idFrom == ID_LISTVIEW_TABLE && nmhdr->code == LVN_ITEMCHANGED) {
                LPNMLISTVIEW pnmv = (LPNMLISTVIEW)lParam;
                if ((pnmv->uNewState & LVIS_SELECTED) && pnmv->iItem >= 0) {
                    char bufId[32], bufClient[96], bufEx[96], bufSets[32], bufWeight[32], bufDone[32];
                    getListViewCellUtf8(hListView, pnmv->iItem, 0, bufId, sizeof(bufId));
                    getListViewCellUtf8(hListView, pnmv->iItem, 1, bufClient, sizeof(bufClient));
                    getListViewCellUtf8(hListView, pnmv->iItem, 2, bufEx, sizeof(bufEx));
                    getListViewCellUtf8(hListView, pnmv->iItem, 3, bufSets, sizeof(bufSets));
                    getListViewCellUtf8(hListView, pnmv->iItem, 4, bufWeight, sizeof(bufWeight));
                    getListViewCellUtf8(hListView, pnmv->iItem, 5, bufDone, sizeof(bufDone));

                    g_selectedRecordId = atoi(bufId);
                    setWindowTextUtf8(hEditId, bufId);
                    setWindowTextUtf8(hEditClient, bufClient);
                    setWindowTextUtf8(hEditExercise, bufEx);
                    setWindowTextUtf8(hEditSets, bufSets);
                    setWindowTextUtf8(hEditWeight, bufWeight);
                    SendMessageW(hChkCompleted, BM_SETCHECK, (strcmp(bufDone, "Да") == 0) ? BST_CHECKED : BST_UNCHECKED, 0);
                }
            }
            break;
        }

        case WM_COMMAND: {
            int id = LOWORD(wParam);
            switch (id) {
                case ID_BTN_CREATE_DB: {
                    char path[MAX_PATH];
                    if (showFileDialog(hwnd, path, true, L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0", L"db")) {
                        if (dbCreate(path)) {
                            clearInputForm();
                            refreshTableFromFile();
                            msgBoxUtf8(hwnd, "Новая база данных создана!", "Создание БД", MB_OK | MB_ICONINFORMATION);
                        }
                    }
                    break;
                }

                case ID_BTN_OPEN_DB: {
                    char path[MAX_PATH];
                    if (showFileDialog(hwnd, path, false, L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0", L"db")) {
                        if (dbOpen(path)) {
                            clearInputForm();
                            refreshTableFromFile();
                        } else {
                            msgBoxUtf8(hwnd, "Не удалось открыть файл БД!", "Ошибка", MB_OK | MB_ICONERROR);
                        }
                    }
                    break;
                }

                case ID_BTN_SAVE_AS_DB: {
                    if (!g_isDbOpen) break;
                    char path[MAX_PATH];
                    if (showFileDialog(hwnd, path, true, L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0", L"db")) {
                        if (copyBinaryFile(g_currentDbPath, path)) {
                            strncpy(g_currentDbPath, path, MAX_PATH - 1);
                            refreshTableFromFile();
                            msgBoxUtf8(hwnd, "База данных успешно сохранена!", "Сохранение", MB_OK | MB_ICONINFORMATION);
                        }
                    }
                    break;
                }

                case ID_BTN_CLEAR_DB: {
                    if (!g_isDbOpen) break;
                    if (dbClear()) {
                        clearInputForm();
                        refreshTableFromFile();
                        setStatusText("  База данных очищена.");
                    }
                    break;
                }

                case ID_BTN_DROP_DB: {
                    if (!g_isDbOpen) break;
                    if (dbDropFile()) {
                        clearInputForm();
                        refreshTableFromFile();
                        msgBoxUtf8(hwnd, "Файл базы данных удален!", "Удаление БД", MB_OK | MB_ICONINFORMATION);
                    }
                    break;
                }

                case ID_BTN_SHOW_ALL: {
                    refreshTableFromFile();
                    break;
                }

                case ID_BTN_CLEAR_FORM: {
                    clearInputForm();
                    break;
                }

                case ID_BTN_ADD_RECORD: {
                    if (!g_isDbOpen) {
                        msgBoxUtf8(hwnd, "Сначала создайте или откройте БД!", "Ошибка", MB_OK | MB_ICONERROR);
                        break;
                    }
                    WorkoutRecord rec;
                    if (readWorkoutFromForm(&rec, hwnd)) {
                        if (dbAddRecord(rec)) {
                            refreshTableFromFile();
                            setStatusText("  Запись успешно добавлена в базу данных.");
                        } else {
                            msgBoxUtf8(hwnd, "Запись с таким ID уже существует!", "Ошибка", MB_OK | MB_ICONERROR);
                        }
                    }
                    break;
                }

                case ID_BTN_EDIT_RECORD: {
                    if (!g_isDbOpen) break;
                    if (g_selectedRecordId == -1) {
                        msgBoxUtf8(hwnd, "Выберите запись в таблице справа!", "Редактирование", MB_OK | MB_ICONWARNING);
                        break;
                    }
                    WorkoutRecord updated;
                    if (readWorkoutFromForm(&updated, hwnd)) {
                        if (dbEditRecord(g_selectedRecordId, updated)) {
                            g_selectedRecordId = updated.id;
                            refreshTableFromFile();
                            setStatusText("  Запись успешно изменена.");
                        } else {
                            msgBoxUtf8(hwnd, "Не удалось обновить запись (возможно, новый ID занят).", "Ошибка", MB_OK | MB_ICONERROR);
                        }
                    }
                    break;
                }

                case ID_BTN_SEARCH: {
                    handleSearchAction(hwnd);
                    break;
                }

                case ID_BTN_DELETE: {
                    handleDeleteAction(hwnd);
                    break;
                }
            }
            break;
        }

        case WM_DESTROY: {
            if (hFontRegular) DeleteObject(hFontRegular);
            if (hFontBold) DeleteObject(hFontBold);
            if (hAppBgBrush) DeleteObject(hAppBgBrush);
            if (hCardBgBrush) DeleteObject(hCardBgBrush);
            if (hInputBgBrush) DeleteObject(hInputBgBrush);
            PostQuitMessage(0);
            break;
        }

        default:
            return DefWindowProcW(hwnd, msg, wParam, lParam);
    }
    return 0;
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE hPrevInstance, LPSTR lpCmdLine, int nCmdShow) {
    hAppBgBrush = CreateSolidBrush(CLR_APP_BG);
    hCardBgBrush = CreateSolidBrush(CLR_CARD_BG);
    hInputBgBrush = CreateSolidBrush(CLR_INPUT_BG);

    WNDCLASSEXW wc;
    ZeroMemory(&wc, sizeof(wc));
    wc.cbSize = sizeof(WNDCLASSEXW);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInstance;
    wc.hCursor = LoadCursor(NULL, IDC_ARROW);
    wc.hbrBackground = hAppBgBrush;
    wc.lpszClassName = L"WorkoutFileDBWindowClassW";
    wc.hIcon = LoadIcon(NULL, IDI_APPLICATION);

    if (!RegisterClassExW(&wc)) {
        return 0;
    }

    wchar_t wWindowTitle[128];
    utf8ToWide("Сервис составления программ тренировок — Файловая БД", wWindowTitle, 128);

    HWND hwnd = CreateWindowExW(
        0,
        L"WorkoutFileDBWindowClassW",
        wWindowTitle,
        WS_OVERLAPPED | WS_CAPTION | WS_SYSMENU | WS_MINIMIZEBOX,
        CW_USEDEFAULT, CW_USEDEFAULT, 1065, 700,
        NULL, NULL, hInstance, NULL
    );

    ShowWindow(hwnd, nCmdShow);
    UpdateWindow(hwnd);

    MSG msg;
    while (GetMessageW(&msg, NULL, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }
    return (int)msg.wParam;
}

int main() {
    HWND hConsole = GetConsoleWindow();
    if (hConsole) ShowWindow(hConsole, SW_HIDE);
    return WinMain(GetModuleHandle(NULL), NULL, GetCommandLineA(), SW_SHOWDEFAULT);
}

