/*
 * Лабораторная работа №2. Файловая база данных с GUI.
 * Предметная область: журнал тренировок.
 *
 * Организация файла: хеш-таблица с цепочками прямо в бинарном файле.
 *   [ Header: magic, число записей, начало списка свободных слотов, 1009 корзин ]
 *   [ Record ][ Record ][ Record ] ...
 * Каждая корзина хранит смещение первой записи цепочки, запись хранит смещение следующей.
 * Вся работа идет через fseek / fread / fwrite, база в памяти НЕ хранится.
 *
 * Сложность:
 *   добавление, удаление и поиск по ключу - O(1) в среднем
 *   поиск и удаление по неключевому полю  - O(N)
 *
 * Сборка:
 *   MSVC : cl /EHsc /utf-8 workout_db.cpp
 *   MinGW: g++ workout_db.cpp -o workout_db.exe -mwindows -lcomctl32 -lcomdlg32 -lgdi32 -luser32
 */

#define _CRT_SECURE_NO_WARNINGS

#include <windows.h>
#include <commctrl.h>
#include <commdlg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <math.h>
#include <stddef.h>

#ifdef _MSC_VER
#pragma comment(lib, "comctl32.lib")
#pragma comment(lib, "comdlg32.lib")
#pragma comment(linker, "/SUBSYSTEM:WINDOWS")
#endif


// ============================================================================
// ЧАСТЬ 1. ФАЙЛОВАЯ БАЗА ДАННЫХ
// ============================================================================

const int HASH_SIZE = 1009;       // число корзин (простое число)
const int DB_MAGIC  = 0x57444231; // сигнатура нашего файла
const int TEXT_LEN  = 32;         // длина строковых полей (в символах)

// Заголовок файла
struct Header {
    int  magic;
    int  activeCount;        // сколько записей живых
    long freeHead;           // первый свободный слот (-1, если нет)
    long buckets[HASH_SIZE]; // смещения первых записей цепочек (-1, если пусто)
};

// Одна запись таблицы
struct Record {
    int     id;                   // КЛЮЧ
    wchar_t client[TEXT_LEN];     // клиент
    wchar_t exercise[TEXT_LEN];   // упражнение
    int     sets;                 // количество подходов
    double  weight;               // рабочий вес, кг
    bool    done;                 // выполнено в журнале
    bool    deleted;              // служебное: слот свободен
    long    next;                 // служебное: следующая запись цепочки / свободного списка
};

// Позиции полей внутри файла
const long POS_COUNT   = (long)offsetof(Header, activeCount);
const long POS_FREE    = (long)offsetof(Header, freeHead);
const long POS_BUCKETS = (long)offsetof(Header, buckets);
const long POS_NEXT    = (long)offsetof(Record, next); // внутри записи

wchar_t g_dbPath[MAX_PATH] = L"trainings.db";
bool    g_dbOpened = false;


// ---------- Низкоуровневые помощники ----------

long readLong(FILE* f, long pos) {
    long v = -1;
    fseek(f, pos, SEEK_SET);
    fread(&v, sizeof(long), 1, f);
    return v;
}

void writeLong(FILE* f, long pos, long v) {
    fseek(f, pos, SEEK_SET);
    fwrite(&v, sizeof(long), 1, f);
}

int readInt(FILE* f, long pos) {
    int v = 0;
    fseek(f, pos, SEEK_SET);
    fread(&v, sizeof(int), 1, f);
    return v;
}

void writeInt(FILE* f, long pos, int v) {
    fseek(f, pos, SEEK_SET);
    fwrite(&v, sizeof(int), 1, f);
}

bool readRecord(FILE* f, long pos, Record* r) {
    fseek(f, pos, SEEK_SET);
    return fread(r, sizeof(Record), 1, f) == 1;
}

void writeRecord(FILE* f, long pos, const Record* r) {
    fseek(f, pos, SEEK_SET);
    fwrite(r, sizeof(Record), 1, f);
}

long fileSize(FILE* f) {
    fseek(f, 0, SEEK_END);
    return ftell(f);
}

// Позиция корзины для ключа в файле
long bucketPosOf(int id) {
    return POS_BUCKETS + (long)(id % HASH_SIZE) * (long)sizeof(long);
}

Record makeRecord(int id, const wchar_t* client, const wchar_t* exercise, int sets, double weight, bool done) {
    Record r;
    memset(&r, 0, sizeof(r));
    r.id = id;
    wcsncpy(r.client, client, TEXT_LEN - 1);
    wcsncpy(r.exercise, exercise, TEXT_LEN - 1);
    r.sets = sets;
    r.weight = weight;
    r.done = done;
    r.next = -1;
    return r;
}


// ---------- Работа с файлом БД: создание, открытие, удаление ----------

// Создает пустой файл БД (или перезаписывает существующий)
bool createEmptyFile(const wchar_t* path) {
    FILE* f = _wfopen(path, L"wb");
    if (!f) return false;

    Header h;
    h.magic = DB_MAGIC;
    h.activeCount = 0;
    h.freeHead = -1;
    for (int i = 0; i < HASH_SIZE; i++) h.buckets[i] = -1;

    bool ok = (fwrite(&h, sizeof(Header), 1, f) == 1);
    fclose(f);
    return ok;
}

// Проверяет, что файл - наша БД
bool isValidDbFile(const wchar_t* path) {
    FILE* f = _wfopen(path, L"rb");
    if (!f) return false;
    Header h;
    bool ok = (fread(&h, sizeof(Header), 1, f) == 1 && h.magic == DB_MAGIC);
    fclose(f);
    return ok;
}

// Делает файл текущей БД
void useDb(const wchar_t* path) {
    if (path != g_dbPath) {
        wcsncpy(g_dbPath, path, MAX_PATH - 1);
        g_dbPath[MAX_PATH - 1] = 0;
    }
    g_dbOpened = true;
}

bool dbOpen(const wchar_t* path) {
    if (!isValidDbFile(path)) return false;
    useDb(path);
    return true;
}

bool dbClear() {
    return createEmptyFile(g_dbPath);
}

bool dbDrop() {
    if (_wremove(g_dbPath) != 0) return false;
    g_dbOpened = false;
    return true;
}


// ---------- Поиск по ключу ----------

// Ищет запись по ключу в открытом файле. Возвращает смещение или -1.
long findInFile(FILE* f, int id, Record* out) {
    long cur = readLong(f, bucketPosOf(id));
    Record r;
    while (cur != -1) {
        if (!readRecord(f, cur, &r)) break;
        if (r.id == id) {
            if (out) *out = r;
            return cur;
        }
        cur = r.next;
    }
    return -1;
}

bool dbSearchByKey(int id, Record* out) {
    FILE* f = _wfopen(g_dbPath, L"rb");
    if (!f) return false;
    bool found = (findInFile(f, id, out) != -1);
    fclose(f);
    return found;
}


// ---------- Добавление ----------

bool addInFile(FILE* f, Record rec) {
    if (findInFile(f, rec.id, NULL) != -1) return false; // ключ уже есть

    long bucketPos = bucketPosOf(rec.id);
    rec.deleted = false;
    rec.next = readLong(f, bucketPos);   // новая запись встает в начало цепочки

    long pos;
    long freeHead = readLong(f, POS_FREE);
    if (freeHead != -1) {                // берем освободившийся слот
        Record old;
        readRecord(f, freeHead, &old);
        writeLong(f, POS_FREE, old.next);
        pos = freeHead;
    } else {                             // иначе пишем в конец файла
        pos = fileSize(f);
    }

    writeRecord(f, pos, &rec);
    writeLong(f, bucketPos, pos);
    writeInt(f, POS_COUNT, readInt(f, POS_COUNT) + 1);
    return true;
}

bool dbAdd(const Record& rec) {
    FILE* f = _wfopen(g_dbPath, L"r+b");
    if (!f) return false;
    bool ok = addInFile(f, rec);
    fclose(f);
    return ok;
}


// ---------- Удаление ----------

bool deleteInFile(FILE* f, int id) {
    long bucketPos = bucketPosOf(id);
    long cur = readLong(f, bucketPos);
    long prev = -1;
    Record r;

    while (cur != -1) {
        if (!readRecord(f, cur, &r)) return false;

        if (r.id == id) {
            // 1. вырезаем запись из цепочки
            if (prev == -1) writeLong(f, bucketPos, r.next);
            else            writeLong(f, prev + POS_NEXT, r.next);

            // 2. кладем слот в список свободных
            r.deleted = true;
            r.next = readLong(f, POS_FREE);
            writeRecord(f, cur, &r);
            writeLong(f, POS_FREE, cur);

            // 3. уменьшаем счетчик
            writeInt(f, POS_COUNT, readInt(f, POS_COUNT) - 1);
            return true;
        }
        prev = cur;
        cur = r.next;
    }
    return false;
}

bool dbDeleteByKey(int id) {
    FILE* f = _wfopen(g_dbPath, L"r+b");
    if (!f) return false;
    bool ok = deleteInFile(f, id);
    fclose(f);
    return ok;
}


// ---------- Неключевые поля ----------

double parseDouble(const wchar_t* text) {
    wchar_t buf[64];
    wcsncpy(buf, text, 63);
    buf[63] = 0;
    for (wchar_t* p = buf; *p; p++) {
        if (*p == L',') *p = L'.';
    }
    return wcstod(buf, NULL);
}

// Содержит ли строка s подстроку part (без учета регистра)
bool containsText(const wchar_t* s, const wchar_t* part) {
    wchar_t a[128], b[128];
    wcsncpy(a, s, 127);    a[127] = 0;
    wcsncpy(b, part, 127); b[127] = 0;
    CharLowerW(a);
    CharLowerW(b);
    return wcsstr(a, b) != NULL;
}

bool isBoolText(const wchar_t* text) {
    wchar_t t[16];
    wcsncpy(t, text, 15);
    t[15] = 0;
    CharLowerW(t);
    return wcscmp(t, L"да") == 0 || wcscmp(t, L"нет") == 0 || wcscmp(t, L"1") == 0 || wcscmp(t, L"0") == 0;
}

bool parseBool(const wchar_t* text) {
    wchar_t t[16];
    wcsncpy(t, text, 15);
    t[15] = 0;
    CharLowerW(t);
    return wcscmp(t, L"да") == 0 || wcscmp(t, L"1") == 0;
}

// Номера полей: 0 - id, 1 - клиент, 2 - упражнение, 3 - подходы, 4 - вес, 5 - выполнено
bool matches(const Record& r, int field, const wchar_t* text) {
    switch (field) {
        case 1: return containsText(r.client, text);
        case 2: return containsText(r.exercise, text);
        case 3: return r.sets == _wtoi(text);
        case 4: return fabs(r.weight - parseDouble(text)) < 0.001;
        case 5: return r.done == parseBool(text);
    }
    return false;
}

// Удаляет ВСЕ записи, совпавшие по неключевому полю. Возвращает их количество.
int dbDeleteByField(int field, const wchar_t* text) {
    FILE* f = _wfopen(g_dbPath, L"r+b");
    if (!f) return 0;

    long size = fileSize(f);
    int count = 0;
    Record r;

    for (long pos = (long)sizeof(Header); pos + (long)sizeof(Record) <= size; pos += (long)sizeof(Record)) {
        if (!readRecord(f, pos, &r)) break;
        if (!r.deleted && matches(r, field, text) && deleteInFile(f, r.id)) {
            count++;
        }
    }
    fclose(f);
    return count;
}


// ---------- Редактирование ----------

bool dbEdit(int oldId, Record rec) {
    FILE* f = _wfopen(g_dbPath, L"r+b");
    if (!f) return false;

    bool ok = false;
    Record old;
    long pos = findInFile(f, oldId, &old);

    if (pos != -1) {
        if (rec.id == oldId) {
            // ключ не менялся - просто перезаписываем на месте
            rec.deleted = false;
            rec.next = old.next;
            writeRecord(f, pos, &rec);
            ok = true;
        } else if (findInFile(f, rec.id, NULL) == -1) {
            // ключ изменился - удаляем старую запись и добавляем новую
            deleteInFile(f, oldId);
            ok = addInFile(f, rec);
        }
    }
    fclose(f);
    return ok;
}


// ---------- Backup, восстановление, экспорт ----------

bool dbBackup(const wchar_t* backupPath) {
    return CopyFileW(g_dbPath, backupPath, FALSE) != 0;
}

bool dbRestore(const wchar_t* backupPath) {
    if (!isValidDbFile(backupPath)) return false;
    if (!CopyFileW(backupPath, g_dbPath, FALSE)) return false;
    g_dbOpened = true;
    return true;
}

void toUtf8(const wchar_t* w, char* out, int size) {
    out[0] = 0;
    WideCharToMultiByte(CP_UTF8, 0, w, -1, out, size, NULL, NULL);
}

// Экспорт в CSV (открывается в Excel)
bool dbExportCsv(const wchar_t* csvPath) {
    FILE* in = _wfopen(g_dbPath, L"rb");
    if (!in) return false;
    FILE* out = _wfopen(csvPath, L"wb");
    if (!out) {
        fclose(in);
        return false;
    }

    char line[256], a[128], b[128], c[16];
    fputs("\xEF\xBB\xBF", out); // BOM, чтобы Excel понял UTF-8
    toUtf8(L"ID;Клиент;Упражнение;Подходы;Вес (кг);Выполнено\r\n", line, sizeof(line));
    fputs(line, out);

    long size = fileSize(in);
    Record r;
    for (long pos = (long)sizeof(Header); pos + (long)sizeof(Record) <= size; pos += (long)sizeof(Record)) {
        if (!readRecord(in, pos, &r)) break;
        if (r.deleted) continue;

        toUtf8(r.client, a, sizeof(a));
        toUtf8(r.exercise, b, sizeof(b));
        toUtf8(r.done ? L"Да" : L"Нет", c, sizeof(c));

        char weight[32];
        sprintf(weight, "%.2f", r.weight);
        for (char* p = weight; *p; p++) {
            if (*p == '.') *p = ','; // для русского Excel
        }
        fprintf(out, "%d;%s;%s;%d;%s;%s\r\n", r.id, a, b, r.sets, weight, c);
    }

    fclose(in);
    fclose(out);
    return true;
}


