// Белая карточка с заголовком
void drawCard(HDC hdc, int x, int y, int w, int h, const wchar_t* title) {
    HPEN pen = CreatePen(PS_SOLID, 1, CLR_BORDER);
    HGDIOBJ oldPen = SelectObject(hdc, pen);
    HGDIOBJ oldBrush = SelectObject(hdc, hBrushCard);
    RoundRect(hdc, x, y, x + w, y + h, 12, 12);
    SelectObject(hdc, oldBrush);
    SelectObject(hdc, oldPen);
    DeleteObject(pen);

    HGDIOBJ oldFont = SelectObject(hdc, hFontBold);
    SetBkMode(hdc, TRANSPARENT);
    SetTextColor(hdc, CLR_TEXT);
    RECT rc = { x + 16, y + 8, x + w - 16, y + 32 };
    DrawTextW(hdc, title, -1, &rc, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    SelectObject(hdc, oldFont);
}


// ---------- Таблица ----------

void setCell(int row, int col, const wchar_t* text) {
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.iSubItem = col;
    item.pszText = (LPWSTR)text;
    SendMessageW(hTable, LVM_SETITEMTEXTW, row, (LPARAM)&item);
}

void addRowToTable(int row, const Record& r) {
    wchar_t num[32];
    char tmp[32];

    _itow(r.id, num, 10);
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.mask = LVIF_TEXT;
    item.iItem = row;
    item.pszText = num;
    SendMessageW(hTable, LVM_INSERTITEMW, 0, (LPARAM)&item);

    setCell(row, 1, r.client);
    setCell(row, 2, r.exercise);

    _itow(r.sets, num, 10);
    setCell(row, 3, num);

    sprintf(tmp, "%.2f", r.weight);
    for (int i = 0; tmp[i]; i++) num[i] = tmp[i], num[i + 1] = 0;
    setCell(row, 4, num);

    setCell(row, 5, r.done ? L"Да" : L"Нет");
}

// Заполняет таблицу из файла. field = -1 - показать все, иначе только совпавшие по полю.
// (Единственное место, где мы читаем файл подряд - это для вывода на экран.)
int loadTable(int field, const wchar_t* text) {
    SendMessageW(hTable, LVM_DELETEALLITEMS, 0, 0);
    if (!g_dbOpened) return 0;

    FILE* f = _wfopen(g_dbPath, L"rb");
    if (!f) return 0;

    long size = fileSize(f);
    int count = 0;
    Record r;

    SendMessageW(hTable, WM_SETREDRAW, FALSE, 0);
    for (long pos = (long)sizeof(Header); pos + (long)sizeof(Record) <= size; pos += (long)sizeof(Record)) {
        if (!readRecord(f, pos, &r)) break;
        if (r.deleted) continue;
        if (field == -1 || matches(r, field, text)) {
            addRowToTable(count++, r);
        }
    }
    SendMessageW(hTable, WM_SETREDRAW, TRUE, 0);
    fclose(f);
    return count;
}

void showAll() {
    if (!g_dbOpened) {
        loadTable(-1, L"");
        setStatus(L"  База данных не открыта. Создайте или откройте БД.");
        return;
    }
    int count = loadTable(-1, L"");
    wchar_t text[MAX_PATH + 64], num[16];
    _itow(count, num, 10);
    wcscpy(text, L"  Файл: ");
    wcscat(text, g_dbPath);
    wcscat(text, L"   |   Записей: ");
    wcscat(text, num);
    setStatus(text);
}


