void clearForm() {
    g_selectedId = -1;
    SetWindowTextW(hEditId, L"");
    SetWindowTextW(hEditClient, L"");
    SetWindowTextW(hEditExercise, L"");
    SetWindowTextW(hEditSets, L"");
    SetWindowTextW(hEditWeight, L"");
    SendMessageW(hChkDone, BM_SETCHECK, BST_UNCHECKED, 0);
}

void fillForm(const Record& r) {
    wchar_t num[32];
    char tmp[32];

    g_selectedId = r.id;
    _itow(r.id, num, 10);
    SetWindowTextW(hEditId, num);
    SetWindowTextW(hEditClient, r.client);
    SetWindowTextW(hEditExercise, r.exercise);
    _itow(r.sets, num, 10);
    SetWindowTextW(hEditSets, num);

    sprintf(tmp, "%g", r.weight);
    for (int i = 0; tmp[i]; i++) num[i] = tmp[i], num[i + 1] = 0;
    SetWindowTextW(hEditWeight, num);

    SendMessageW(hChkDone, BM_SETCHECK, r.done ? BST_CHECKED : BST_UNCHECKED, 0);
}

// Читает и проверяет форму
bool readForm(HWND hwnd, Record* out) {
    wchar_t id[16], client[64], exercise[64], sets[16], weight[32];
    GetWindowTextW(hEditId, id, 16);
    GetWindowTextW(hEditClient, client, 64);
    GetWindowTextW(hEditExercise, exercise, 64);
    GetWindowTextW(hEditSets, sets, 16);
    GetWindowTextW(hEditWeight, weight, 32);

    if (!id[0] || !client[0] || !exercise[0] || !sets[0] || !weight[0]) {
        msg(hwnd, L"Заполните все поля записи!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(id, false) || _wtoi(id) <= 0) {
        msg(hwnd, L"ID должен быть положительным целым числом!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(sets, false) || _wtoi(sets) < 1 || _wtoi(sets) > 30) {
        msg(hwnd, L"Количество подходов - целое число от 1 до 30!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(weight, true) || parseDouble(weight) > 500.0) {
        msg(hwnd, L"Вес - число от 0 до 500 кг!", MB_ICONWARNING);
        return false;
    }

    bool done = (SendMessageW(hChkDone, BM_GETCHECK, 0, 0) == BST_CHECKED);
    *out = makeRecord(_wtoi(id), client, exercise, _wtoi(sets), parseDouble(weight), done);
    return true;
}

// Пользователь выбрал строку в таблице - берем полную запись из файла по ключу
void onRowSelected(int row) {
    wchar_t text[32];
    text[0] = 0;
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.iSubItem = 0;
    item.pszText = text;
    item.cchTextMax = 32;
    SendMessageW(hTable, LVM_GETITEMTEXTW, row, (LPARAM)&item);

    Record r;
    if (dbSearchByKey(_wtoi(text), &r)) fillForm(r);
}


// ---------- Обработчики кнопок ----------

void onCreateDb(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_DB, L"db")) return;

    if (createEmptyFile(path)) {
        useDb(path);
        clearForm();
        showAll();
    } else {
        msg(hwnd, L"Не удалось создать файл БД!", MB_ICONERROR);
    }
}

void onOpenDb(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, false, FILTER_DB, L"db")) return;

    if (dbOpen(path)) {
        clearForm();
        showAll();
    } else {
        msg(hwnd, L"Это не файл базы данных этой программы!", MB_ICONERROR);
    }
}

void onSaveAs(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_DB, L"db")) return;

    if (CopyFileW(g_dbPath, path, FALSE)) {
        useDb(path);
        showAll();
        msg(hwnd, L"База данных сохранена.");
    } else {
        msg(hwnd, L"Не удалось сохранить файл!", MB_ICONERROR);
    }
}

void onBackup(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_BAK, L"bak")) return;

    if (dbBackup(path)) msg(hwnd, L"Backup-файл создан.");
    else                msg(hwnd, L"Не удалось создать backup!", MB_ICONERROR);
}

void onRestore(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, false, FILTER_BAK, L"bak")) return;
    if (!ask(hwnd, L"Текущая база будет заменена данными из backup. Продолжить?")) return;

    if (dbRestore(path)) {
        clearForm();
        showAll();
        msg(hwnd, L"База данных восстановлена из backup.");
    } else {
        msg(hwnd, L"Не удалось восстановить: это не backup этой программы.", MB_ICONERROR);
    }
}

void onClearDb(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Удалить ВСЕ записи из базы?")) return;

    if (dbClear()) {
        clearForm();
        showAll();
    }
}

void onDropDb(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Удалить файл базы данных с диска?")) return;

    if (dbDrop()) {
        clearForm();
        showAll();
    }
}

void onExport(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_CSV, L"csv")) return;

