void onAdd(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"Сначала создайте или откройте БД!", MB_ICONERROR); return; }

    Record rec;
    if (!readForm(hwnd, &rec)) return;

    if (dbAdd(rec)) {
        showAll();
        setStatus(L"  Запись добавлена.");
    } else {
        msg(hwnd, L"Запись с таким ID уже существует!", MB_ICONERROR);
    }
}

void onEdit(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (g_selectedId == -1) {
        msg(hwnd, L"Сначала выберите запись в таблице!", MB_ICONWARNING);
        return;
    }

    Record rec;
    if (!readForm(hwnd, &rec)) return;

    if (dbEdit(g_selectedId, rec)) {
        g_selectedId = rec.id;
        showAll();
        setStatus(L"  Запись изменена.");
    } else {
        msg(hwnd, L"Не удалось изменить запись (новый ID уже занят).", MB_ICONERROR);
    }
}

// Читает поле и значение из блока "Поиск и удаление"
bool readSearchInput(HWND hwnd, int* field, wchar_t* text) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return false; }

    *field = (int)SendMessageW(hComboField, CB_GETCURSEL, 0, 0);
    GetWindowTextW(hEditQuery, text, 64);

    if (!text[0]) {
        msg(hwnd, L"Введите значение!", MB_ICONWARNING);
        return false;
    }
    if (*field == 5 && !isBoolText(text)) {
        msg(hwnd, L"Для поля «Выполнено» введите Да или Нет.", MB_ICONWARNING);
        return false;
    }
    return true;
}

void onSearch(HWND hwnd) {
    int field;
    wchar_t text[64];
    if (!readSearchInput(hwnd, &field, text)) return;

    int found = 0;
    if (field == 0) {                       // по ключу - быстрый поиск через хеш
        Record r;
        SendMessageW(hTable, LVM_DELETEALLITEMS, 0, 0);
        if (dbSearchByKey(_wtoi(text), &r)) {
            addRowToTable(0, r);
            found = 1;
        }
    } else {                                // по неключевому - ищем все совпадения
        found = loadTable(field, text);
    }
    setStatusNumber(L"  Найдено записей: ", found);
}

void onDelete(HWND hwnd) {
    int field;
    wchar_t text[64];
    if (!readSearchInput(hwnd, &field, text)) return;

    if (!ask(hwnd, L"Удалить найденные записи?")) return;

    int deleted = 0;
    if (field == 0) deleted = dbDeleteByKey(_wtoi(text)) ? 1 : 0;
    else            deleted = dbDeleteByField(field, text);

    clearForm();
    showAll();
    if (deleted == 0) msg(hwnd, L"Записей с таким значением не найдено.");
    else              setStatusNumber(L"  Удалено записей: ", deleted);
}


