// Цветная кнопка вместо серых кнопок Windows
void drawButton(LPDRAWITEMSTRUCT dis) {
    HDC hdc = dis->hDC;
    RECT rc = dis->rcItem;
    bool pressed = (dis->itemState & ODS_SELECTED) != 0;

    COLORREF bg = pressed ? RGB(222, 229, 238) : CLR_GRAY;
    COLORREF textColor = CLR_TEXT;
    COLORREF border = RGB(205, 215, 228);

    if (dis->CtlID == ID_BTN_ADD || dis->CtlID == ID_BTN_SEARCH) {
        bg = pressed ? RGB(37, 99, 235) : CLR_BLUE;
        textColor = RGB(255, 255, 255);
        border = bg;
    } else if (dis->CtlID == ID_BTN_DELETE || dis->CtlID == ID_BTN_DROP_DB) {
        bg = pressed ? RGB(220, 38, 38) : CLR_RED;
        textColor = RGB(255, 255, 255);
        border = bg;
    }

    FillRect(hdc, &rc, hBrushCard); // закрашиваем уголки цветом карточки

    HBRUSH brush = CreateSolidBrush(bg);
    HPEN pen = CreatePen(PS_SOLID, 1, border);
    HGDIOBJ oldBrush = SelectObject(hdc, brush);
    HGDIOBJ oldPen = SelectObject(hdc, pen);
    RoundRect(hdc, rc.left, rc.top, rc.right, rc.bottom, 8, 8);
    SelectObject(hdc, oldBrush);
    SelectObject(hdc, oldPen);
    DeleteObject(brush);
    DeleteObject(pen);

    wchar_t text[64];
    GetWindowTextW(dis->hwndItem, text, 64);
    SetBkMode(hdc, TRANSPARENT);
    SetTextColor(hdc, textColor);
    HGDIOBJ oldFont = SelectObject(hdc, hFontNormal);
    DrawTextW(hdc, text, -1, &rc, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    SelectObject(hdc, oldFont);
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam) {
    switch (message) {
        case WM_CREATE:
            onCreateWindow(hwnd);
            return 0;

        case WM_PAINT: {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hwnd, &ps);
            drawCard(hdc, 14, 10,  972, 78,  L"База данных");
            drawCard(hdc, 14, 98,  350, 292, L"Запись");
            drawCard(hdc, 14, 400, 350, 232, L"Поиск и удаление");
            drawCard(hdc, 374, 98, 612, 534, L"Журнал тренировок");
            EndPaint(hwnd, &ps);
            return 0;
        }

        case WM_DRAWITEM:
            drawButton((LPDRAWITEMSTRUCT)lParam);
            return TRUE;

        case WM_CTLCOLORSTATIC:
        case WM_CTLCOLORBTN: {
            HDC hdc = (HDC)wParam;
            SetTextColor(hdc, CLR_TEXT);
            if ((HWND)lParam == hStatus) {
                SetBkColor(hdc, CLR_WINDOW_BG);
                return (LRESULT)hBrushWindow;
            }
            SetBkColor(hdc, CLR_CARD_BG);
            return (LRESULT)hBrushCard;
        }

        case WM_CTLCOLOREDIT: {
            HDC hdc = (HDC)wParam;
            SetTextColor(hdc, CLR_TEXT);
            SetBkColor(hdc, CLR_INPUT_BG);
            return (LRESULT)hBrushInput;
        }

        case WM_NOTIFY: {
            LPNMHDR nm = (LPNMHDR)lParam;
            if (nm->idFrom != ID_TABLE) break;

            // Чередование цвета строк
            if (nm->code == NM_CUSTOMDRAW) {
                LPNMLVCUSTOMDRAW cd = (LPNMLVCUSTOMDRAW)lParam;
                if (cd->nmcd.dwDrawStage == CDDS_PREPAINT) return CDRF_NOTIFYITEMDRAW;
                if (cd->nmcd.dwDrawStage == CDDS_ITEMPREPAINT) {
                    cd->clrTextBk = (cd->nmcd.dwItemSpec % 2 == 0) ? RGB(255, 255, 255) : RGB(244, 248, 254);
                    cd->clrText = CLR_TEXT;
                    return CDRF_NEWFONT;
                }
            }

            // Выбор строки
            if (nm->code == LVN_ITEMCHANGED) {
                LPNMLISTVIEW info = (LPNMLISTVIEW)lParam;
                if ((info->uChanged & LVIF_STATE) && (info->uNewState & LVIS_SELECTED)) {
                    onRowSelected(info->iItem);
                }
            }
            break;
        }

        case WM_COMMAND:
            switch (LOWORD(wParam)) {
                case ID_BTN_CREATE:     onCreateDb(hwnd);  break;
                case ID_BTN_OPEN:       onOpenDb(hwnd);    break;
                case ID_BTN_SAVE_AS:    onSaveAs(hwnd);    break;
                case ID_BTN_BACKUP:     onBackup(hwnd);    break;
                case ID_BTN_RESTORE:    onRestore(hwnd);   break;
                case ID_BTN_CLEAR_DB:   onClearDb(hwnd);   break;
                case ID_BTN_DROP_DB:    onDropDb(hwnd);    break;
                case ID_BTN_EXPORT:     onExport(hwnd);    break;
                case ID_BTN_ADD:        onAdd(hwnd);       break;
                case ID_BTN_EDIT:       onEdit(hwnd);      break;
                case ID_BTN_CLEAR_FORM: clearForm();       break;
                case ID_BTN_SEARCH:     onSearch(hwnd);    break;
                case ID_BTN_DELETE:     onDelete(hwnd);    break;
                case ID_BTN_SHOW_ALL:   showAll();         break;
            }
            return 0;

        case WM_DESTROY:
            DeleteObject(hFontNormal);
            DeleteObject(hFontBold);
            DeleteObject(hBrushWindow);
            DeleteObject(hBrushCard);
            DeleteObject(hBrushInput);
            PostQuitMessage(0);
            return 0;
    }
    return DefWindowProcW(hwnd, message, wParam, lParam);
}

int WINAPI WinMain(HINSTANCE hInstance, HINSTANCE, LPSTR, int nCmdShow) {
    INITCOMMONCONTROLSEX icc;
    icc.dwSize = sizeof(icc);
    icc.dwICC = ICC_LISTVIEW_CLASSES;
    InitCommonControlsEx(&icc);

    hBrushWindow = CreateSolidBrush(CLR_WINDOW_BG);
    hBrushCard   = CreateSolidBrush(CLR_CARD_BG);
    hBrushInput  = CreateSolidBrush(CLR_INPUT_BG);

    WNDCLASSEXW wc;
    ZeroMemory(&wc, sizeof(wc));
    wc.cbSize = sizeof(wc);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInstance;
    wc.hCursor = LoadCursor(NULL, IDC_ARROW);
    wc.hIcon = LoadIcon(NULL, IDI_APPLICATION);
    wc.hbrBackground = hBrushWindow;
    wc.lpszClassName = L"WorkoutDbWindow";
    if (!RegisterClassExW(&wc)) return 0;

    // Размер окна считаем так, чтобы рабочая область была ровно 1000 x 676
    DWORD style = WS_OVERLAPPED | WS_CAPTION | WS_SYSMENU | WS_MINIMIZEBOX;
    RECT rc = { 0, 0, 1000, 676 };
    AdjustWindowRect(&rc, style, FALSE);

    HWND hwnd = CreateWindowExW(0, L"WorkoutDbWindow", WINDOW_TITLE, style,
        CW_USEDEFAULT, CW_USEDEFAULT, rc.right - rc.left, rc.bottom - rc.top,
        NULL, NULL, hInstance, NULL);

    ShowWindow(hwnd, nCmdShow);
    UpdateWindow(hwnd);

    MSG m;
    while (GetMessageW(&m, NULL, 0, 0) > 0) {
        TranslateMessage(&m);
        DispatchMessageW(&m);
    }
    return (int)m.wParam;
}

