// "<prefix> N" в строку состояния
void setStatusNumber(const wchar_t* prefix, int n) {
    wchar_t num[16], text[300];
    _itow(n, num, 10);
    wcscpy(text, prefix);
    wcscat(text, num);
    setStatus(text);
}

// Только цифры (и, если allowDot, одна точка или запятая)
bool isNumber(const wchar_t* s, bool allowDot) {
    if (!*s) return false;
    int dots = 0;
    for (; *s; s++) {
        if (*s == L'.' || *s == L',') dots++;
        else if (*s < L'0' || *s > L'9') return false;
    }
    return dots == 0 || (allowDot && dots == 1);
}

bool chooseFile(HWND hwnd, wchar_t* path, bool save, const wchar_t* filter, const wchar_t* defExt) {
    OPENFILENAMEW ofn;
    ZeroMemory(&ofn, sizeof(ofn));
    path[0] = 0;
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = hwnd;
    ofn.lpstrFilter = filter;
    ofn.lpstrFile = path;
    ofn.nMaxFile = MAX_PATH;
    ofn.lpstrDefExt = defExt;
    ofn.Flags = OFN_NOCHANGEDIR | (save ? OFN_OVERWRITEPROMPT : OFN_FILEMUSTEXIST);
    return (save ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn)) != 0;
}


