// Белая карточка с заголовком
void drawCard(HDC hdc, int x, int y, int w, int h, const wchar_t* title) {
    HPEN pen = CreatePen(PS_SOLID, 1, CLR_BORDER);
    HGDIOBJ oldPen = SelectObject(hdc, pen);
    HGDIOBJ oldBrush = SelectObject(hdc, hBrushCard);
    RoundRect(hdc, x, y, x + w, y + h, 12, 12);
    SelectObject(hdc, oldBrush);
    SelectObject(hdc, oldPen);
    DeleteObject(pen);

    HGDIOBJ oldFont = SelectObject(hdc, hFontBold);
    SetBkMode(hdc, TRANSPARENT);
    SetTextColor(hdc, CLR_TEXT);
    RECT rc = { x + 16, y + 8, x + w - 16, y + 32 };
    DrawTextW(hdc, title, -1, &rc, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    SelectObject(hdc, oldFont);
}


// ---------- Таблица ----------

void setCell(int row, int col, const wchar_t* text) {
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.iSubItem = col;
    item.pszText = (LPWSTR)text;
    SendMessageW(hTable, LVM_SETITEMTEXTW, row, (LPARAM)&item);
}

void addRowToTable(int row, const Record& r) {
    wchar_t num[32];
    char tmp[32];

    _itow(r.id, num, 10);
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.mask = LVIF_TEXT;
    item.iItem = row;
    item.pszText = num;
    SendMessageW(hTable, LVM_INSERTITEMW, 0, (LPARAM)&item);

    setCell(row, 1, r.client);
    setCell(row, 2, r.exercise);

    _itow(r.sets, num, 10);
    setCell(row, 3, num);

    sprintf(tmp, "%.2f", r.weight);
    for (int i = 0; tmp[i]; i++) num[i] = tmp[i], num[i + 1] = 0;
    setCell(row, 4, num);

    setCell(row, 5, r.done ? L"Да" : L"Нет");
}

// Заполняет таблицу из файла. field = -1 - показать все, иначе только совпавшие по полю.
// (Единственное место, где мы читаем файл подряд - это для вывода на экран.)
int loadTable(int field, const wchar_t* text) {
    SendMessageW(hTable, LVM_DELETEALLITEMS, 0, 0);
    if (!g_dbOpened) return 0;

    FILE* f = _wfopen(g_dbPath, L"rb");
    if (!f) return 0;

    long size = fileSize(f);
    int count = 0;
    Record r;

    SendMessageW(hTable, WM_SETREDRAW, FALSE, 0);
    for (long pos = (long)sizeof(Header); pos + (long)sizeof(Record) <= size; pos += (long)sizeof(Record)) {
        if (!readRecord(f, pos, &r)) break;
        if (r.deleted) continue;
        if (field == -1 || matches(r, field, text)) {
            addRowToTable(count++, r);
        }
    }
    SendMessageW(hTable, WM_SETREDRAW, TRUE, 0);
    fclose(f);
    return count;
}

void showAll() {
    if (!g_dbOpened) {
        loadTable(-1, L"");
        setStatus(L"  База данных не открыта. Создайте или откройте БД.");
        return;
    }
    int count = loadTable(-1, L"");
    wchar_t text[MAX_PATH + 64], num[16];
    _itow(count, num, 10);
    wcscpy(text, L"  Файл: ");
    wcscat(text, g_dbPath);
    wcscat(text, L"   |   Записей: ");
    wcscat(text, num);
    setStatus(text);
}


// ---------- Форма ----------

void clearForm() {
    g_selectedId = -1;
    SetWindowTextW(hEditId, L"");
    SetWindowTextW(hEditClient, L"");
    SetWindowTextW(hEditExercise, L"");
    SetWindowTextW(hEditSets, L"");
    SetWindowTextW(hEditWeight, L"");
    SendMessageW(hChkDone, BM_SETCHECK, BST_UNCHECKED, 0);
}

void fillForm(const Record& r) {
    wchar_t num[32];
    char tmp[32];

    g_selectedId = r.id;
    _itow(r.id, num, 10);
    SetWindowTextW(hEditId, num);
    SetWindowTextW(hEditClient, r.client);
    SetWindowTextW(hEditExercise, r.exercise);
    _itow(r.sets, num, 10);
    SetWindowTextW(hEditSets, num);

    sprintf(tmp, "%g", r.weight);
    for (int i = 0; tmp[i]; i++) num[i] = tmp[i], num[i + 1] = 0;
    SetWindowTextW(hEditWeight, num);

    SendMessageW(hChkDone, BM_SETCHECK, r.done ? BST_CHECKED : BST_UNCHECKED, 0);
}

// Читает и проверяет форму
bool readForm(HWND hwnd, Record* out) {
    wchar_t id[16], client[64], exercise[64], sets[16], weight[32];
    GetWindowTextW(hEditId, id, 16);
    GetWindowTextW(hEditClient, client, 64);
    GetWindowTextW(hEditExercise, exercise, 64);
    GetWindowTextW(hEditSets, sets, 16);
    GetWindowTextW(hEditWeight, weight, 32);

    if (!id[0] || !client[0] || !exercise[0] || !sets[0] || !weight[0]) {
        msg(hwnd, L"Заполните все поля записи!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(id, false) || _wtoi(id) <= 0) {
        msg(hwnd, L"ID должен быть положительным целым числом!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(sets, false) || _wtoi(sets) < 1 || _wtoi(sets) > 30) {
        msg(hwnd, L"Количество подходов - целое число от 1 до 30!", MB_ICONWARNING);
        return false;
    }
    if (!isNumber(weight, true) || parseDouble(weight) > 500.0) {
        msg(hwnd, L"Вес - число от 0 до 500 кг!", MB_ICONWARNING);
        return false;
    }

    bool done = (SendMessageW(hChkDone, BM_GETCHECK, 0, 0) == BST_CHECKED);
    *out = makeRecord(_wtoi(id), client, exercise, _wtoi(sets), parseDouble(weight), done);
    return true;
}

// Пользователь выбрал строку в таблице - берем полную запись из файла по ключу
void onRowSelected(int row) {
    wchar_t text[32];
    text[0] = 0;
    LVITEMW item;
    memset(&item, 0, sizeof(item));
    item.iSubItem = 0;
    item.pszText = text;
    item.cchTextMax = 32;
    SendMessageW(hTable, LVM_GETITEMTEXTW, row, (LPARAM)&item);

    Record r;
    if (dbSearchByKey(_wtoi(text), &r)) fillForm(r);
}


// ---------- Обработчики кнопок ----------

void onCreateDb(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_DB, L"db")) return;

    if (createEmptyFile(path)) {
        useDb(path);
        clearForm();
        showAll();
    } else {
        msg(hwnd, L"Не удалось создать файл БД!", MB_ICONERROR);
    }
}

void onOpenDb(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, false, FILTER_DB, L"db")) return;

    if (dbOpen(path)) {
        clearForm();
        showAll();
    } else {
        msg(hwnd, L"Это не файл базы данных этой программы!", MB_ICONERROR);
    }
}

void onSaveAs(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_DB, L"db")) return;

    if (CopyFileW(g_dbPath, path, FALSE)) {
        useDb(path);
        showAll();
        msg(hwnd, L"База данных сохранена.");
    } else {
        msg(hwnd, L"Не удалось сохранить файл!", MB_ICONERROR);
    }
}

void onBackup(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_BAK, L"bak")) return;

    if (dbBackup(path)) msg(hwnd, L"Backup-файл создан.");
    else                msg(hwnd, L"Не удалось создать backup!", MB_ICONERROR);
}

void onRestore(HWND hwnd) {
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, false, FILTER_BAK, L"bak")) return;
    if (!ask(hwnd, L"Текущая база будет заменена данными из backup. Продолжить?")) return;

    if (dbRestore(path)) {
        clearForm();
        showAll();
        msg(hwnd, L"База данных восстановлена из backup.");
    } else {
        msg(hwnd, L"Не удалось восстановить: это не backup этой программы.", MB_ICONERROR);
    }
}

void onClearDb(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Удалить ВСЕ записи из базы?")) return;

    if (dbClear()) {
        clearForm();
        showAll();
    }
}

void onDropDb(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Удалить файл базы данных с диска?")) return;

    if (dbDrop()) {
        clearForm();
        showAll();
    }
}

void onExport(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    wchar_t path[MAX_PATH];
    if (!chooseFile(hwnd, path, true, FILTER_CSV, L"csv")) return;

    if (dbExportCsv(path)) msg(hwnd, L"Экспорт выполнен. Файл можно открыть в Excel.");
    else                   msg(hwnd, L"Не удалось записать файл!", MB_ICONERROR);
}

void onAdd(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"Сначала создайте или откройте БД!", MB_ICONERROR); return; }

    Record rec;
    if (!readForm(hwnd, &rec)) return;

    if (dbAdd(rec)) {
        showAll();
        setStatus(L"  Запись добавлена.");
    } else {
        msg(hwnd, L"Запись с таким ID уже существует!", MB_ICONERROR);
    }
}

void onEdit(HWND hwnd) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return; }
    if (g_selectedId == -1) {
        msg(hwnd, L"Сначала выберите запись в таблице!", MB_ICONWARNING);
        return;
    }

    Record rec;
    if (!readForm(hwnd, &rec)) return;

    if (dbEdit(g_selectedId, rec)) {
        g_selectedId = rec.id;
        showAll();
        setStatus(L"  Запись изменена.");
    } else {
        msg(hwnd, L"Не удалось изменить запись (новый ID уже занят).", MB_ICONERROR);
    }
}

// Читает поле и значение из блока "Поиск и удаление"
bool readSearchInput(HWND hwnd, int* field, wchar_t* text) {
    if (!g_dbOpened) { msg(hwnd, L"База данных не открыта!", MB_ICONERROR); return false; }

    *field = (int)SendMessageW(hComboField, CB_GETCURSEL, 0, 0);
    GetWindowTextW(hEditQuery, text, 64);

    if (!text[0]) {
        msg(hwnd, L"Введите значение!", MB_ICONWARNING);
        return false;
    }
    if (*field == 5 && !isBoolText(text)) {
        msg(hwnd, L"Для поля «Выполнено» введите Да или Нет.", MB_ICONWARNING);
        return false;
    }
    return true;
}

void onSearch(HWND hwnd) {
    int field;
    wchar_t text[64];
    if (!readSearchInput(hwnd, &field, text)) return;

    int found = 0;
    if (field == 0) {                       // по ключу - быстрый поиск через хеш
        Record r;
        SendMessageW(hTable, LVM_DELETEALLITEMS, 0, 0);
        if (dbSearchByKey(_wtoi(text), &r)) {
            addRowToTable(0, r);
            found = 1;
        }
    } else {                                // по неключевому - ищем все совпадения
        found = loadTable(field, text);
    }
    setStatusNumber(L"  Найдено записей: ", found);
}

void onDelete(HWND hwnd) {
    int field;
    wchar_t text[64];
    if (!readSearchInput(hwnd, &field, text)) return;

    if (!ask(hwnd, L"Удалить найденные записи?")) return;

    int deleted = 0;
    if (field == 0) deleted = dbDeleteByKey(_wtoi(text)) ? 1 : 0;
    else            deleted = dbDeleteByField(field, text);

    clearForm();
    showAll();
    if (deleted == 0) msg(hwnd, L"Записей с таким значением не найдено.");
    else              setStatusNumber(L"  Удалено записей: ", deleted);
}


