#include <windows.h>
#include <commctrl.h>
#include <fstream>
#include <string>
#include <sstream>
#include <iomanip>
#include <filesystem>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <algorithm>
#pragma comment(lib, "Comdlg32.lib")
#pragma comment(lib, "Comctl32.lib")

using namespace std;

const int HASH_TABLE_SIZE = 1009;       // Количество корзин хеш-таблицы (простое число)
const int FILE_SIGNATURE  = 0x57444231; // Сигнатура нашего файла БД ("WDB1")
const int MAX_TEXT_LEN    = 32;         // Фиксированный размер текстовых полей для бинарной записи

// Заголовок бинарного файла (лежит в самом начале файла, с 0-го байта)
struct FileHeader {
    int  signature;                   // Метка файла для проверки формата
    int  activeRecordsCount;          // Количество активных записей
    long firstFreeSlotOffset;         // Смещение первой удаленной записи (-1, если удаленных нет)
    long buckets[HASH_TABLE_SIZE];    // Массив корзин (хранит смещения первых записей цепочек)
};

// Структура одной записи в файле (6 полей 4 разных типов + 2 служебных поля)
struct WorkoutRecord {
    int     id;                             // КЛЮЧЕВОЕ ПОЛЕ: уникальный ID записи (int)
    wchar_t clientName[MAX_TEXT_LEN];       // Клиент и его цель (текст фиксированной длины)
    wchar_t exerciseName[MAX_TEXT_LEN];     // Упражнение (текст фиксированной длины)
    int     setsCount;                      // Количество подходов (int)
    double  workingWeight;                  // Рабочий вес снаряда в кг (double)
    bool    isCompleted;                    // Выполнено ли упражнение в журнале (bool)
    bool    isDeleted;                      // Служебное поле: true, если запись удалена
    long    nextRecordOffset;               // Служебное поле: смещение следующей записи в цепочке
};

wstring g_currentDbPath = L"trainings.db";  // Путь к текущему открытому файлу БД
bool    g_isDbOpen      = false;            // Открыта ли база данных
int getHashIndex(int id) {
    // Остаток нормализуется без abs(), который переполняется для INT_MIN.
    int index = id % HASH_TABLE_SIZE;
    return index < 0 ? index + HASH_TABLE_SIZE : index;
}

WorkoutRecord makeWorkoutRecord(int id, const wstring& client, const wstring& exercise, int sets, double weight, bool completed) {
    WorkoutRecord rec = {};
    rec.id = id;
    wcsncpy_s(rec.clientName, MAX_TEXT_LEN, client.c_str(), _TRUNCATE);
    wcsncpy_s(rec.exerciseName, MAX_TEXT_LEN, exercise.c_str(), _TRUNCATE);
    rec.setsCount = sets;
    rec.workingWeight = weight;
    rec.isCompleted = completed;
    rec.isDeleted = false;
    rec.nextRecordOffset = -1;
    return rec;
}

bool createDatabaseFile(const wstring& path) {
    ofstream file(filesystem::path(path), ios::binary | ios::trunc);
    if (!file.is_open()) return false;

    FileHeader header;
    header.signature = FILE_SIGNATURE;
    header.activeRecordsCount = 0;
    header.firstFreeSlotOffset = -1;
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        header.buckets[i] = -1;
    }

    file.write(reinterpret_cast<const char*>(&header), sizeof(FileHeader));
    file.flush();
    return file.good();
}
bool isValidDatabaseFile(const wstring& path) {
    ifstream file(filesystem::path(path), ios::binary);
    if (!file.is_open()) return false;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE || header.activeRecordsCount < 0) return false;

    file.seekg(0, ios::end);
    streamoff fileSize = file.tellg();
    if (fileSize < static_cast<streamoff>(sizeof(FileHeader))) return false;
    streamoff recordsBytes = fileSize - static_cast<streamoff>(sizeof(FileHeader));
    if (recordsBytes % static_cast<streamoff>(sizeof(WorkoutRecord)) != 0) return false;

    const long firstRecordOffset = static_cast<long>(sizeof(FileHeader));
    const long endOffset = static_cast<long>(fileSize);
    auto validOffset = [&](long offset) {
        return offset == -1 || (offset >= firstRecordOffset && offset < endOffset &&
            (offset - firstRecordOffset) % static_cast<long>(sizeof(WorkoutRecord)) == 0);
    };
    if (!validOffset(header.firstFreeSlotOffset)) return false;
    for (long offset : header.buckets) if (!validOffset(offset)) return false;

    int activeCount = 0;
    file.clear();
    file.seekg(sizeof(FileHeader), ios::beg);
    WorkoutRecord rec = {};
    while (file.read(reinterpret_cast<char*>(&rec), sizeof(rec))) {
        if (!validOffset(rec.nextRecordOffset)) return false;
        if (!rec.isDeleted) ++activeCount;
    }
    if (!file.eof() || activeCount != header.activeRecordsCount) return false;
    return true;
}

bool openDatabaseFile(const wstring& path) {
    if (!isValidDatabaseFile(path)) return false;
    g_currentDbPath = path;
    g_isDbOpen = true;
    return true;
}
long findRecordOffset(fstream& file, const FileHeader& header, int searchId, WorkoutRecord* outRecord = nullptr) {
    int bucket = getHashIndex(searchId);
    long currentOffset = header.buckets[bucket];
    WorkoutRecord rec;
    while (currentOffset != -1) {
        file.seekg(currentOffset, ios::beg);
        file.read(reinterpret_cast<char*>(&rec), sizeof(WorkoutRecord));
        if (!file.good()) break;

        if (!rec.isDeleted && rec.id == searchId) {
            if (outRecord != nullptr) *outRecord = rec;
            return currentOffset;
        }
        currentOffset = rec.nextRecordOffset;
    }
    return -1;
}
bool searchRecordByKey(int searchId, WorkoutRecord& outRecord) {
    fstream file(filesystem::path(g_currentDbPath), ios::in | ios::binary);
    if (!file.is_open()) return false;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE) return false;
    return findRecordOffset(file, header, searchId, &outRecord) != -1;
}
bool addRecordToDatabase(WorkoutRecord newRec) {
    fstream file(filesystem::path(g_currentDbPath), ios::in | ios::out | ios::binary);
    if (!file.is_open()) return false;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE || newRec.id <= 0 ||
        newRec.setsCount < 1 || newRec.setsCount > 30 ||
        !std::isfinite(newRec.workingWeight) || newRec.workingWeight < 0.0 || newRec.workingWeight > 500.0) {
        return false;
    }
    if (findRecordOffset(file, header, newRec.id) != -1) {
        return false;
    }
    int bucket = getHashIndex(newRec.id);
    newRec.isDeleted = false;
    newRec.nextRecordOffset = header.buckets[bucket];

    long insertOffset = -1;
    if (header.firstFreeSlotOffset != -1) {
        insertOffset = header.firstFreeSlotOffset;
        WorkoutRecord deletedRec;
        file.seekg(insertOffset, ios::beg);
        file.read(reinterpret_cast<char*>(&deletedRec), sizeof(WorkoutRecord));
        if (!file || !deletedRec.isDeleted) return false;
        header.firstFreeSlotOffset = deletedRec.nextRecordOffset;
    } else {
        file.seekp(0, ios::end);
        insertOffset = static_cast<long>(file.tellp());
    }

    file.seekp(insertOffset, ios::beg);
    file.write(reinterpret_cast<const char*>(&newRec), sizeof(WorkoutRecord));
    if (!file) return false;

    header.buckets[bucket] = insertOffset;
    header.activeRecordsCount++;
    file.seekp(0, ios::beg);
    file.write(reinterpret_cast<const char*>(&header), sizeof(FileHeader));
    return file.good();
}

bool deleteByKeyInStream(fstream& file, FileHeader& header, int targetId) {
    int bucket = getHashIndex(targetId);
    long currentOffset = header.buckets[bucket];
    long prevOffset = -1;

    WorkoutRecord rec;
    while (currentOffset != -1) {
        file.seekg(currentOffset, ios::beg);
        file.read(reinterpret_cast<char*>(&rec), sizeof(WorkoutRecord));
        if (!file.good()) return false;

        if (!rec.isDeleted && rec.id == targetId) {
            // Перекидываем указатель в цепочке коллизий в обход удаляемой записи
            if (prevOffset == -1) {
                header.buckets[bucket] = rec.nextRecordOffset;
            } else {
                WorkoutRecord prevRec;
                file.seekg(prevOffset, ios::beg);
                file.read(reinterpret_cast<char*>(&prevRec), sizeof(WorkoutRecord));
                prevRec.nextRecordOffset = rec.nextRecordOffset;
                file.seekp(prevOffset, ios::beg);
                file.write(reinterpret_cast<const char*>(&prevRec), sizeof(WorkoutRecord));
            }

            // Помечаем запись удаленной и помещаем слот в голову списка свободных мест
            rec.isDeleted = true;
            rec.nextRecordOffset = header.firstFreeSlotOffset;
            file.seekp(currentOffset, ios::beg);
            file.write(reinterpret_cast<const char*>(&rec), sizeof(WorkoutRecord));

            header.firstFreeSlotOffset = currentOffset;
            header.activeRecordsCount--;
            file.seekp(0, ios::beg);
            file.write(reinterpret_cast<const char*>(&header), sizeof(FileHeader));
            return true;
        }
        prevOffset = currentOffset;
        currentOffset = rec.nextRecordOffset;
    }
    return false;
}

bool deleteRecordByKey(int targetId) {
    fstream file(filesystem::path(g_currentDbPath), ios::in | ios::out | ios::binary);
    if (!file.is_open()) return false;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE) return false;
    return deleteByKeyInStream(file, header, targetId);
}

bool editRecordInDatabase(int oldId, WorkoutRecord updatedRec) {
    fstream file(filesystem::path(g_currentDbPath), ios::in | ios::out | ios::binary);
    if (!file.is_open()) return false;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE) return false;

    WorkoutRecord existingRec;
    long offset = findRecordOffset(file, header, oldId, &existingRec);
    if (offset == -1) return false;

    if (updatedRec.id == oldId) {

        updatedRec.isDeleted = false;
        updatedRec.nextRecordOffset = existingRec.nextRecordOffset;
        file.seekp(offset, ios::beg);
        file.write(reinterpret_cast<const char*>(&updatedRec), sizeof(WorkoutRecord));
        return file.good();
    }

    if (findRecordOffset(file, header, updatedRec.id) != -1) return false;
    if (!deleteByKeyInStream(file, header, oldId)) return false;
    file.close();
    if (addRecordToDatabase(updatedRec)) return true;

    // При ошибке вставки стараемся вернуть исходную запись.
    existingRec.isDeleted = false;
    existingRec.nextRecordOffset = -1;
    addRecordToDatabase(existingRec);
    return false;
}

wstring toLowerString(wstring str) {
    for (wchar_t& ch : str) ch = towlower(ch);
    return str;
}

bool matchesNonKeyField(const WorkoutRecord& rec, int fieldIndex, const wstring& query) {
    wstring qLower = toLowerString(query);
    try {
        switch (fieldIndex) {
            case 1: return toLowerString(rec.clientName).find(qLower) != wstring::npos;
            case 2: return toLowerString(rec.exerciseName).find(qLower) != wstring::npos;
            case 3: return rec.setsCount == stoi(query);
            case 4: {
                wstring weightQuery = query;
                for (wchar_t& ch : weightQuery) if (ch == L',') ch = L'.';
                return abs(rec.workingWeight - stod(weightQuery)) < 0.001;
            }
            case 5: {
                if (qLower == L"да" || qLower == L"1") return rec.isCompleted;
                if (qLower == L"нет" || qLower == L"0") return !rec.isCompleted;
                return false;
            }
        }
    } catch (...) {
        return false;
    }
    return false;
}

int deleteRecordsByNonKeyField(int fieldIndex, const wstring& query) {
    fstream file(filesystem::path(g_currentDbPath), ios::in | ios::out | ios::binary);
    if (!file.is_open()) return 0;

    FileHeader header = {};
    file.read(reinterpret_cast<char*>(&header), sizeof(FileHeader));
    if (!file || header.signature != FILE_SIGNATURE) return 0;

    file.seekg(0, ios::end);
    long totalSize = static_cast<long>(file.tellg());
    int deletedCount = 0;

    WorkoutRecord rec;
    for (long pos = sizeof(FileHeader); pos + (long)sizeof(WorkoutRecord) <= totalSize; pos += sizeof(WorkoutRecord)) {
        file.seekg(pos, ios::beg);
        file.read(reinterpret_cast<char*>(&rec), sizeof(WorkoutRecord));
        if (!rec.isDeleted && matchesNonKeyField(rec, fieldIndex, query)) {
            if (deleteByKeyInStream(file, header, rec.id)) {
                deletedCount++;
            }
        }
    }
    return deletedCount;
}

string wideToUtf8(const wstring& value) {
    if (value.empty()) return string();
    int size = WideCharToMultiByte(CP_UTF8, 0, value.c_str(), -1, nullptr, 0, nullptr, nullptr);
    if (size <= 0) return string();
    string result(static_cast<size_t>(size), '\0');
    int written = WideCharToMultiByte(CP_UTF8, 0, value.c_str(), -1,
        result.data(), size, nullptr, nullptr);
    if (written <= 0) return string();
    result.resize(static_cast<size_t>(written - 1));
    return result;
}

wstring utf8ToWide(const string& value) {
    if (value.empty()) return wstring();
    int size = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, value.data(),
        static_cast<int>(value.size()), nullptr, 0);
    if (size <= 0) return wstring();
    wstring result(static_cast<size_t>(size), L'\0');
    int written = MultiByteToWideChar(CP_UTF8, MB_ERR_INVALID_CHARS, value.data(),
        static_cast<int>(value.size()), result.data(), size);
    if (written <= 0) return wstring();
    result.resize(static_cast<size_t>(written));
    return result;
}

string csvEscape(const string& value) {
    if (value.find_first_of(";\"\r\n") == string::npos) return value;
    string result = "\"";
    for (char ch : value) {
        if (ch == '\"') result += "\"\"";
        else result += ch;
    }
    result += '\"';
    return result;
}

vector<string> parseCsvLine(const string& line) {
    vector<string> fields;
    string field;
    bool inQuotes = false;
    for (size_t i = 0; i < line.size(); ++i) {
        char ch = line[i];
        if (ch == '\"') {
            if (inQuotes && i + 1 < line.size() && line[i + 1] == '\"') {
                field += '\"';
                ++i;
            } else {
                inQuotes = !inQuotes;
            }
        } else if (ch == ';' && !inQuotes) {
            fields.push_back(field);
            field.clear();
        } else {
            field += ch;
        }
    }
    if (inQuotes) return vector<string>();
    fields.push_back(field);
    return fields;
}

bool exportDatabaseToCsv(const wstring& csvPath) {
    if (!g_isDbOpen || !isValidDatabaseFile(g_currentDbPath)) return false;
    if (filesystem::path(csvPath).lexically_normal() == filesystem::path(g_currentDbPath).lexically_normal()) return false;

    ifstream dbFile(filesystem::path(g_currentDbPath), ios::binary);
    ofstream csvFile(filesystem::path(csvPath), ios::binary | ios::trunc);
    if (!dbFile.is_open() || !csvFile.is_open()) return false;

    csvFile << "\xEF\xBB\xBF";
    csvFile << "ID;Клиент;Упражнение;Подходы;Вес (кг);Выполнено\r\n";
    dbFile.seekg(sizeof(FileHeader), ios::beg);
    WorkoutRecord rec = {};
    while (dbFile.read(reinterpret_cast<char*>(&rec), sizeof(WorkoutRecord))) {
        if (rec.isDeleted) continue;
        wstringstream weightStream;
        weightStream << fixed << setprecision(2) << rec.workingWeight;
        wstring weightStr = weightStream.str();
        for (wchar_t& ch : weightStr) if (ch == L'.') ch = L',';
        csvFile << rec.id << ";"
                << csvEscape(wideToUtf8(rec.clientName)) << ";"
                << csvEscape(wideToUtf8(rec.exerciseName)) << ";"
                << rec.setsCount << ";"
                << csvEscape(wideToUtf8(weightStr)) << ";"
                << wideToUtf8(rec.isCompleted ? L"Да" : L"Нет") << "\r\n";
        if (!csvFile) return false;
    }
    return dbFile.eof() && csvFile.good();
}

// Импортирует CSV, созданный этим приложением или имеющий такие же 6 столбцов.
// Уже существующие ID пропускаются; некорректные строки тоже пропускаются.
bool importDatabaseFromCsv(const wstring& csvPath, int& addedCount, int& skippedCount) {
    addedCount = 0;
    skippedCount = 0;
    if (!g_isDbOpen || !isValidDatabaseFile(g_currentDbPath)) return false;
    if (filesystem::path(csvPath).lexically_normal() == filesystem::path(g_currentDbPath).lexically_normal()) return false;

    ifstream input(filesystem::path(csvPath), ios::binary);
    if (!input.is_open()) return false;

    string line;
    bool firstLine = true;
    while (getline(input, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (firstLine) {
            firstLine = false;
            if (line.size() >= 3 && static_cast<unsigned char>(line[0]) == 0xEF &&
                static_cast<unsigned char>(line[1]) == 0xBB && static_cast<unsigned char>(line[2]) == 0xBF) {
                line.erase(0, 3);
            }
            // Заголовок CSV пропускается.
            if (line.rfind("ID;", 0) == 0) continue;
        }
        if (line.empty()) continue;
        vector<string> fields = parseCsvLine(line);
        if (fields.size() != 6) { ++skippedCount; continue; }
        try {
            wstring idText = utf8ToWide(fields[0]);
            wstring client = utf8ToWide(fields[1]);
            wstring exercise = utf8ToWide(fields[2]);
            wstring setsText = utf8ToWide(fields[3]);
            wstring weightText = utf8ToWide(fields[4]);
            wstring doneText = toLowerString(utf8ToWide(fields[5]));
            if (idText.empty() || client.empty() || exercise.empty() || setsText.empty() || weightText.empty()) {
                ++skippedCount; continue;
            }
            size_t posId = 0, posSets = 0, posWeight = 0;
            int id = stoi(idText, &posId);
            int sets = stoi(setsText, &posSets);
            for (wchar_t& ch : weightText) if (ch == L',') ch = L'.';
            double weight = stod(weightText, &posWeight);
            bool completed;
            if (doneText == L"да" || doneText == L"1") completed = true;
            else if (doneText == L"нет" || doneText == L"0") completed = false;
            else { ++skippedCount; continue; }
            if (posId != idText.size() || posSets != setsText.size() || posWeight != weightText.size() ||
                id <= 0 || sets < 1 || sets > 30 || !std::isfinite(weight) || weight < 0.0 || weight > 500.0 ||
                client.size() >= MAX_TEXT_LEN || exercise.size() >= MAX_TEXT_LEN) {
                ++skippedCount; continue;
            }
            WorkoutRecord rec = makeWorkoutRecord(id, client, exercise, sets, weight, completed);
            if (addRecordToDatabase(rec)) ++addedCount;
            else ++skippedCount;
        } catch (...) {
            ++skippedCount;
        }
    }
    return input.eof();
}

