// Стандартное диалоговое окно выбора файла ("Открыть" / "Сохранить")
bool selectFileDialog(HWND hwnd, wstring& outPath, bool isSave, const wchar_t* filter, const wchar_t* defExt) {
    wchar_t filePath[MAX_PATH] = {};
    OPENFILENAMEW ofn = {};
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = hwnd;
    ofn.lpstrFilter = filter;
    ofn.lpstrFile = filePath;
    ofn.nMaxFile = MAX_PATH;
    ofn.lpstrDefExt = defExt;
    ofn.Flags = OFN_NOCHANGEDIR | (isSave ? OFN_OVERWRITEPROMPT : OFN_FILEMUSTEXIST);

    bool ok = isSave ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn);
    if (ok) outPath = filePath;
    return ok;
}

// Добавляет одну строку в визуальную таблицу ListView
void addRowToListView(int rowIndex, const WorkoutRecord& rec) {
    wstring idStr = to_wstring(rec.id);
    LVITEMW item = {};
    item.mask = LVIF_TEXT;
    item.iItem = rowIndex;
    item.pszText = idStr.data();
    SendMessageW(g_hTable, LVM_INSERTITEMW, 0, reinterpret_cast<LPARAM>(&item));

    auto setCell = [&](int col, wstring text) {
        LVITEMW cell = {};
        cell.iSubItem = col;
        cell.pszText = text.data();
        SendMessageW(g_hTable, LVM_SETITEMTEXTW, rowIndex, reinterpret_cast<LPARAM>(&cell));
    };

    wstringstream weightStream;
    weightStream << fixed << setprecision(2) << rec.workingWeight;

    setCell(1, rec.clientName);
    setCell(2, rec.exerciseName);
    setCell(3, to_wstring(rec.setsCount));
    setCell(4, weightStream.str());
    setCell(5, rec.isCompleted ? L"Да" : L"Нет");
}

// Обновляет таблицу на экране из файла БД (если filterField == -1, выводит все записи)
int refreshTableFromFile(int filterField = -1, const wstring& query = L"") {
    SendMessageW(g_hTable, LVM_DELETEALLITEMS, 0, 0);
    if (!g_isDbOpen) {
        SetWindowTextW(g_hStatusLabel, L"  База данных не открыта. Нажмите «Создать БД» или «Открыть БД».");
        return 0;
    }

    ifstream file(filesystem::path(g_currentDbPath), ios::binary);
    if (!file.is_open()) return 0;

    file.seekg(sizeof(FileHeader), ios::beg);
    WorkoutRecord rec;
    int rowCount = 0;

    SendMessageW(g_hTable, WM_SETREDRAW, FALSE, 0);
    while (file.read(reinterpret_cast<char*>(&rec), sizeof(WorkoutRecord))) {
        if (!rec.isDeleted && (filterField == -1 || matchesNonKeyField(rec, filterField, query))) {
            addRowToListView(rowCount++, rec);
        }
    }
    SendMessageW(g_hTable, WM_SETREDRAW, TRUE, 0);

    if (filterField == -1) {
        wstring status = L"  Файл: " + g_currentDbPath + L"   |   Активных записей: " + to_wstring(rowCount);
        SetWindowTextW(g_hStatusLabel, status.c_str());
    }
    return rowCount;
}

