// Проверяет поля формы и собирает структуру WorkoutRecord
bool readRecordFromForm(HWND hwnd, WorkoutRecord& outRec) {
    wstring idStr     = getControlText(g_hEditId);
    wstring client    = getControlText(g_hEditClient);
    wstring exercise  = getControlText(g_hEditExercise);
    wstring setsStr   = getControlText(g_hEditSets);
    wstring weightStr = getControlText(g_hEditWeight);

    if (idStr.empty() || client.empty() || exercise.empty() || setsStr.empty() || weightStr.empty()) {
        MessageBoxW(hwnd, L"Заполните все поля записи!", WINDOW_TITLE, MB_OK | MB_ICONWARNING);
        return false;
    }

    try {
        size_t posId = 0, posSets = 0, posWeight = 0;
        int id = stoi(idStr, &posId);
        int sets = stoi(setsStr, &posSets);

        for (wchar_t& ch : weightStr) if (ch == L',') ch = L'.';
        double weight = stod(weightStr, &posWeight);

        if (posId != idStr.size() || id <= 0) throw invalid_argument("id");
        if (posSets != setsStr.size() || sets < 1 || sets > 30) throw invalid_argument("sets");
        if (posWeight != weightStr.size() || !std::isfinite(weight) || weight < 0.0 || weight > 500.0) throw invalid_argument("weight");

        bool done = (SendMessageW(g_hCheckDone, BM_GETCHECK, 0, 0) == BST_CHECKED);
        outRec = makeWorkoutRecord(id, client, exercise, sets, weight, done);
        return true;
    } catch (...) {
        MessageBoxW(hwnd, L"Проверьте числа: ID > 0, Подходы (1..30), Вес (0..500 кг)!", WINDOW_TITLE, MB_OK | MB_ICONWARNING);
        return false;
    }
}

