        }
    } else if (dbExists) {
        openDatabaseFile(g_currentDbPath); // Если файл повреждён, не перезаписываем его автоматически.
    }
    refreshTableFromFile();
}
void handleCommand(HWND hwnd, int cmdId) {
    const wchar_t* FILTER_DB  = L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0";
    const wchar_t* FILTER_BAK = L"Файлы Backup (*.bak)\0*.bak\0Все файлы (*.*)\0*.*\0";
    const wchar_t* FILTER_CSV = L"Таблицы CSV (*.csv)\0*.csv\0";
    wstring path;

    switch (cmdId) {
        case ID_BTN_CREATE_DB:
            if (selectFileDialog(hwnd, path, true, FILTER_DB, L"db") && createDatabaseFile(path)) {
                openDatabaseFile(path);
                clearInputForm();
                refreshTableFromFile();
            }
            break;

        case ID_BTN_OPEN_DB:
            if (selectFileDialog(hwnd, path, false, FILTER_DB, L"db")) {
                if (openDatabaseFile(path)) { clearInputForm(); refreshTableFromFile(); }
                else MessageBoxW(hwnd, L"Неверный формат файла БД!", WINDOW_TITLE, MB_OK | MB_ICONERROR);
            }
            break;

        case ID_BTN_SAVE_AS_DB:
            if (g_isDbOpen && selectFileDialog(hwnd, path, true, FILTER_DB, L"db")) {
                error_code ec;
                if (filesystem::copy_file(g_currentDbPath, path, filesystem::copy_options::overwrite_existing, ec)) {
                    openDatabaseFile(path);
                    refreshTableFromFile();
                }
            }
            break;

        case ID_BTN_BACKUP_DB:
            if (g_isDbOpen && selectFileDialog(hwnd, path, true, FILTER_BAK, L"bak")) {
                error_code ec;
                if (filesystem::copy_file(g_currentDbPath, path, filesystem::copy_options::overwrite_existing, ec))
                    MessageBoxW(hwnd, L"Backup-копия успешно создана.", WINDOW_TITLE, MB_OK | MB_ICONINFORMATION);
            }
            break;

        case ID_BTN_RESTORE_DB:
            if (selectFileDialog(hwnd, path, false, FILTER_BAK, L"bak")) {
                if (!isValidDatabaseFile(path)) {
                    MessageBoxW(hwnd, L"Выбран некорректный файл backup!", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                    break;
                }
                error_code ec;
                if (g_isDbOpen) {
                    // Восстанавливаем в текущий файл, не меняя путь до копирования.
                    if (filesystem::path(path).lexically_normal() == filesystem::path(g_currentDbPath).lexically_normal()) {
                        MessageBoxW(hwnd, L"Выбранный backup уже является текущей базой.", WINDOW_TITLE, MB_OK | MB_ICONINFORMATION);
                        break;
                    }
                    filesystem::copy_file(path, g_currentDbPath, filesystem::copy_options::overwrite_existing, ec);
                    if (ec || !openDatabaseFile(g_currentDbPath)) {
                        MessageBoxW(hwnd, L"Не удалось восстановить базу из backup.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                        break;
                    }
                } else {
                    // Если текущей базы нет, открываем сам проверенный backup.
                    if (!openDatabaseFile(path)) {
                        MessageBoxW(hwnd, L"Не удалось открыть backup.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                        break;
                    }
                }
                clearInputForm();
                refreshTableFromFile();
                MessageBoxW(hwnd, L"База данных восстановлена из backup.", WINDOW_TITLE, MB_OK | MB_ICONINFORMATION);
            }
            break;

        case ID_BTN_CLEAR_DB:
            if (g_isDbOpen && MessageBoxW(hwnd, L"Очистить все записи в БД?", WINDOW_TITLE, MB_YESNO | MB_ICONQUESTION) == IDYES) {
                if (!createDatabaseFile(g_currentDbPath) || !openDatabaseFile(g_currentDbPath)) {
                    MessageBoxW(hwnd, L"Не удалось очистить базу данных.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                    break;
                }
                clearInputForm();
                refreshTableFromFile();
            }
            break;

        case ID_BTN_DROP_DB:
            if (g_isDbOpen && MessageBoxW(hwnd, L"Удалить файл БД с диска?", WINDOW_TITLE, MB_YESNO | MB_ICONQUESTION) == IDYES) {
                error_code ec;
                bool removed = filesystem::remove(g_currentDbPath, ec);
                if (ec || !removed) {
                    MessageBoxW(hwnd, L"Не удалось удалить файл базы данных.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                    break;
                }
                g_isDbOpen = false;
                clearInputForm();
                refreshTableFromFile();
            }
            break;

        case ID_BTN_EXPORT_CSV:
            if (g_isDbOpen && selectFileDialog(hwnd, path, true, FILTER_CSV, L"csv")) {
                if (exportDatabaseToCsv(path))
                    MessageBoxW(hwnd, L"Экспорт в CSV выполнен!", WINDOW_TITLE, MB_OK | MB_ICONINFORMATION);
                else
                    MessageBoxW(hwnd, L"Не удалось экспортировать CSV.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
            }
            break;

        case ID_BTN_IMPORT_CSV:
            if (g_isDbOpen && selectFileDialog(hwnd, path, false, FILTER_CSV, L"csv")) {
                int added = 0, skipped = 0;
                if (importDatabaseFromCsv(path, added, skipped)) {
                    refreshTableFromFile();
                    wstring message = L"Импорт завершён. Добавлено записей: " + to_wstring(added) +
                        L". Пропущено строк: " + to_wstring(skipped) + L".";
                    MessageBoxW(hwnd, message.c_str(), WINDOW_TITLE, MB_OK | MB_ICONINFORMATION);
                } else {
                    MessageBoxW(hwnd, L"Не удалось прочитать CSV. Проверьте кодировку UTF-8 и формат шести столбцов.", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                }
            }
            break;

        case ID_BTN_ADD_RECORD: {
            WorkoutRecord rec;
            if (g_isDbOpen && readRecordFromForm(hwnd, rec)) {
                if (addRecordToDatabase(rec)) refreshTableFromFile();
                else MessageBoxW(hwnd, L"Запись с таким ID уже существует!", WINDOW_TITLE, MB_OK | MB_ICONERROR);
            }
            break;
        }

        case ID_BTN_EDIT_RECORD: {
            if (g_selectedKeyId == -1) {
                MessageBoxW(hwnd, L"Сначала выберите запись в таблице!", WINDOW_TITLE, MB_OK | MB_ICONWARNING);
                break;
            }
            WorkoutRecord rec;
            if (g_isDbOpen && readRecordFromForm(hwnd, rec)) {
                if (editRecordInDatabase(g_selectedKeyId, rec)) {
                    g_selectedKeyId = rec.id;
                    refreshTableFromFile();
                } else {
                    MessageBoxW(hwnd, L"Новый ключ ID уже занят!", WINDOW_TITLE, MB_OK | MB_ICONERROR);
                }
            }
            break;
        }

        case ID_BTN_CLEAR_FORM:
            clearInputForm();
            break;

        case ID_BTN_SEARCH:
        case ID_BTN_DELETE: {
            if (!g_isDbOpen) break;
            int field = static_cast<int>(SendMessageW(g_hComboField, CB_GETCURSEL, 0, 0));
            wstring query = getControlText(g_hEditQuery);
            if (query.empty()) {
                MessageBoxW(hwnd, L"Введите значение для поиска или удаления!", WINDOW_TITLE, MB_OK | MB_ICONWARNING);
                break;
            }

            if (cmdId == ID_BTN_SEARCH) {
                int count = 0;
                if (field == 0) {
                    SendMessageW(g_hTable, LVM_DELETEALLITEMS, 0, 0);
                    WorkoutRecord found;
                    try {
                        size_t parsed = 0;
                        int searchId = stoi(query, &parsed);
                        if (parsed == query.size() && searchId > 0 && searchRecordByKey(searchId, found)) {
                            addRowToListView(0, found); count = 1;
                        }
                    } catch (...) {}
                } else {
                    count = refreshTableFromFile(field, query);
                }
                wstring status = L"  Найдено записей: " + to_wstring(count);
                SetWindowTextW(g_hStatusLabel, status.c_str());
            } else {
                if (MessageBoxW(hwnd, L"Удалить подходящие записи?", WINDOW_TITLE, MB_YESNO | MB_ICONQUESTION) != IDYES) break;
                int deleted = 0;
                try {
                    if (field == 0) {
                        size_t parsed = 0;
                        int deleteId = stoi(query, &parsed);
                        if (parsed == query.size() && deleteId > 0) deleted = deleteRecordByKey(deleteId) ? 1 : 0;
                    } else {
                        deleted = deleteRecordsByNonKeyField(field, query);
                    }
                } catch (...) {}
                clearInputForm();
                refreshTableFromFile();
                wstring status = L"  Удалено записей: " + to_wstring(deleted);
                SetWindowTextW(g_hStatusLabel, status.c_str());
            }
            break;
        }

        case ID_BTN_SHOW_ALL:
            refreshTableFromFile();
            break;
    }
}


// Перестраивает расположение основных элементов при изменении размера окна.
// Левая панель остаётся фиксированной, таблица занимает всё оставшееся место.
void layoutMainControls(HWND hwnd, int clientWidth, int clientHeight) {
    if (clientWidth <= 0 || clientHeight <= 0) return;

    const int margin = 20;
    const int toolbarGap = 6;
    const int toolbarCount = 9;
    const int toolbarY = 46;
    const int toolbarH = 36;
    int toolbarW = (clientWidth - 2 * margin - (toolbarCount - 1) * toolbarGap) / toolbarCount;

    const int toolbarIds[toolbarCount] = {
        ID_BTN_CREATE_DB, ID_BTN_OPEN_DB, ID_BTN_SAVE_AS_DB,
        ID_BTN_BACKUP_DB, ID_BTN_RESTORE_DB, ID_BTN_CLEAR_DB,
        ID_BTN_DROP_DB, ID_BTN_EXPORT_CSV, ID_BTN_IMPORT_CSV
    };
    for (int i = 0; i < toolbarCount; ++i) {
        HWND control = GetDlgItem(hwnd, toolbarIds[i]);
        if (control) {
            int x = margin + i * (toolbarW + toolbarGap);
            int w = (i == toolbarCount - 1) ? clientWidth - margin - x : toolbarW;
            MoveWindow(control, x, toolbarY, w, toolbarH, TRUE);
        }
    }

    // Левая колонка сохраняет ширину; таблица растягивается по ширине и высоте.
    const int tableX = 460;
    const int tableY = 138;
    const int rightMargin = 20;
    const int bottomMargin = 54;
    int tableW = max(400, clientWidth - tableX - rightMargin);
    int tableH = max(300, clientHeight - tableY - bottomMargin);

    if (g_hTable) MoveWindow(g_hTable, tableX, tableY, tableW, tableH, TRUE);
    HWND showAll = GetDlgItem(hwnd, ID_BTN_SHOW_ALL);
    if (showAll) MoveWindow(showAll, clientWidth - rightMargin - 160, 102, 160, 28, TRUE);
    if (g_hStatusLabel) MoveWindow(g_hStatusLabel, 14, clientHeight - 34, clientWidth - 28, 26, TRUE);

    // Распределяем ширину столбцов пропорционально ширине таблицы.
    if (g_hTable) {
        int available = max(400, tableW - 8);
        const double ratios[] = { 0.09, 0.22, 0.25, 0.13, 0.13, 0.18 };
        int used = 0;
        for (int i = 0; i < 6; ++i) {
            int colW = (i == 5) ? available - used : static_cast<int>(available * ratios[i]);
            SendMessageW(g_hTable, LVM_SETCOLUMNWIDTH, i, colW);
            used += colW;
        }
    }
}

LRESULT CALLBACK MainWindowProc(HWND hwnd, UINT msg, WPARAM wParam, LPARAM lParam) {
    switch (msg) {
        case WM_CREATE:
            initWindowControls(hwnd);
            return 0;

        case WM_GETMINMAXINFO: {
            auto* limits = reinterpret_cast<MINMAXINFO*>(lParam);
            limits->ptMinTrackSize.x = 1120;
            limits->ptMinTrackSize.y = 720;
            return 0;
        }

        case WM_SIZE: {
            layoutMainControls(hwnd, LOWORD(lParam), HIWORD(lParam));
            InvalidateRect(hwnd, nullptr, TRUE);
            return 0;
        }

        case WM_PAINT: {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hwnd, &ps);
            auto drawCard = [&](int x, int y, int w, int h, const wchar_t* title) {
                HPEN pen = CreatePen(PS_SOLID, 1, COLOR_BORDER);
                HGDIOBJ oldPen = SelectObject(hdc, pen);
                HGDIOBJ oldBrush = SelectObject(hdc, g_hBrushCardBg);
                RoundRect(hdc, x, y, x + w, y + h, 12, 12);
                SelectObject(hdc, oldBrush);
                SelectObject(hdc, oldPen);
                DeleteObject(pen);

                HGDIOBJ oldFont = SelectObject(hdc, g_hFontBold);
                SetBkMode(hdc, TRANSPARENT);
                SetTextColor(hdc, COLOR_TEXT_DARK);
                RECT rc = { x + 16, y + 8, x + w - 16, y + 32 };
                DrawTextW(hdc, title, -1, &rc, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
                SelectObject(hdc, oldFont);
            };
            RECT clientRect = {};
            GetClientRect(hwnd, &clientRect);
            int clientWidth = clientRect.right - clientRect.left;
            int clientHeight = clientRect.bottom - clientRect.top;
            drawCard(14, 10, clientWidth - 28, 78, L"База данных");
            drawCard(14, 98, 430, 292, L"Запись");
            drawCard(14, 400, 430, max(232, clientHeight - 454), L"Поиск и удаление");
            drawCard(450, 98, clientWidth - 464, clientHeight - 130, L"Журнал тренировок");
            EndPaint(hwnd, &ps);
            return 0;
        }

        case WM_DRAWITEM: {
            auto* dis = reinterpret_cast<LPDRAWITEMSTRUCT>(lParam);
            bool pressed = (dis->itemState & ODS_SELECTED) != 0;
            COLORREF bg = pressed ? RGB(222, 229, 238) : COLOR_BTN_GRAY;
            COLORREF txt = COLOR_TEXT_DARK;
            COLORREF brd = RGB(205, 215, 228);
            if (dis->CtlID == ID_BTN_ADD_RECORD || dis->CtlID == ID_BTN_SEARCH) {
                bg = pressed ? RGB(37, 99, 235) : COLOR_BTN_BLUE; txt = RGB(255, 255, 255); brd = bg;
            } else if (dis->CtlID == ID_BTN_DELETE || dis->CtlID == ID_BTN_DROP_DB) {
                bg = pressed ? RGB(220, 38, 38) : COLOR_BTN_RED; txt = RGB(255, 255, 255); brd = bg;
            }
            FillRect(dis->hDC, &dis->rcItem, g_hBrushCardBg);
            HBRUSH b = CreateSolidBrush(bg);
            HPEN p = CreatePen(PS_SOLID, 1, brd);
            SelectObject(dis->hDC, b); SelectObject(dis->hDC, p);
            RoundRect(dis->hDC, dis->rcItem.left, dis->rcItem.top, dis->rcItem.right, dis->rcItem.bottom, 8, 8);
            DeleteObject(b); DeleteObject(p);
            wstring btnText = getControlText(dis->hwndItem);
            SetBkMode(dis->hDC, TRANSPARENT);
            SetTextColor(dis->hDC, txt);
            SelectObject(dis->hDC, g_hFontRegular);
            DrawTextW(dis->hDC, btnText.c_str(), -1, &dis->rcItem, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
            return TRUE;
        }

        case WM_CTLCOLORSTATIC:
        case WM_CTLCOLORBTN: {
            HDC hdc = reinterpret_cast<HDC>(wParam);
            SetTextColor(hdc, COLOR_TEXT_DARK);
            bool isStatus = (reinterpret_cast<HWND>(lParam) == g_hStatusLabel);
            SetBkColor(hdc, isStatus ? COLOR_WINDOW_BG : COLOR_CARD_BG);
            return reinterpret_cast<LRESULT>(isStatus ? g_hBrushWindowBg : g_hBrushCardBg);
        }

        case WM_CTLCOLOREDIT: {
            HDC hdc = reinterpret_cast<HDC>(wParam);
            SetTextColor(hdc, COLOR_TEXT_DARK);
            SetBkColor(hdc, COLOR_INPUT_BG);
            return reinterpret_cast<LRESULT>(g_hBrushInputBg);
        }

        case WM_NOTIFY: {
            auto* nm = reinterpret_cast<LPNMHDR>(lParam);
            if (nm->idFrom != ID_LISTVIEW_TABLE) break;
            if (nm->code == NM_CUSTOMDRAW) {
                auto* cd = reinterpret_cast<LPNMLVCUSTOMDRAW>(lParam);
                if (cd->nmcd.dwDrawStage == CDDS_PREPAINT) return CDRF_NOTIFYITEMDRAW;
                if (cd->nmcd.dwDrawStage == CDDS_ITEMPREPAINT) {
                    cd->clrTextBk = (cd->nmcd.dwItemSpec % 2 == 0) ? RGB(255, 255, 255) : RGB(244, 248, 254);
                    cd->clrText = COLOR_TEXT_DARK;
                    return CDRF_NEWFONT;
                }
            }
            if (nm->code == LVN_ITEMCHANGED) {
                auto* info = reinterpret_cast<LPNMLISTVIEW>(lParam);
                if ((info->uChanged & LVIF_STATE) && (info->uNewState & LVIS_SELECTED)) {
                    wchar_t idBuf[32] = {};
                    LVITEMW item = {};
                    item.pszText = idBuf;
                    item.cchTextMax = 32;
                    SendMessageW(g_hTable, LVM_GETITEMTEXTW, info->iItem, reinterpret_cast<LPARAM>(&item));
                    WorkoutRecord rec;
                    if (searchRecordByKey(_wtoi(idBuf), rec)) {
                        g_selectedKeyId = rec.id;
                        SetWindowTextW(g_hEditId, to_wstring(rec.id).c_str());
                        SetWindowTextW(g_hEditClient, rec.clientName);
                        SetWindowTextW(g_hEditExercise, rec.exerciseName);
                        SetWindowTextW(g_hEditSets, to_wstring(rec.setsCount).c_str());
                        wstringstream ws; ws << rec.workingWeight;
                        SetWindowTextW(g_hEditWeight, ws.str().c_str());
                        SendMessageW(g_hCheckDone, BM_SETCHECK, rec.isCompleted ? BST_CHECKED : BST_UNCHECKED, 0);
                    }
                }
            }
            break;
        }

        case WM_COMMAND:
            handleCommand(hwnd, LOWORD(wParam));
            return 0;

        case WM_DESTROY:
            DeleteObject(g_hFontRegular); DeleteObject(g_hFontBold);
            DeleteObject(g_hBrushWindowBg); DeleteObject(g_hBrushCardBg); DeleteObject(g_hBrushInputBg);
            PostQuitMessage(0);
            return 0;
    }
    return DefWindowProcW(hwnd, msg, wParam, lParam);
}
int WINAPI WinMain(HINSTANCE hInst, HINSTANCE, LPSTR, int nCmdShow) {
    INITCOMMONCONTROLSEX icc = { sizeof(icc), ICC_LISTVIEW_CLASSES };
    InitCommonControlsEx(&icc);
    g_hBrushWindowBg = CreateSolidBrush(COLOR_WINDOW_BG);
    g_hBrushCardBg   = CreateSolidBrush(COLOR_CARD_BG);
    g_hBrushInputBg  = CreateSolidBrush(COLOR_INPUT_BG);
    WNDCLASSEXW wc = {};
    wc.cbSize = sizeof(wc);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = MainWindowProc;
    wc.hInstance = hInst;
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hIcon = LoadIcon(nullptr, IDI_APPLICATION);
    wc.hbrBackground = g_hBrushWindowBg;
    wc.lpszClassName = L"WorkoutCppDbWindow";
    RegisterClassExW(&wc);
    DWORD style = WS_OVERLAPPEDWINDOW | WS_CLIPCHILDREN;
    RECT rc = { 0, 0, 1500, 900 };
    AdjustWindowRect(&rc, style, FALSE);
    HWND hwnd = CreateWindowExW(0, wc.lpszClassName, WINDOW_TITLE, style,
        CW_USEDEFAULT, CW_USEDEFAULT, rc.right - rc.left, rc.bottom - rc.top, nullptr, nullptr, hInst, nullptr);
    ShowWindow(hwnd, nCmdShow);
    UpdateWindow(hwnd);
    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }
    return static_cast<int>(msg.wParam);
}

input.file_text:
/*
 * Лабораторная работа №2. Файловая база данных с GUI.
 * Предметная область: журнал тренировок.
 *
 * Файл БД - это хеш-таблица с цепочками прямо на диске:
 *     [ Header ][ Record ][ Record ][ Record ] ...
 *   Header: сигнатура, число записей, начало списка свободных слотов, 1009 корзин.
 *   Корзина хранит смещение первой записи цепочки, запись хранит смещение следующей.
 * В памяти база НЕ хранится: каждая операция читает и пишет только нужные байты файла.
 *
 * Сложность:  добавление / удаление / поиск по ключу - O(1) в среднем,
 *             поиск и удаление по неключевому полю   - O(N).
 *
 * Сборка:
 *   MSVC : cl /EHsc /std:c++17 /utf-8 workout_db_final.cpp
 *   MinGW: g++ -std=c++17 workout_db_final.cpp -o workout_db.exe -mwindows -lcomctl32 -lcomdlg32 -lgdi32
 */

#define _CRT_SECURE_NO_WARNINGS
#define NOMINMAX

#include <windows.h>
#include <commctrl.h>
#include <commdlg.h>
#include <chrono>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <cwchar>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <string>

#ifdef _MSC_VER
#pragma comment(lib, "comctl32.lib")
#pragma comment(lib, "comdlg32.lib")
#pragma comment(linker, "/SUBSYSTEM:WINDOWS")
#endif

using namespace std;


// ============================================================================
// ЧАСТЬ 1. ФАЙЛОВАЯ БАЗА ДАННЫХ
// ============================================================================

const int HASH_SIZE = 1009;       // число корзин (простое число)
const int SIGNATURE = 0x57444231; // "WDB1" - метка нашего файла
const int TEXT_LEN  = 32;         // длина текстовых полей (в символах)

struct Header {                   // лежит в начале файла
    int  signature;
    int  count;                   // сколько живых записей
    long freeHead;                // первый свободный слот (-1, если нет)
    long buckets[HASH_SIZE];      // смещения первых записей цепочек (-1, если пусто)
};

struct Record {                   // одна запись таблицы
    int     id;                   // КЛЮЧ
    wchar_t client[TEXT_LEN];     // клиент
    wchar_t exercise[TEXT_LEN];   // упражнение
    int     sets;                 // подходы
    double  weight;               // рабочий вес, кг
    bool    done;                 // выполнено в журнале
    bool    deleted;              // служебное: слот свободен
    long    next;                 // служебное: следующая запись цепочки / свободного списка
};

const long HEADER_SIZE = sizeof(Header);
const long RECORD_SIZE = sizeof(Record);
const long POS_COUNT   = offsetof(Header, count);
const long POS_FREE    = offsetof(Header, freeHead);
const long POS_NEXT    = offsetof(Record, next);   // смещение внутри записи

wstring g_path = L"trainings.db"; // текущий файл БД
bool    g_open = false;           // открыта ли БД


// ---------- Чтение и запись по смещению ----------

template <class T> T readAt(fstream& f, long pos) {
    T value{};
    f.clear();
    f.seekg(pos, ios::beg);
    f.read(reinterpret_cast<char*>(&value), sizeof(T));
    return value;
}

template <class T> void writeAt(fstream& f, long pos, const T& value) {
    f.clear();
    f.seekp(pos, ios::beg);
    f.write(reinterpret_cast<const char*>(&value), sizeof(T));
}

long fileSize(fstream& f) {
    f.clear();
    f.seekg(0, ios::end);
    return static_cast<long>(static_cast<streamoff>(f.tellg()));
}

fstream openFile(const wstring& path, bool forWrite) {
    ios::openmode mode = ios::in | ios::binary;
    if (forWrite) mode |= ios::out;
    return fstream(filesystem::path(path), mode);
}

long bucketPos(int id) {   // где в файле лежит корзина этого ключа
    return (long)offsetof(Header, buckets) + (id % HASH_SIZE) * (long)sizeof(long);
}

Record makeRecord(int id, const wstring& client, const wstring& exercise, int sets, double weight, bool done) {
    Record r = {};
    r.id = id;
    wcsncpy(r.client, client.c_str(), TEXT_LEN - 1);
    wcsncpy(r.exercise, exercise.c_str(), TEXT_LEN - 1);
    r.sets = sets;
    r.weight = weight;
    r.done = done;
    r.next = -1;
    return r;
}


// ---------- Файл БД: создание, проверка, открытие ----------

bool createDb(const wstring& path) {          // создает пустую БД (или затирает старую)
    ofstream f(filesystem::path(path), ios::binary | ios::trunc);
    Header h;
    h.signature = SIGNATURE;
    h.count = 0;
    h.freeHead = -1;
    for (long& b : h.buckets) b = -1;
    f.write(reinterpret_cast<const char*>(&h), sizeof(h));
    return f.good();
}

bool isDbFile(const wstring& path) {          // наш ли это файл
    fstream f = openFile(path, false);
    if (!f.is_open()) return false;
    Header h = readAt<Header>(f, 0);
    long size = fileSize(f);
    return h.signature == SIGNATURE && size >= HEADER_SIZE && (size - HEADER_SIZE) % RECORD_SIZE == 0;
}

bool openDb(const wstring& path) {
    if (!isDbFile(path)) return false;
    g_path = path;
    g_open = true;
    return true;
}


// ---------- Поиск по ключу ----------

long findOffset(fstream& f, int id, Record* out = nullptr) {   // смещение записи или -1
    long pos = readAt<long>(f, bucketPos(id));                 // начало цепочки
    while (pos != -1) {
        Record r = readAt<Record>(f, pos);
        if (r.id == id) {
            if (out) *out = r;
            return pos;
        }
        pos = r.next;                                          // идем по цепочке
    }
    return -1;
}

bool dbSearch(int id, Record& out) {
    fstream f = openFile(g_path, false);
    return f.is_open() && findOffset(f, id, &out) != -1;
}


// ---------- Добавление ----------

bool addToFile(fstream& f, Record rec) {
    if (findOffset(f, rec.id) != -1) return false;             // ключ должен быть уникальным

    long bucket = bucketPos(rec.id);
    rec.deleted = false;
    rec.next = readAt<long>(f, bucket);                        // новая запись встает в начало цепочки

    long pos = readAt<long>(f, POS_FREE);
    if (pos != -1) {                                           // есть свободный слот - используем его
        writeAt(f, POS_FREE, readAt<Record>(f, pos).next);
    } else {                                                   // иначе пишем в конец файла
        pos = fileSize(f);
    }

    writeAt(f, pos, rec);
    writeAt(f, bucket, pos);
    writeAt(f, POS_COUNT, readAt<int>(f, POS_COUNT) + 1);
    return true;
}

bool dbAdd(const Record& rec) {
    fstream f = openFile(g_path, true);
    return f.is_open() && addToFile(f, rec);
}


// ---------- Удаление ----------

bool deleteFromFile(fstream& f, int id) {
    long bucket = bucketPos(id);
    long prev = -1;
    long pos = readAt<long>(f, bucket);

    while (pos != -1) {
        Record r = readAt<Record>(f, pos);
        if (r.id == id) {
            if (prev == -1) writeAt(f, bucket, r.next);        // была первой в цепочке
            else            writeAt(f, prev + POS_NEXT, r.next); // иначе "перепрыгиваем" через нее

            r.deleted = true;                                  // слот уходит в список свободных
            r.next = readAt<long>(f, POS_FREE);
            writeAt(f, pos, r);
            writeAt(f, POS_FREE, pos);
            writeAt(f, POS_COUNT, readAt<int>(f, POS_COUNT) - 1);
            return true;
        }
        prev = pos;
        pos = r.next;
    }
    return false;
}

bool dbDeleteKey(int id) {
    fstream f = openFile(g_path, true);
    return f.is_open() && deleteFromFile(f, id);
}


// ---------- Разбор текста и сравнение по неключевым полям ----------

bool parseInt(const wstring& s, int& out) {
    wchar_t* end = nullptr;
    long v = wcstol(s.c_str(), &end, 10);
    if (s.empty() || *end != L'\0' || v < 0 || v > 1000000000) return false;
    out = (int)v;
    return true;
}

bool parseDouble(wstring s, double& out) {
    for (wchar_t& c : s) if (c == L',') c = L'.';              // 12,5 -> 12.5
    wchar_t* end = nullptr;
    out = wcstod(s.c_str(), &end);
    return !s.empty() && *end == L'\0';
}

wstring toLower(wstring s) {                                   // работает и для русских букв
    CharLowerBuffW(&s[0], (DWORD)s.size());
    return s;
}

bool parseBool(const wstring& s, bool& out) {
    wstring t = toLower(s);
    if (t == L"да" || t == L"1")  { out = true;  return true; }
    if (t == L"нет" || t == L"0") { out = false; return true; }
    return false;
}

wstring toText(double v, int digits = -1) {                    // число -> текст
    wstringstream s;
    if (digits >= 0) s << fixed << setprecision(digits);
    s << v;
    return s.str();
}

// Номера полей: 1 - клиент, 2 - упражнение, 3 - подходы, 4 - вес, 5 - выполнено
bool matches(const Record& r, int field, const wstring& q) {
    int i = 0;
    double d = 0;
    bool b = false;
    switch (field) {
        case 1: return toLower(r.client).find(toLower(q)) != wstring::npos;
        case 2: return toLower(r.exercise).find(toLower(q)) != wstring::npos;
        case 3: return parseInt(q, i) && r.sets == i;
        case 4: return parseDouble(q, d) && fabs(r.weight - d) < 0.001;
        case 5: return parseBool(q, b) && r.done == b;
    }
    return false;
}

int dbDeleteByField(int field, const wstring& q) {             // удаляет ВСЕ совпавшие записи
    fstream f = openFile(g_path, true);
    long size = fileSize(f);
    int deleted = 0;
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(f, pos);
        if (!r.deleted && matches(r, field, q) && deleteFromFile(f, r.id)) deleted++;
    }
    return deleted;
}


// ---------- Редактирование ----------

bool dbEdit(int oldId, Record rec) {
    fstream f = openFile(g_path, true);
    if (!f.is_open()) return false;

    Record old;
    long pos = findOffset(f, oldId, &old);
    if (pos == -1) return false;

    if (rec.id == oldId) {                                     // ключ не менялся - пишем поверх
        rec.deleted = false;
        rec.next = old.next;
        writeAt(f, pos, rec);
        return true;
    }
    if (findOffset(f, rec.id) != -1) return false;             // новый ключ занят
    deleteFromFile(f, oldId);                                  // ключ изменился - удалить + добавить
    return addToFile(f, rec);
}


// ---------- Экспорт в CSV (открывается в Excel) ----------

string toUtf8(const wstring& w) {
    int n = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), -1, nullptr, 0, nullptr, nullptr);
    string s(n, '\0');
    WideCharToMultiByte(CP_UTF8, 0, w.c_str(), -1, &s[0], n, nullptr, nullptr);
    s.resize(n - 1);
    return s;
}

bool dbExportCsv(const wstring& csvPath) {
    fstream db = openFile(g_path, false);
    ofstream csv(filesystem::path(csvPath), ios::binary | ios::trunc);
    if (!db.is_open() || !csv.is_open()) return false;

    auto quote = [](const wstring& s) {                        // текст в кавычках, " удваивается
        wstring r = L"\"";
        for (wchar_t c : s) {
            if (c == L'"') r += L'"';
            r += c;
        }
        return r + L"\"";
    };

    csv << "\xEF\xBB\xBF";                                     // метка UTF-8, чтобы Excel понял кодировку
    csv << toUtf8(L"ID;Клиент;Упражнение;Подходы;Вес (кг);Выполнено\r\n");

    long size = fileSize(db);
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(db, pos);
        if (r.deleted) continue;
        wstring weight = toText(r.weight, 2);
        for (wchar_t& c : weight) if (c == L'.') c = L',';     // русский Excel ждет запятую
        wstring line = to_wstring(r.id) + L";" + quote(r.client) + L";" + quote(r.exercise) + L";" +
                       to_wstring(r.sets) + L";" + weight + L";" + (r.done ? L"Да" : L"Нет") + L"\r\n";
        csv << toUtf8(line);
    }
    return csv.good();
}


// ============================================================================
// ЧАСТЬ 2. ГРАФИЧЕСКИЙ ИНТЕРФЕЙС
// ============================================================================

enum ControlId {
    ID_BTN_CREATE = 101, ID_BTN_OPEN, ID_BTN_SAVE_AS, ID_BTN_BACKUP,
    ID_BTN_RESTORE, ID_BTN_CLEAR_DB, ID_BTN_DROP_DB, ID_BTN_EXPORT,

    ID_EDIT_ID = 201, ID_EDIT_CLIENT, ID_EDIT_EXERCISE, ID_EDIT_SETS, ID_EDIT_WEIGHT,
    ID_CHK_DONE, ID_BTN_ADD, ID_BTN_EDIT, ID_BTN_CLEAR_FORM,

    ID_COMBO = 301, ID_EDIT_QUERY, ID_BTN_SEARCH, ID_BTN_DELETE,

    ID_BTN_SHOW_ALL = 401, ID_BTN_BENCH, ID_TABLE
};

const COLORREF CLR_WINDOW = RGB(240, 244, 249);
const COLORREF CLR_CARD   = RGB(255, 255, 255);
const COLORREF CLR_BORDER = RGB(218, 226, 236);
const COLORREF CLR_INPUT  = RGB(248, 250, 252);
const COLORREF CLR_TEXT   = RGB(30, 41, 59);

const wchar_t* TITLE = L"Журнал тренировок — файловая БД";

// Фильтры диалогов выбора файла
const wchar_t FILTER_DB[]  = L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0";
const wchar_t FILTER_BAK[] = L"Backup (*.bak)\0*.bak\0Все файлы (*.*)\0*.*\0";
const wchar_t FILTER_CSV[] = L"CSV для Excel (*.csv)\0*.csv\0";

HWND g_table, g_status, g_combo;
HWND g_edId, g_edClient, g_edExercise, g_edSets, g_edWeight, g_chkDone, g_edQuery;
HFONT g_fontRegular, g_fontBold;
HBRUSH g_brWindow, g_brCard, g_brInput;

int g_selectedId = -1;   // ключ записи, выбранной в таблице


// ---------- Мелкие помощники ----------

void msg(HWND hwnd, const wstring& text, UINT icon = MB_ICONINFORMATION) {
    MessageBoxW(hwnd, text.c_str(), TITLE, MB_OK | icon);
}

bool ask(HWND hwnd, const wstring& text) {
    return MessageBoxW(hwnd, text.c_str(), TITLE, MB_YESNO | MB_ICONQUESTION) == IDYES;
}

bool needDb(HWND hwnd) {
    if (!g_open) msg(hwnd, L"База данных не открыта! Создайте или откройте файл БД.", MB_ICONERROR);
    return g_open;
}

void setStatus(const wstring& text) { SetWindowTextW(g_status, text.c_str()); }

wstring getText(HWND h) {
    wchar_t buf[256] = {};
    GetWindowTextW(h, buf, 255);
    return buf;
}

bool pickFile(HWND hwnd, wstring& path, bool save, const wchar_t* filter, const wchar_t* ext) {
    wchar_t buf[MAX_PATH] = {};
    OPENFILENAMEW ofn = {};
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = hwnd;
    ofn.lpstrFilter = filter;
    ofn.lpstrFile = buf;
    ofn.nMaxFile = MAX_PATH;
    ofn.lpstrDefExt = ext;
    ofn.Flags = OFN_NOCHANGEDIR | (save ? OFN_OVERWRITEPROMPT : OFN_FILEMUSTEXIST);
    if (!(save ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn))) return false;
    path = buf;
    return true;
}


// ---------- Таблица ----------

void setCell(int row, int col, const wstring& text) {
    LVITEMW item = {};
    item.iSubItem = col;
    item.pszText = const_cast<LPWSTR>(text.c_str());
    SendMessageW(g_table, LVM_SETITEMTEXTW, row, reinterpret_cast<LPARAM>(&item));
}

void addRow(int row, const Record& r) {
    wstring id = to_wstring(r.id);
    LVITEMW item = {};
    item.mask = LVIF_TEXT;
    item.iItem = row;
    item.pszText = const_cast<LPWSTR>(id.c_str());
    SendMessageW(g_table, LVM_INSERTITEMW, 0, reinterpret_cast<LPARAM>(&item));

    setCell(row, 1, r.client);
    setCell(row, 2, r.exercise);
    setCell(row, 3, to_wstring(r.sets));
    setCell(row, 4, toText(r.weight, 2));
    setCell(row, 5, r.done ? L"Да" : L"Нет");
}

// Заполняет таблицу на экране из файла. field = -1 - все записи, иначе только совпавшие.
// (Это единственное место, где файл читается подряд - только для показа на экране.)
int loadTable(int field = -1, const wstring& query = L"") {
    SendMessageW(g_table, LVM_DELETEALLITEMS, 0, 0);
    if (!g_open) return 0;

    fstream f = openFile(g_path, false);
    long size = fileSize(f);
    int count = 0;

    SendMessageW(g_table, WM_SETREDRAW, FALSE, 0);
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(f, pos);
        if (!r.deleted && (field == -1 || matches(r, field, query))) addRow(count++, r);
    }
    SendMessageW(g_table, WM_SETREDRAW, TRUE, 0);
    return count;
}

void showAll() {
    if (!g_open) {
        loadTable();
        setStatus(L"  База данных не открыта. Создайте или откройте файл БД.");
        return;
    }
    int n = loadTable();
    setStatus(L"  Файл: " + g_path + L"   |   Записей: " + to_wstring(n));
}


// ---------- Форма записи ----------

void clearForm() {
    g_selectedId = -1;
    for (HWND e : { g_edId, g_edClient, g_edExercise, g_edSets, g_edWeight }) SetWindowTextW(e, L"");
    SendMessageW(g_chkDone, BM_SETCHECK, BST_UNCHECKED, 0);
}

void fillForm(const Record& r) {
    g_selectedId = r.id;
    SetWindowTextW(g_edId, to_wstring(r.id).c_str());
    SetWindowTextW(g_edClient, r.client);
    SetWindowTextW(g_edExercise, r.exercise);
    SetWindowTextW(g_edSets, to_wstring(r.sets).c_str());
    SetWindowTextW(g_edWeight, toText(r.weight).c_str());
    SendMessageW(g_chkDone, BM_SETCHECK, r.done ? BST_CHECKED : BST_UNCHECKED, 0);
}

bool readForm(HWND hwnd, Record& out) {
    wstring client = getText(g_edClient), exercise = getText(g_edExercise);
    int id = 0, sets = 0;
    double weight = 0;

    bool ok = parseInt(getText(g_edId), id) && id > 0 &&
              parseInt(getText(g_edSets), sets) && sets >= 1 && sets <= 30 &&
              parseDouble(getText(g_edWeight), weight) && weight >= 0 && weight <= 500;
    if (!ok || client.empty() || exercise.empty()) {
        msg(hwnd, L"Проверьте поля: все заполнены, ID > 0, подходы 1..30, вес 0..500 кг.", MB_ICONWARNING);
        return false;
    }
    bool done = (SendMessageW(g_chkDone, BM_GETCHECK, 0, 0) == BST_CHECKED);
    out = makeRecord(id, client, exercise, sets, weight, done);
    return true;
}

// Пользователь щелкнул строку таблицы - берем полную запись из файла по ключу
void onRowSelected(int row) {
    wchar_t text[32] = {};
    LVITEMW item = {};
    item.pszText = text;
    item.cchTextMax = 32;
    SendMessageW(g_table, LVM_GETITEMTEXTW, row, reinterpret_cast<LPARAM>(&item));

    Record r;
    if (dbSearch(_wtoi(text), r)) fillForm(r);
}


// ---------- Действия кнопок ----------

void cmdCreateDb(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, true, FILTER_DB, L"db")) return;
    if (createDb(path) && openDb(path)) { clearForm(); showAll(); }
    else msg(hwnd, L"Не удалось создать файл БД!", MB_ICONERROR);
}

void cmdOpenDb(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, false, FILTER_DB, L"db")) return;
    if (openDb(path)) { clearForm(); showAll(); }
    else msg(hwnd, L"Это не файл базы данных этой программы!", MB_ICONERROR);
}

void cmdSaveAs(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_DB, L"db")) return;
    if (CopyFileW(g_path.c_str(), path.c_str(), FALSE) && openDb(path)) {
        showAll();
        msg(hwnd, L"База данных сохранена.");
    } else {
        msg(hwnd, L"Не удалось сохранить файл!", MB_ICONERROR);
    }
}

void cmdBackup(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_BAK, L"bak")) return;
    if (CopyFileW(g_path.c_str(), path.c_str(), FALSE)) msg(hwnd, L"Backup-файл создан.");
    else msg(hwnd, L"Не удалось создать backup!", MB_ICONERROR);
}

void cmdRestore(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, false, FILTER_BAK, L"bak")) return;
    if (!isDbFile(path)) { msg(hwnd, L"Это не backup этой программы!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Текущая база будет заменена данными из backup. Продолжить?")) return;

    if (CopyFileW(path.c_str(), g_path.c_str(), FALSE) && openDb(g_path)) {
        clearForm();
        showAll();
        msg(hwnd, L"База данных восстановлена из backup.");
    } else {
        msg(hwnd, L"Не удалось восстановить базу!", MB_ICONERROR);
    }
}

void cmdClearDb(HWND hwnd) {
    if (!needDb(hwnd) || !ask(hwnd, L"Удалить ВСЕ записи из базы?")) return;
    if (createDb(g_path)) { clearForm(); showAll(); }
}

void cmdDropDb(HWND hwnd) {
    if (!needDb(hwnd) || !ask(hwnd, L"Удалить файл базы данных с диска?")) return;
    if (DeleteFileW(g_path.c_str())) { g_open = false; clearForm(); showAll(); }
    else msg(hwnd, L"Не удалось удалить файл!", MB_ICONERROR);
}

void cmdExport(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_CSV, L"csv")) return;
    if (dbExportCsv(path)) msg(hwnd, L"Экспорт выполнен. Файл открывается в Excel.");
    else msg(hwnd, L"Не удалось записать файл!", MB_ICONERROR);
}

void cmdAdd(HWND hwnd) {
    Record rec;
    if (!needDb(hwnd) || !readForm(hwnd, rec)) return;
    if (dbAdd(rec)) { showAll(); setStatus(L"  Запись добавлена."); }
    else msg(hwnd, L"Запись с таким ID уже существует!", MB_ICONERROR);
}

void cmdEdit(HWND hwnd) {
    Record rec;
    if (!needDb(hwnd)) return;
    if (g_selectedId == -1) { msg(hwnd, L"Сначала выберите запись в таблице!", MB_ICONWARNING); return; }
    if (!readForm(hwnd, rec)) return;

    if (dbEdit(g_selectedId, rec)) {
        g_selectedId = rec.id;
        showAll();
        setStatus(L"  Запись изменена.");
    } else {
        msg(hwnd, L"Не удалось изменить запись (новый ID уже занят).", MB_ICONERROR);
    }
}

// Читает и проверяет поле + значение из блока "Поиск и удаление"
bool readQuery(HWND hwnd, int& field, wstring& query) {
    if (!needDb(hwnd)) return false;
    field = (int)SendMessageW(g_combo, CB_GETCURSEL, 0, 0);
    query = getText(g_edQuery);

    int i = 0;
    double d = 0;
    bool b = false, ok = !query.empty();
    if (field == 0 || field == 3) ok = ok && parseInt(query, i);
    if (field == 4)               ok = ok && parseDouble(query, d);
    if (field == 5)               ok = ok && parseBool(query, b);

    if (!ok) msg(hwnd, L"Введите корректное значение для выбранного поля (для «Выполнено» - Да или Нет).", MB_ICONWARNING);
    return ok;
}

void cmdSearch(HWND hwnd) {
    int field;
    wstring q;
    if (!readQuery(hwnd, field, q)) return;

    int found = 0;
    if (field == 0) {                          // по ключу - быстрый поиск через хеш
        int id = 0;
        Record r;
        parseInt(q, id);
        SendMessageW(g_table, LVM_DELETEALLITEMS, 0, 0);
        if (dbSearch(id, r)) { addRow(0, r); found = 1; }
    } else {                                   // по неключевому - все совпадения
        found = loadTable(field, q);
    }
    setStatus(L"  Найдено записей: " + to_wstring(found) + L". «Показать все» возвращает полный список.");
}

void cmdDelete(HWND hwnd) {
    int field;
    wstring q;
    if (!readQuery(hwnd, field, q) || !ask(hwnd, L"Удалить найденные записи?")) return;

    int deleted = 0;
    if (field == 0) {
        int id = 0;
        parseInt(q, id);
        deleted = dbDeleteKey(id) ? 1 : 0;
    } else {
        deleted = dbDeleteByField(field, q);
    }
    clearForm();
    showAll();
    if (deleted == 0) msg(hwnd, L"Записей с таким значением не найдено.");
    else setStatus(L"  Удалено записей: " + to_wstring(deleted));
}

// Замер скорости для отчета. Работает с отдельным временным файлом, ваша БД не затрагивается.
void cmdBenchmark(HWND hwnd) {
    typedef chrono::steady_clock Clock;
    wstring tmp = g_path + L".bench";
    wstring report = L"Среднее время одной операции:\n";
    const int sizes[] = { 1000, 5000, 10000 };

    for (int n : sizes) {
        createDb(tmp);
        fstream f = openFile(tmp, true);

        Clock::time_point t0 = Clock::now();
        for (int i = 1; i <= n; i++) addToFile(f, makeRecord(i, L"Клиент", L"Упражнение", 3, 50.0, false));
        Clock::time_point t1 = Clock::now();
        for (int i = 1; i <= n; i++) findOffset(f, i);
        Clock::time_point t2 = Clock::now();

        long size = fileSize(f);                                   // поиск по неключевому полю
        int found = 0;
        for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE)
            if (matches(readAt<Record>(f, pos), 3, L"3")) found++;
        Clock::time_point t3 = Clock::now();

        for (int i = 1; i <= n; i++) deleteFromFile(f, i);
        Clock::time_point t4 = Clock::now();

        auto perOp = [&](Clock::time_point a, Clock::time_point b) {
            return chrono::duration<double, micro>(b - a).count() / n;
        };
        report += L"\nN = " + to_wstring(n) + L" записей:\n" +
                  L"  добавление: " + toText(perOp(t0, t1), 1) + L" мкс\n" +
                  L"  поиск по ключу: " + toText(perOp(t1, t2), 1) + L" мкс\n" +
                  L"  удаление по ключу: " + toText(perOp(t3, t4), 1) + L" мкс\n" +
                  L"  поиск по неключевому полю (весь файл): " +
                  toText(chrono::duration<double, milli>(t3 - t2).count(), 1) + L" мс (найдено " +
                  to_wstring(found) + L")\n";
    }
    DeleteFileW(tmp.c_str());
    msg(hwnd, report);
}


