/*
 * Лабораторная работа №2. Файловая база данных с GUI.
 * Предметная область: журнал тренировок.
 *
 * Файл БД - это хеш-таблица с цепочками прямо на диске:
 *     [ Header ][ Record ][ Record ][ Record ] ...
 *   Header: сигнатура, число записей, начало списка свободных слотов, 1009 корзин.
 *   Корзина хранит смещение первой записи цепочки, запись хранит смещение следующей.
 * В памяти база НЕ хранится: каждая операция читает и пишет только нужные байты файла.
 *
 * Сложность:  добавление / удаление / поиск по ключу - O(1) в среднем,
 *             поиск и удаление по неключевому полю   - O(N).
 *
 * Сборка:
 *   MSVC : cl /EHsc /std:c++17 /utf-8 workout_db_final.cpp
 *   MinGW: g++ -std=c++17 workout_db_final.cpp -o workout_db.exe -mwindows -lcomctl32 -lcomdlg32 -lgdi32
 */

#define _CRT_SECURE_NO_WARNINGS
#define NOMINMAX

#include <windows.h>
#include <commctrl.h>
#include <commdlg.h>
#include <chrono>
#include <cmath>
#include <cstddef>
#include <cstdlib>
#include <cwchar>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <string>

#ifdef _MSC_VER
#pragma comment(lib, "comctl32.lib")
#pragma comment(lib, "comdlg32.lib")
#pragma comment(linker, "/SUBSYSTEM:WINDOWS")
#endif

using namespace std;


// ============================================================================
// ЧАСТЬ 1. ФАЙЛОВАЯ БАЗА ДАННЫХ
// ============================================================================

const int HASH_SIZE = 1009;       // число корзин (простое число)
const int SIGNATURE = 0x57444231; // "WDB1" - метка нашего файла
const int TEXT_LEN  = 32;         // длина текстовых полей (в символах)

struct Header {                   // лежит в начале файла
    int  signature;
    int  count;                   // сколько живых записей
    long freeHead;                // первый свободный слот (-1, если нет)
    long buckets[HASH_SIZE];      // смещения первых записей цепочек (-1, если пусто)
};

struct Record {                   // одна запись таблицы
    int     id;                   // КЛЮЧ
    wchar_t client[TEXT_LEN];     // клиент
    wchar_t exercise[TEXT_LEN];   // упражнение
    int     sets;                 // подходы
    double  weight;               // рабочий вес, кг
    bool    done;                 // выполнено в журнале
    bool    deleted;              // служебное: слот свободен
    long    next;                 // служебное: следующая запись цепочки / свободного списка
};

const long HEADER_SIZE = sizeof(Header);
const long RECORD_SIZE = sizeof(Record);
const long POS_COUNT   = offsetof(Header, count);
const long POS_FREE    = offsetof(Header, freeHead);
const long POS_NEXT    = offsetof(Record, next);   // смещение внутри записи

wstring g_path = L"trainings.db"; // текущий файл БД
bool    g_open = false;           // открыта ли БД


// ---------- Чтение и запись по смещению ----------

template <class T> T readAt(fstream& f, long pos) {
    T value{};
    f.clear();
    f.seekg(pos, ios::beg);
    f.read(reinterpret_cast<char*>(&value), sizeof(T));
    return value;
}

template <class T> void writeAt(fstream& f, long pos, const T& value) {
    f.clear();
    f.seekp(pos, ios::beg);
    f.write(reinterpret_cast<const char*>(&value), sizeof(T));
}

long fileSize(fstream& f) {
    f.clear();
    f.seekg(0, ios::end);
    return static_cast<long>(static_cast<streamoff>(f.tellg()));
}

fstream openFile(const wstring& path, bool forWrite) {
    ios::openmode mode = ios::in | ios::binary;
    if (forWrite) mode |= ios::out;
    return fstream(filesystem::path(path), mode);
}

long bucketPos(int id) {   // где в файле лежит корзина этого ключа
    return (long)offsetof(Header, buckets) + (id % HASH_SIZE) * (long)sizeof(long);
}

Record makeRecord(int id, const wstring& client, const wstring& exercise, int sets, double weight, bool done) {
    Record r = {};
    r.id = id;
    wcsncpy(r.client, client.c_str(), TEXT_LEN - 1);
    wcsncpy(r.exercise, exercise.c_str(), TEXT_LEN - 1);
    r.sets = sets;
    r.weight = weight;
    r.done = done;
    r.next = -1;
    return r;
}


// ---------- Файл БД: создание, проверка, открытие ----------

bool createDb(const wstring& path) {          // создает пустую БД (или затирает старую)
    ofstream f(filesystem::path(path), ios::binary | ios::trunc);
    Header h;
    h.signature = SIGNATURE;
    h.count = 0;
    h.freeHead = -1;
    for (long& b : h.buckets) b = -1;
    f.write(reinterpret_cast<const char*>(&h), sizeof(h));
    return f.good();
}

bool isDbFile(const wstring& path) {          // наш ли это файл
    fstream f = openFile(path, false);
    if (!f.is_open()) return false;
    Header h = readAt<Header>(f, 0);
    long size = fileSize(f);
    return h.signature == SIGNATURE && size >= HEADER_SIZE && (size - HEADER_SIZE) % RECORD_SIZE == 0;
}

bool openDb(const wstring& path) {
    if (!isDbFile(path)) return false;
    g_path = path;
    g_open = true;
    return true;
}


// ---------- Поиск по ключу ----------

long findOffset(fstream& f, int id, Record* out = nullptr) {   // смещение записи или -1
    long pos = readAt<long>(f, bucketPos(id));                 // начало цепочки
    while (pos != -1) {
        Record r = readAt<Record>(f, pos);
        if (r.id == id) {
            if (out) *out = r;
            return pos;
        }
        pos = r.next;                                          // идем по цепочке
    }
    return -1;
}

bool dbSearch(int id, Record& out) {
    fstream f = openFile(g_path, false);
    return f.is_open() && findOffset(f, id, &out) != -1;
}


// ---------- Добавление ----------

bool addToFile(fstream& f, Record rec) {
    if (findOffset(f, rec.id) != -1) return false;             // ключ должен быть уникальным

    long bucket = bucketPos(rec.id);
    rec.deleted = false;
    rec.next = readAt<long>(f, bucket);                        // новая запись встает в начало цепочки

    long pos = readAt<long>(f, POS_FREE);
    if (pos != -1) {                                           // есть свободный слот - используем его
        writeAt(f, POS_FREE, readAt<Record>(f, pos).next);
    } else {                                                   // иначе пишем в конец файла
        pos = fileSize(f);
    }

    writeAt(f, pos, rec);
    writeAt(f, bucket, pos);
    writeAt(f, POS_COUNT, readAt<int>(f, POS_COUNT) + 1);
    return true;
}

bool dbAdd(const Record& rec) {
    fstream f = openFile(g_path, true);
    return f.is_open() && addToFile(f, rec);
}


// ---------- Удаление ----------

bool deleteFromFile(fstream& f, int id) {
    long bucket = bucketPos(id);
    long prev = -1;
    long pos = readAt<long>(f, bucket);

    while (pos != -1) {
        Record r = readAt<Record>(f, pos);
        if (r.id == id) {
            if (prev == -1) writeAt(f, bucket, r.next);        // была первой в цепочке
            else            writeAt(f, prev + POS_NEXT, r.next); // иначе "перепрыгиваем" через нее

            r.deleted = true;                                  // слот уходит в список свободных
            r.next = readAt<long>(f, POS_FREE);
            writeAt(f, pos, r);
            writeAt(f, POS_FREE, pos);
            writeAt(f, POS_COUNT, readAt<int>(f, POS_COUNT) - 1);
            return true;
        }
        prev = pos;
        pos = r.next;
    }
    return false;
}

bool dbDeleteKey(int id) {
    fstream f = openFile(g_path, true);
    return f.is_open() && deleteFromFile(f, id);
}


// ---------- Разбор текста и сравнение по неключевым полям ----------

bool parseInt(const wstring& s, int& out) {
    wchar_t* end = nullptr;
    long v = wcstol(s.c_str(), &end, 10);
    if (s.empty() || *end != L'\0' || v < 0 || v > 1000000000) return false;
    out = (int)v;
    return true;
}

bool parseDouble(wstring s, double& out) {
    for (wchar_t& c : s) if (c == L',') c = L'.';              // 12,5 -> 12.5
    wchar_t* end = nullptr;
    out = wcstod(s.c_str(), &end);
    return !s.empty() && *end == L'\0';
}

wstring toLower(wstring s) {                                   // работает и для русских букв
    CharLowerBuffW(&s[0], (DWORD)s.size());
    return s;
}

bool parseBool(const wstring& s, bool& out) {
    wstring t = toLower(s);
    if (t == L"да" || t == L"1")  { out = true;  return true; }
    if (t == L"нет" || t == L"0") { out = false; return true; }
    return false;
}

wstring toText(double v, int digits = -1) {                    // число -> текст
    wstringstream s;
    if (digits >= 0) s << fixed << setprecision(digits);
    s << v;
    return s.str();
}

// Номера полей: 1 - клиент, 2 - упражнение, 3 - подходы, 4 - вес, 5 - выполнено
bool matches(const Record& r, int field, const wstring& q) {
    int i = 0;
    double d = 0;
    bool b = false;
    switch (field) {
        case 1: return toLower(r.client).find(toLower(q)) != wstring::npos;
        case 2: return toLower(r.exercise).find(toLower(q)) != wstring::npos;
        case 3: return parseInt(q, i) && r.sets == i;
        case 4: return parseDouble(q, d) && fabs(r.weight - d) < 0.001;
        case 5: return parseBool(q, b) && r.done == b;
    }
    return false;
}

int dbDeleteByField(int field, const wstring& q) {             // удаляет ВСЕ совпавшие записи
    fstream f = openFile(g_path, true);
    long size = fileSize(f);
    int deleted = 0;
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(f, pos);
        if (!r.deleted && matches(r, field, q) && deleteFromFile(f, r.id)) deleted++;
    }
    return deleted;
}


// ---------- Редактирование ----------

bool dbEdit(int oldId, Record rec) {
    fstream f = openFile(g_path, true);
    if (!f.is_open()) return false;

    Record old;
    long pos = findOffset(f, oldId, &old);
    if (pos == -1) return false;

    if (rec.id == oldId) {                                     // ключ не менялся - пишем поверх
        rec.deleted = false;
        rec.next = old.next;
        writeAt(f, pos, rec);
        return true;
    }
    if (findOffset(f, rec.id) != -1) return false;             // новый ключ занят
    deleteFromFile(f, oldId);                                  // ключ изменился - удалить + добавить
    return addToFile(f, rec);
}


// ---------- Экспорт в CSV (открывается в Excel) ----------

string toUtf8(const wstring& w) {
    int n = WideCharToMultiByte(CP_UTF8, 0, w.c_str(), -1, nullptr, 0, nullptr, nullptr);
    string s(n, '\0');
    WideCharToMultiByte(CP_UTF8, 0, w.c_str(), -1, &s[0], n, nullptr, nullptr);
    s.resize(n - 1);
    return s;
}

bool dbExportCsv(const wstring& csvPath) {
    fstream db = openFile(g_path, false);
    ofstream csv(filesystem::path(csvPath), ios::binary | ios::trunc);
    if (!db.is_open() || !csv.is_open()) return false;

    auto quote = [](const wstring& s) {                        // текст в кавычках, " удваивается
        wstring r = L"\"";
        for (wchar_t c : s) {
            if (c == L'"') r += L'"';
            r += c;
        }
        return r + L"\"";
    };

    csv << "\xEF\xBB\xBF";                                     // метка UTF-8, чтобы Excel понял кодировку
    csv << toUtf8(L"ID;Клиент;Упражнение;Подходы;Вес (кг);Выполнено\r\n");

    long size = fileSize(db);
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(db, pos);
        if (r.deleted) continue;
        wstring weight = toText(r.weight, 2);
        for (wchar_t& c : weight) if (c == L'.') c = L',';     // русский Excel ждет запятую
        wstring line = to_wstring(r.id) + L";" + quote(r.client) + L";" + quote(r.exercise) + L";" +
                       to_wstring(r.sets) + L";" + weight + L";" + (r.done ? L"Да" : L"Нет") + L"\r\n";
        csv << toUtf8(line);
    }
    return csv.good();
}


