    ID_BTN_SHOW_ALL = 401, ID_BTN_BENCH, ID_TABLE
};

const COLORREF CLR_WINDOW = RGB(240, 244, 249);
const COLORREF CLR_CARD   = RGB(255, 255, 255);
const COLORREF CLR_BORDER = RGB(218, 226, 236);
