const wchar_t* TITLE = L"Журнал тренировок — файловая БД";

// Фильтры диалогов выбора файла
const wchar_t FILTER_DB[]  = L"Файлы БД (*.db)\0*.db\0Все файлы (*.*)\0*.*\0";
const wchar_t FILTER_BAK[] = L"Backup (*.bak)\0*.bak\0Все файлы (*.*)\0*.*\0";
const wchar_t FILTER_CSV[] = L"CSV для Excel (*.csv)\0*.csv\0";

HWND g_table, g_status, g_combo;
HWND g_edId, g_edClient, g_edExercise, g_edSets, g_edWeight, g_chkDone, g_edQuery;
HFONT g_fontRegular, g_fontBold;
HBRUSH g_brWindow, g_brCard, g_brInput;

int g_selectedId = -1;   // ключ записи, выбранной в таблице


// ---------- Мелкие помощники ----------

void msg(HWND hwnd, const wstring& text, UINT icon = MB_ICONINFORMATION) {
    MessageBoxW(hwnd, text.c_str(), TITLE, MB_OK | icon);
}

bool ask(HWND hwnd, const wstring& text) {
    return MessageBoxW(hwnd, text.c_str(), TITLE, MB_YESNO | MB_ICONQUESTION) == IDYES;
}

bool needDb(HWND hwnd) {
    if (!g_open) msg(hwnd, L"База данных не открыта! Создайте или откройте файл БД.", MB_ICONERROR);
    return g_open;
}

void setStatus(const wstring& text) { SetWindowTextW(g_status, text.c_str()); }

wstring getText(HWND h) {
    wchar_t buf[256] = {};
    GetWindowTextW(h, buf, 255);
    return buf;
}

bool pickFile(HWND hwnd, wstring& path, bool save, const wchar_t* filter, const wchar_t* ext) {
    wchar_t buf[MAX_PATH] = {};
    OPENFILENAMEW ofn = {};
    ofn.lStructSize = sizeof(ofn);
    ofn.hwndOwner = hwnd;
    ofn.lpstrFilter = filter;
    ofn.lpstrFile = buf;
    ofn.nMaxFile = MAX_PATH;
    ofn.lpstrDefExt = ext;
    ofn.Flags = OFN_NOCHANGEDIR | (save ? OFN_OVERWRITEPROMPT : OFN_FILEMUSTEXIST);
    if (!(save ? GetSaveFileNameW(&ofn) : GetOpenFileNameW(&ofn))) return false;
    path = buf;
    return true;
}


// ---------- Таблица ----------

void setCell(int row, int col, const wstring& text) {
    LVITEMW item = {};
    item.iSubItem = col;
    item.pszText = const_cast<LPWSTR>(text.c_str());
    SendMessageW(g_table, LVM_SETITEMTEXTW, row, reinterpret_cast<LPARAM>(&item));
}

void addRow(int row, const Record& r) {
    wstring id = to_wstring(r.id);
    LVITEMW item = {};
    item.mask = LVIF_TEXT;
    item.iItem = row;
    item.pszText = const_cast<LPWSTR>(id.c_str());
    SendMessageW(g_table, LVM_INSERTITEMW, 0, reinterpret_cast<LPARAM>(&item));

    setCell(row, 1, r.client);
    setCell(row, 2, r.exercise);
    setCell(row, 3, to_wstring(r.sets));
    setCell(row, 4, toText(r.weight, 2));
    setCell(row, 5, r.done ? L"Да" : L"Нет");
}

// Заполняет таблицу на экране из файла. field = -1 - все записи, иначе только совпавшие.
// (Это единственное место, где файл читается подряд - только для показа на экране.)
int loadTable(int field = -1, const wstring& query = L"") {
    SendMessageW(g_table, LVM_DELETEALLITEMS, 0, 0);
    if (!g_open) return 0;

    fstream f = openFile(g_path, false);
    long size = fileSize(f);
    int count = 0;

    SendMessageW(g_table, WM_SETREDRAW, FALSE, 0);
    for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE) {
        Record r = readAt<Record>(f, pos);
        if (!r.deleted && (field == -1 || matches(r, field, query))) addRow(count++, r);
    }
    SendMessageW(g_table, WM_SETREDRAW, TRUE, 0);
    return count;
}

void showAll() {
    if (!g_open) {
        loadTable();
        setStatus(L"  База данных не открыта. Создайте или откройте файл БД.");
        return;
    }
    int n = loadTable();
    setStatus(L"  Файл: " + g_path + L"   |   Записей: " + to_wstring(n));
}


// ---------- Форма записи ----------

void clearForm() {
    g_selectedId = -1;
    for (HWND e : { g_edId, g_edClient, g_edExercise, g_edSets, g_edWeight }) SetWindowTextW(e, L"");
    SendMessageW(g_chkDone, BM_SETCHECK, BST_UNCHECKED, 0);
}

void fillForm(const Record& r) {
    g_selectedId = r.id;
    SetWindowTextW(g_edId, to_wstring(r.id).c_str());
    SetWindowTextW(g_edClient, r.client);
    SetWindowTextW(g_edExercise, r.exercise);
    SetWindowTextW(g_edSets, to_wstring(r.sets).c_str());
    SetWindowTextW(g_edWeight, toText(r.weight).c_str());
    SendMessageW(g_chkDone, BM_SETCHECK, r.done ? BST_CHECKED : BST_UNCHECKED, 0);
}

bool readForm(HWND hwnd, Record& out) {
    wstring client = getText(g_edClient), exercise = getText(g_edExercise);
    int id = 0, sets = 0;
    double weight = 0;

    bool ok = parseInt(getText(g_edId), id) && id > 0 &&
              parseInt(getText(g_edSets), sets) && sets >= 1 && sets <= 30 &&
              parseDouble(getText(g_edWeight), weight) && weight >= 0 && weight <= 500;
    if (!ok || client.empty() || exercise.empty()) {
        msg(hwnd, L"Проверьте поля: все заполнены, ID > 0, подходы 1..30, вес 0..500 кг.", MB_ICONWARNING);
        return false;
    }
    bool done = (SendMessageW(g_chkDone, BM_GETCHECK, 0, 0) == BST_CHECKED);
    out = makeRecord(id, client, exercise, sets, weight, done);
    return true;
}

// Пользователь щелкнул строку таблицы - берем полную запись из файла по ключу
void onRowSelected(int row) {
    wchar_t text[32] = {};
    LVITEMW item = {};
    item.pszText = text;
    item.cchTextMax = 32;
    SendMessageW(g_table, LVM_GETITEMTEXTW, row, reinterpret_cast<LPARAM>(&item));

    Record r;
    if (dbSearch(_wtoi(text), r)) fillForm(r);
}


// ---------- Действия кнопок ----------

void cmdCreateDb(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, true, FILTER_DB, L"db")) return;
    if (createDb(path) && openDb(path)) { clearForm(); showAll(); }
    else msg(hwnd, L"Не удалось создать файл БД!", MB_ICONERROR);
}

void cmdOpenDb(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, false, FILTER_DB, L"db")) return;
    if (openDb(path)) { clearForm(); showAll(); }
    else msg(hwnd, L"Это не файл базы данных этой программы!", MB_ICONERROR);
}

void cmdSaveAs(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_DB, L"db")) return;
    if (CopyFileW(g_path.c_str(), path.c_str(), FALSE) && openDb(path)) {
        showAll();
        msg(hwnd, L"База данных сохранена.");
    } else {
        msg(hwnd, L"Не удалось сохранить файл!", MB_ICONERROR);
    }
}

void cmdBackup(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_BAK, L"bak")) return;
    if (CopyFileW(g_path.c_str(), path.c_str(), FALSE)) msg(hwnd, L"Backup-файл создан.");
    else msg(hwnd, L"Не удалось создать backup!", MB_ICONERROR);
}

void cmdRestore(HWND hwnd) {
    wstring path;
    if (!pickFile(hwnd, path, false, FILTER_BAK, L"bak")) return;
    if (!isDbFile(path)) { msg(hwnd, L"Это не backup этой программы!", MB_ICONERROR); return; }
    if (!ask(hwnd, L"Текущая база будет заменена данными из backup. Продолжить?")) return;

    if (CopyFileW(path.c_str(), g_path.c_str(), FALSE) && openDb(g_path)) {
        clearForm();
        showAll();
        msg(hwnd, L"База данных восстановлена из backup.");
    } else {
        msg(hwnd, L"Не удалось восстановить базу!", MB_ICONERROR);
    }
}

void cmdClearDb(HWND hwnd) {
    if (!needDb(hwnd) || !ask(hwnd, L"Удалить ВСЕ записи из базы?")) return;
    if (createDb(g_path)) { clearForm(); showAll(); }
}

void cmdDropDb(HWND hwnd) {
    if (!needDb(hwnd) || !ask(hwnd, L"Удалить файл базы данных с диска?")) return;
    if (DeleteFileW(g_path.c_str())) { g_open = false; clearForm(); showAll(); }
    else msg(hwnd, L"Не удалось удалить файл!", MB_ICONERROR);
}

void cmdExport(HWND hwnd) {
    wstring path;
    if (!needDb(hwnd) || !pickFile(hwnd, path, true, FILTER_CSV, L"csv")) return;
    if (dbExportCsv(path)) msg(hwnd, L"Экспорт выполнен. Файл открывается в Excel.");
    else msg(hwnd, L"Не удалось записать файл!", MB_ICONERROR);
}

void cmdAdd(HWND hwnd) {
    Record rec;
    if (!needDb(hwnd) || !readForm(hwnd, rec)) return;
    if (dbAdd(rec)) { showAll(); setStatus(L"  Запись добавлена."); }
    else msg(hwnd, L"Запись с таким ID уже существует!", MB_ICONERROR);
}

void cmdEdit(HWND hwnd) {
    Record rec;
    if (!needDb(hwnd)) return;
    if (g_selectedId == -1) { msg(hwnd, L"Сначала выберите запись в таблице!", MB_ICONWARNING); return; }
    if (!readForm(hwnd, rec)) return;

    if (dbEdit(g_selectedId, rec)) {
        g_selectedId = rec.id;
        showAll();
        setStatus(L"  Запись изменена.");
    } else {
        msg(hwnd, L"Не удалось изменить запись (новый ID уже занят).", MB_ICONERROR);
    }
}

// Читает и проверяет поле + значение из блока "Поиск и удаление"
bool readQuery(HWND hwnd, int& field, wstring& query) {
    if (!needDb(hwnd)) return false;
    field = (int)SendMessageW(g_combo, CB_GETCURSEL, 0, 0);
    query = getText(g_edQuery);

    int i = 0;
    double d = 0;
    bool b = false, ok = !query.empty();
    if (field == 0 || field == 3) ok = ok && parseInt(query, i);
    if (field == 4)               ok = ok && parseDouble(query, d);
    if (field == 5)               ok = ok && parseBool(query, b);

    if (!ok) msg(hwnd, L"Введите корректное значение для выбранного поля (для «Выполнено» - Да или Нет).", MB_ICONWARNING);
    return ok;
}

void cmdSearch(HWND hwnd) {
    int field;
    wstring q;
    if (!readQuery(hwnd, field, q)) return;

    int found = 0;
    if (field == 0) {                          // по ключу - быстрый поиск через хеш
        int id = 0;
        Record r;
        parseInt(q, id);
        SendMessageW(g_table, LVM_DELETEALLITEMS, 0, 0);
        if (dbSearch(id, r)) { addRow(0, r); found = 1; }
    } else {                                   // по неключевому - все совпадения
        found = loadTable(field, q);
    }
    setStatus(L"  Найдено записей: " + to_wstring(found) + L". «Показать все» возвращает полный список.");
}

void cmdDelete(HWND hwnd) {
    int field;
    wstring q;
    if (!readQuery(hwnd, field, q) || !ask(hwnd, L"Удалить найденные записи?")) return;

    int deleted = 0;
    if (field == 0) {
        int id = 0;
        parseInt(q, id);
        deleted = dbDeleteKey(id) ? 1 : 0;
    } else {
        deleted = dbDeleteByField(field, q);
    }
    clearForm();
    showAll();
    if (deleted == 0) msg(hwnd, L"Записей с таким значением не найдено.");
    else setStatus(L"  Удалено записей: " + to_wstring(deleted));
}

// Замер скорости для отчета. Работает с отдельным временным файлом, ваша БД не затрагивается.
void cmdBenchmark(HWND hwnd) {
    typedef chrono::steady_clock Clock;
    wstring tmp = g_path + L".bench";
    wstring report = L"Среднее время одной операции:\n";
    const int sizes[] = { 1000, 5000, 10000 };

    for (int n : sizes) {
        createDb(tmp);
        fstream f = openFile(tmp, true);

        Clock::time_point t0 = Clock::now();
        for (int i = 1; i <= n; i++) addToFile(f, makeRecord(i, L"Клиент", L"Упражнение", 3, 50.0, false));
        Clock::time_point t1 = Clock::now();
        for (int i = 1; i <= n; i++) findOffset(f, i);
        Clock::time_point t2 = Clock::now();

        long size = fileSize(f);                                   // поиск по неключевому полю
        int found = 0;
        for (long pos = HEADER_SIZE; pos + RECORD_SIZE <= size; pos += RECORD_SIZE)
            if (matches(readAt<Record>(f, pos), 3, L"3")) found++;
        Clock::time_point t3 = Clock::now();

        for (int i = 1; i <= n; i++) deleteFromFile(f, i);
        Clock::time_point t4 = Clock::now();

        auto perOp = [&](Clock::time_point a, Clock::time_point b) {
            return chrono::duration<double, micro>(b - a).count() / n;
        };
        report += L"\nN = " + to_wstring(n) + L" записей:\n" +
                  L"  добавление: " + toText(perOp(t0, t1), 1) + L" мкс\n" +
                  L"  поиск по ключу: " + toText(perOp(t1, t2), 1) + L" мкс\n" +
                  L"  удаление по ключу: " + toText(perOp(t3, t4), 1) + L" мкс\n" +
                  L"  поиск по неключевому полю (весь файл): " +
                  toText(chrono::duration<double, milli>(t3 - t2).count(), 1) + L" мс (найдено " +
                  to_wstring(found) + L")\n";
    }
    DeleteFileW(tmp.c_str());
    msg(hwnd, report);
}


