void drawCard(HDC hdc, int x, int y, int w, int h, const wchar_t* title) {
    HPEN pen = CreatePen(PS_SOLID, 1, CLR_BORDER);
    HGDIOBJ oldPen = SelectObject(hdc, pen);
    HGDIOBJ oldBrush = SelectObject(hdc, g_brCard);
    RoundRect(hdc, x, y, x + w, y + h, 12, 12);
    SelectObject(hdc, oldBrush);
    SelectObject(hdc, oldPen);
    DeleteObject(pen);

    HGDIOBJ oldFont = SelectObject(hdc, g_fontBold);
    SetBkMode(hdc, TRANSPARENT);
    SetTextColor(hdc, CLR_TEXT);
    RECT rc = { x + 16, y + 8, x + w - 16, y + 32 };
    DrawTextW(hdc, title, -1, &rc, DT_LEFT | DT_VCENTER | DT_SINGLELINE);
    SelectObject(hdc, oldFont);
}

void drawButton(LPDRAWITEMSTRUCT d) {
    bool pressed = (d->itemState & ODS_SELECTED) != 0;
    COLORREF bg = pressed ? RGB(222, 229, 238) : RGB(238, 242, 247);
    COLORREF text = CLR_TEXT, border = RGB(205, 215, 228);

    if (d->CtlID == ID_BTN_ADD || d->CtlID == ID_BTN_SEARCH) {          // главные - синие
        bg = pressed ? RGB(37, 99, 235) : RGB(59, 130, 246);
        text = RGB(255, 255, 255);
        border = bg;
    } else if (d->CtlID == ID_BTN_DELETE || d->CtlID == ID_BTN_DROP_DB) { // опасные - красные
        bg = pressed ? RGB(220, 38, 38) : RGB(239, 68, 68);
        text = RGB(255, 255, 255);
        border = bg;
    }

    FillRect(d->hDC, &d->rcItem, g_brCard);                             // фон под скругленными углами
    HBRUSH brush = CreateSolidBrush(bg);
    HPEN pen = CreatePen(PS_SOLID, 1, border);
    HGDIOBJ oldBrush = SelectObject(d->hDC, brush);
    HGDIOBJ oldPen = SelectObject(d->hDC, pen);
    RoundRect(d->hDC, d->rcItem.left, d->rcItem.top, d->rcItem.right, d->rcItem.bottom, 8, 8);
    SelectObject(d->hDC, oldBrush);
    SelectObject(d->hDC, oldPen);
    DeleteObject(brush);
    DeleteObject(pen);

    wstring caption = getText(d->hwndItem);
    SetBkMode(d->hDC, TRANSPARENT);
    SetTextColor(d->hDC, text);
    HGDIOBJ oldFont = SelectObject(d->hDC, g_fontRegular);
    DrawTextW(d->hDC, caption.c_str(), -1, &d->rcItem, DT_CENTER | DT_VCENTER | DT_SINGLELINE);
    SelectObject(d->hDC, oldFont);
}

LRESULT CALLBACK WndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam) {
    switch (message) {
        case WM_CREATE:
            createControls(hwnd);
            return 0;

        case WM_PAINT: {
            PAINTSTRUCT ps;
            HDC hdc = BeginPaint(hwnd, &ps);
            drawCard(hdc, 14, 10,  972, 70,  L"База данных");
            drawCard(hdc, 14, 88,  350, 300, L"Запись");
            drawCard(hdc, 14, 396, 350, 208, L"Поиск и удаление");
            drawCard(hdc, 374, 88, 612, 516, L"Журнал тренировок");
            EndPaint(hwnd, &ps);
            return 0;
        }

        case WM_DRAWITEM:
            drawButton(reinterpret_cast<LPDRAWITEMSTRUCT>(lParam));
            return TRUE;

        case WM_CTLCOLORSTATIC:       // подписи и чекбокс: белый фон карточки (строка состояния - фон окна)
        case WM_CTLCOLORBTN: {
            HDC hdc = reinterpret_cast<HDC>(wParam);
            bool isStatus = (reinterpret_cast<HWND>(lParam) == g_status);
            SetTextColor(hdc, CLR_TEXT);
            SetBkColor(hdc, isStatus ? CLR_WINDOW : CLR_CARD);
            return reinterpret_cast<LRESULT>(isStatus ? g_brWindow : g_brCard);
        }

        case WM_CTLCOLOREDIT: {
            HDC hdc = reinterpret_cast<HDC>(wParam);
            SetTextColor(hdc, CLR_TEXT);
            SetBkColor(hdc, CLR_INPUT);
            return reinterpret_cast<LRESULT>(g_brInput);
        }

        case WM_NOTIFY: {
            LPNMHDR nm = reinterpret_cast<LPNMHDR>(lParam);
            if (nm->idFrom != ID_TABLE) break;

            if (nm->code == NM_CUSTOMDRAW) {                            // чередование цвета строк
                LPNMLVCUSTOMDRAW cd = reinterpret_cast<LPNMLVCUSTOMDRAW>(lParam);
                if (cd->nmcd.dwDrawStage == CDDS_PREPAINT) return CDRF_NOTIFYITEMDRAW;
                if (cd->nmcd.dwDrawStage == CDDS_ITEMPREPAINT) {
                    cd->clrTextBk = (cd->nmcd.dwItemSpec % 2 == 0) ? RGB(255, 255, 255) : RGB(244, 248, 254);
                    cd->clrText = CLR_TEXT;
                    return CDRF_NEWFONT;
                }
            }
            if (nm->code == LVN_ITEMCHANGED) {                          // выбор строки
                LPNMLISTVIEW info = reinterpret_cast<LPNMLISTVIEW>(lParam);
                if ((info->uChanged & LVIF_STATE) && (info->uNewState & LVIS_SELECTED)) onRowSelected(info->iItem);
            }
            break;
        }

        case WM_COMMAND:
            switch (LOWORD(wParam)) {
                case ID_BTN_CREATE:     cmdCreateDb(hwnd);  break;
                case ID_BTN_OPEN:       cmdOpenDb(hwnd);    break;
                case ID_BTN_SAVE_AS:    cmdSaveAs(hwnd);    break;
                case ID_BTN_BACKUP:     cmdBackup(hwnd);    break;
                case ID_BTN_RESTORE:    cmdRestore(hwnd);   break;
                case ID_BTN_CLEAR_DB:   cmdClearDb(hwnd);   break;
                case ID_BTN_DROP_DB:    cmdDropDb(hwnd);    break;
                case ID_BTN_EXPORT:     cmdExport(hwnd);    break;
                case ID_BTN_ADD:        cmdAdd(hwnd);       break;
                case ID_BTN_EDIT:       cmdEdit(hwnd);      break;
                case ID_BTN_CLEAR_FORM: clearForm();        break;
                case ID_BTN_SEARCH:     cmdSearch(hwnd);    break;
                case ID_BTN_DELETE:     cmdDelete(hwnd);    break;
                case ID_BTN_SHOW_ALL:   showAll();          break;
                case ID_BTN_BENCH:      cmdBenchmark(hwnd); break;
            }
            return 0;

        case WM_DESTROY:
            DeleteObject(g_fontRegular);
            DeleteObject(g_fontBold);
            DeleteObject(g_brWindow);
            DeleteObject(g_brCard);
            DeleteObject(g_brInput);
            PostQuitMessage(0);
            return 0;
    }
    return DefWindowProcW(hwnd, message, wParam, lParam);
}

int WINAPI WinMain(HINSTANCE hInst, HINSTANCE, LPSTR, int nCmdShow) {
    INITCOMMONCONTROLSEX icc = { sizeof(icc), ICC_LISTVIEW_CLASSES };
    InitCommonControlsEx(&icc);

    g_brWindow = CreateSolidBrush(CLR_WINDOW);
    g_brCard   = CreateSolidBrush(CLR_CARD);
    g_brInput  = CreateSolidBrush(CLR_INPUT);

    WNDCLASSEXW wc = {};
    wc.cbSize = sizeof(wc);
    wc.style = CS_HREDRAW | CS_VREDRAW;
    wc.lpfnWndProc = WndProc;
    wc.hInstance = hInst;
    wc.hCursor = LoadCursor(nullptr, IDC_ARROW);
    wc.hIcon = LoadIcon(nullptr, IDI_APPLICATION);
    wc.hbrBackground = g_brWindow;
    wc.lpszClassName = L"WorkoutDbWindow";
    if (!RegisterClassExW(&wc)) return 0;

    // Окно фиксированного размера: рабочая область ровно 1000 x 640 (помещается на любой экран)
    DWORD style = WS_OVERLAPPED | WS_CAPTION | WS_SYSMENU | WS_MINIMIZEBOX | WS_CLIPCHILDREN;
    RECT rc = { 0, 0, 1000, 640 };
    AdjustWindowRect(&rc, style, FALSE);

    HWND hwnd = CreateWindowExW(0, wc.lpszClassName, TITLE, style, CW_USEDEFAULT, CW_USEDEFAULT,
                                rc.right - rc.left, rc.bottom - rc.top, nullptr, nullptr, hInst, nullptr);
    ShowWindow(hwnd, nCmdShow);
    UpdateWindow(hwnd);

    MSG m;
    while (GetMessageW(&m, nullptr, 0, 0) > 0) {
        TranslateMessage(&m);
        DispatchMessageW(&m);
    }
    return static_cast<int>(m.wParam);
}

