const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, Table, TableRow, TableCell,
  WidthType, ShadingType, BorderStyle, AlignmentType, LevelFormat, ImageRun,
  PageBreak, Footer, PageNumber, VerticalAlign
} = require('docx');

function createKit(o) {
  const numbering = [];
  let numCount = 0;

  numbering.push({
    reference: 'bullets',
    levels: [
      { level: 0, format: LevelFormat.BULLET, text: '•', alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 720, hanging: 360 } } } },
      { level: 1, format: LevelFormat.BULLET, text: '–', alignment: AlignmentType.LEFT,
        style: { paragraph: { indent: { left: 1440, hanging: 360 } } } },
    ],
  });

  // **жирный** и `код` внутри строки
  function rich(text, base = {}) {
    const parts = String(text).split(/(\*\*[^*]+\*\*|`[^`]+`)/g).filter(s => s !== '');
    return parts.map(p => {
      if (p.startsWith('**')) return new TextRun({ ...base, text: p.slice(2, -2), bold: true });
      if (p.startsWith('`')) return new TextRun({
        ...base, text: p.slice(1, -1), font: o.codeFont, size: o.codeInlineSize || base.size,
        shading: { type: ShadingType.CLEAR, fill: 'EEF0F3', color: 'auto' },
      });
      return new TextRun({ ...base, text: p });
    });
  }

  const bodySpacing = { line: o.line, after: o.after ?? 0, before: 0 };

  function P(text, opts = {}) {
    return new Paragraph({
      alignment: opts.align || (o.justify ? AlignmentType.JUSTIFIED : AlignmentType.LEFT),
      spacing: { ...bodySpacing, ...(opts.spacing || {}) },
      indent: opts.noIndent ? undefined : (o.firstLine ? { firstLine: o.firstLine } : undefined),
      keepNext: opts.keepNext,
      children: rich(text, { size: o.size, ...(opts.run || {}) }),
    });
  }

  const H1 = t => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(t)] });
  const H2 = t => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(t)] });
  const H3 = t => new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(t)] });

  function B(items, level = 0) {
    return items.map(t => new Paragraph({
      numbering: { reference: 'bullets', level },
      alignment: o.justify ? AlignmentType.JUSTIFIED : AlignmentType.LEFT,
      spacing: { line: o.line, after: o.listAfter ?? 0, before: 0 },
      children: rich(t, { size: o.size }),
    }));
  }

  function N(items) {
    const ref = 'num' + (++numCount);
    numbering.push({
      reference: ref,
      levels: [{ level: 0, format: LevelFormat.DECIMAL, text: '%1.', alignment: AlignmentType.LEFT,
                 style: { paragraph: { indent: { left: 720, hanging: 360 } } } }],
    });
    return items.map(t => new Paragraph({
      numbering: { reference: ref, level: 0 },
      alignment: o.justify ? AlignmentType.JUSTIFIED : AlignmentType.LEFT,
      spacing: { line: o.line, after: o.listAfter ?? 0, before: 0 },
      children: rich(t, { size: o.size }),
    }));
  }

  function CODE(text) {
    const lines = String(text).replace(/\t/g, '    ').split('\n');
    const out = lines.map((ln, i) => new Paragraph({
      spacing: { line: 240, before: 0, after: 0 },
      indent: { left: 140 },
      keepLines: true,
      shading: { type: ShadingType.CLEAR, fill: 'F4F5F7', color: 'auto' },
      border: { left: { style: BorderStyle.SINGLE, size: 18, color: '4472C4', space: 6 } },
      children: [new TextRun({ text: ln === '' ? ' ' : ln, font: o.codeFont, size: o.codeSize })],
    }));
    out.push(new Paragraph({ spacing: { before: 0, after: o.codeGap ?? 120 }, children: [] }));
    return out;
  }

  function NOTE(label, text, fill = 'FFF4D6', color = 'E0A100') {
    return new Paragraph({
      spacing: { line: o.noteLine || 276, before: 80, after: 160 },
      shading: { type: ShadingType.CLEAR, fill, color: 'auto' },
      border: { left: { style: BorderStyle.SINGLE, size: 24, color, space: 8 } },
      indent: { left: 160, right: 80 },
      children: [new TextRun({ text: label + ' ', bold: true, size: o.noteSize || o.size }),
                 ...rich(text, { size: o.noteSize || o.size })],
    });
  }

  function TABLE(widths, header, rows, opts = {}) {
    const total = widths.reduce((a, b) => a + b, 0);
    const border = { style: BorderStyle.SINGLE, size: 4, color: 'A6A6A6' };
    const borders = { top: border, bottom: border, left: border, right: border };
    const fs = opts.size || o.tableSize;

    const mkCell = (content, w, isHead, fill) => {
      const paras = (Array.isArray(content) ? content : [content]).map(t => new Paragraph({
        spacing: { line: 252, before: 0, after: 0 },
        alignment: opts.centerCols && opts.centerCols.includes(widths.indexOf(w)) && !isHead ? AlignmentType.CENTER : AlignmentType.LEFT,
        children: rich(t, { size: fs, bold: isHead }),
      }));
      return new TableCell({
        width: { size: w, type: WidthType.DXA },
        borders,
        verticalAlign: VerticalAlign.CENTER,
        margins: { top: 60, bottom: 60, left: 100, right: 100 },
        shading: isHead ? { type: ShadingType.CLEAR, fill: o.tableHead || 'D9E2F3', color: 'auto' }
                        : (fill ? { type: ShadingType.CLEAR, fill, color: 'auto' } : undefined),
        children: paras,
      });
    };

    const trs = [];
    if (header) trs.push(new TableRow({ tableHeader: true, cantSplit: true,
      children: header.map((h, i) => mkCell(h, widths[i], true)) }));
    rows.forEach((r, ri) => trs.push(new TableRow({ cantSplit: true,
      children: r.map((c, i) => mkCell(c, widths[i], false, opts.zebra && ri % 2 ? 'F7F9FC' : null)) })));

    return [
      new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: widths, rows: trs }),
      new Paragraph({ spacing: { before: 0, after: 160 }, children: [] }),
    ];
  }

  function IMG(path, wPx, hPx, alt) {
    return new Paragraph({
      alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 60 },
      children: [new ImageRun({
        type: 'png', data: fs.readFileSync(path),
        transformation: { width: wPx, height: hPx },
        altText: { title: alt, description: alt, name: alt },
      })],
    });
  }

  const CAPTION = t => new Paragraph({
    alignment: AlignmentType.CENTER, spacing: { before: 0, after: 200 },
    children: [new TextRun({ text: t, italics: true, size: o.size - 2 })],
  });

  const PB = () => new Paragraph({ children: [new PageBreak()] });

  function footer() {
    return new Footer({ children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ children: [PageNumber.CURRENT], size: 20 })],
    })] });
  }

  function styles() {
    const h = (size, before, after, extra = {}) => ({ run: { size, bold: true, font: o.font, color: o.headColor, ...extra },
      paragraph: { spacing: { before, after }, keepNext: true, keepLines: true } });
    return {
      default: { document: { run: { font: o.font, size: o.size } } },
      paragraphStyles: [
        { id: 'Heading1', name: 'Heading 1', basedOn: 'Normal', next: 'Normal', quickFormat: true, ...h(o.h1, 320, 160), paragraph: { spacing: { before: 320, after: 160 }, keepNext: true, keepLines: true, outlineLevel: 0 } },
        { id: 'Heading2', name: 'Heading 2', basedOn: 'Normal', next: 'Normal', quickFormat: true, ...h(o.h2, 240, 120), paragraph: { spacing: { before: 240, after: 120 }, keepNext: true, keepLines: true, outlineLevel: 1 } },
        { id: 'Heading3', name: 'Heading 3', basedOn: 'Normal', next: 'Normal', quickFormat: true, ...h(o.h3, 200, 100, { italics: !!o.h3Italic }), paragraph: { spacing: { before: 200, after: 100 }, keepNext: true, keepLines: true, outlineLevel: 2 } },
      ],
    };
  }

  return { rich, P, H1, H2, H3, B, N, CODE, NOTE, TABLE, IMG, CAPTION, PB, footer, styles, numbering, Document, Packer, Paragraph, TextRun, AlignmentType };
}

// ---------- Извлечение кода из исходника ----------
function createSource(path) {
  const src = fs.readFileSync(path, 'utf8').split('\n');
  const find = (s, from = 0) => {
    const i = src.findIndex((l, idx) => idx >= from && l.includes(s));
    if (i < 0) throw new Error('Не найдено в исходнике: ' + s);
    return i;
  };
  // Блок от строки, начинающейся с s, до закрывающей скобки (по балансу { })
  function block(s) {
    const i = src.findIndex(l => l.startsWith(s));
    if (i < 0) throw new Error('Не найден блок: ' + s);
    let depth = 0, seen = false, j = i;
    for (; j < src.length; j++) {
      for (const ch of src[j]) { if (ch === '{') { depth++; seen = true; } else if (ch === '}') depth--; }
      if (seen && depth === 0) break;
    }
    return src.slice(i, j + 1).join('\n');
  }
  // Фрагмент от строки, содержащей a (включительно), до строки, содержащей b (не включая)
  function part(a, b) {
    const i = find(a);
    const j = find(b, i + 1);
    return src.slice(i, j).join('\n').replace(/\s+$/, '');
  }
  // Фрагмент от a до b включительно
  function partIncl(a, b) {
    const i = find(a);
    const j = find(b, i);
    return src.slice(i, j + 1).join('\n');
  }
  return { block, part, partIncl, lineCount: src.length };
}

module.exports = { createKit, createSource };

