const fs = require('fs');
const { createKit } = require('./lib');
const { AlignmentType, TextRun, Paragraph } = require('docx');

const k = createKit({
  font: 'Times New Roman', size: 28, line: 360, justify: true, firstLine: 709, after: 0, listAfter: 0,
  tableSize: 24, codeFont: 'Consolas', codeSize: 20, codeInlineSize: 24,
  h1: 32, h2: 28, h3: 28, h3Italic: true, headColor: '000000', noteLine: 300, noteSize: 24,
});
const { P, H1, H2, H3, B, N, NOTE, TABLE, IMG, CAPTION, PB } = k;
const W = 9355; // ширина текста: A4, поля 3 / 1.5 см

const c = [];     // содержимое основного раздела
const center = (text, o = {}) => new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { line: 360, before: o.before || 0, after: o.after || 0 },
  children: [new TextRun({ text, size: o.size || 28, bold: !!o.bold, allCaps: !!o.caps })],
});

// ============================ ТИТУЛЬНЫЙ ЛИСТ ============================
const title = [
  center('[Наименование учебного заведения]', { caps: true }),
  center('[Факультет / кафедра]', { after: 2200 }),
  center('ОТЧЁТ', { bold: true, size: 36 }),
  center('по лабораторной работе №2', { bold: true, size: 32, after: 200 }),
  center('«Файловая база данных с графическим интерфейсом»', { size: 30, after: 200 }),
  center('Предметная область: сервис составления программ тренировок', { size: 28, after: 2800 }),
  new Paragraph({ alignment: AlignmentType.LEFT, indent: { left: 4800 }, spacing: { line: 360 },
    children: [new TextRun({ text: 'Выполнил: [ФИО]', size: 28 })] }),
  new Paragraph({ alignment: AlignmentType.LEFT, indent: { left: 4800 }, spacing: { line: 360 },
    children: [new TextRun({ text: 'Группа: [номер группы]', size: 28 })] }),
  new Paragraph({ alignment: AlignmentType.LEFT, indent: { left: 4800 }, spacing: { line: 360, after: 200 },
    children: [new TextRun({ text: 'Проверил: [ФИО преподавателя]', size: 28 })] }),
  center('[Город], 2026', { before: 2400 }),
];

// ============================ СОДЕРЖАНИЕ ============================
c.push(H1('Содержание'));
const toc = ['1. Цель работы и постановка задачи', '2. Описание предметной области', '3. Структура базы данных',
  '4. Организация хранения данных в файле', '5. Реализованные функции', '6. Описание алгоритмов',
  '7. Анализ сложности алгоритмов', '8. Временная статистика', '9. Пользовательский интерфейс',
  '10. Контроль ввода и обработка ошибок', '11. Сценарии проверки', '12. Ограничения и возможные улучшения',
  '13. Заключение', '14. Список использованных источников'];
