});
const { P, H1, H2, H3, B, N, NOTE, TABLE, IMG, CAPTION, PB } = k;
const W = 9355; // ширина текста: A4, поля 3 / 1.5 см

const c = [];     // содержимое основного раздела
const center = (text, o = {}) => new Paragraph({
