  center('Предметная область: сервис составления программ тренировок', { size: 28, after: 2800 }),
  new Paragraph({ alignment: AlignmentType.LEFT, indent: { left: 4800 }, spacing: { line: 360 },
    children: [new TextRun({ text: 'Выполнил: [ФИО]', size: 28 })] }),
