const fs = require('fs');
const { createKit, createSource } = require('./lib');
const { AlignmentType, TextRun, Paragraph } = require('docx');

const SRC = '/mnt/user-data/outputs/workout_db_final.cpp';
const S = createSource(SRC);

const k = createKit({
  font: 'Calibri', size: 22, line: 288, justify: false, after: 100, listAfter: 40,
  tableSize: 20, codeFont: 'Consolas', codeSize: 17, codeInlineSize: 20, codeGap: 140,
  h1: 34, h2: 28, h3: 24, headColor: '1F3864', noteLine: 276, noteSize: 21, tableHead: 'DCE6F4',
});
const { P, H1, H2, H3, B, N, CODE, NOTE, TABLE, IMG, CAPTION, PB } = k;
const c = [];
const code = (s) => c.push(...CODE(s));
const blk = (s) => code(S.block(s));
const W = 9638;

// ============================ ТИТУЛ ============================
c.push(new Paragraph({ spacing: { before: 2200, after: 120 }, alignment: AlignmentType.LEFT,
  children: [new TextRun({ text: 'Подробный разбор программы', size: 52, bold: true, color: '1F3864' })] }));
c.push(new Paragraph({ spacing: { after: 120 },
  children: [new TextRun({ text: 'workout_db_final.cpp', size: 40, font: 'Consolas', color: '3B82F6' })] }));
c.push(new Paragraph({ spacing: { after: 400 },
  children: [new TextRun({ text: 'Файловая база данных «Журнал тренировок» с графическим интерфейсом (лабораторная работа №2)', size: 26, color: '475569' })] }));
c.push(P('Этот документ написан для того, чтобы вы **понимали каждую строку** своей программы и могли уверенно отвечать на вопросы на защите. Он идёт от общей идеи к деталям: сначала как устроен файл и алгоритмы, затем — как устроен интерфейс. Все фрагменты кода взяты из вашего файла без изменений.'));
c.push(NOTE('Как читать.', 'Если времени мало, прочитайте разделы 1–2 (идея и схема), затем разделы 7–9 (поиск, добавление, удаление) и раздел 15 (вопросы и ответы). Остальное — справочник, к которому можно возвращаться.', 'E8F1FD', '3B82F6'));
c.push(H2('Содержание'));
const toc = [
  '1. Программа за пять минут', '2. Схема файла и путь одной операции', '3. Подключаемые файлы и настройки',
  '4. Константы и структуры данных', '5. Ввод-вывод по смещению (readAt, writeAt и другие)',
  '6. Создание, проверка и открытие базы', '7. Поиск по ключу', '8. Добавление записи',
  '9. Удаление записи по ключу', '10. Редактирование записи', '11. Неключевые поля: разбор, сравнение, массовое удаление',
  '12. Экспорт в CSV', '13. Графический интерфейс', '14. Типичные ловушки', '15. Вопросы и ответы для защиты',
  '16. Как изменить программу', '17. Глоссарий',
];
toc.forEach(t => c.push(P(t, { spacing: { after: 20 } })));
c.push(PB());

// ============================ 1 ============================
c.push(H1('1. Программа за пять минут'));
c.push(P('**Что это.** Windows-программа с окном, в которой можно вести журнал тренировок: добавлять, менять, искать и удалять записи. Все данные лежат в одном бинарном файле `trainings.db`. Программа не держит базу в памяти — каждое действие читает и пишет нужные байты прямо в файле.'));
c.push(P('**Главная трудность лабораторной.** Искать запись в файле «подряд» медленно: чем больше записей, тем дольше. Преподаватель оценивает выше, если поиск, добавление и удаление работают за время, почти не зависящее от размера базы. Для этого в файле построена **хеш-таблица**.'));
c.push(H2('Три идеи, на которых всё держится'));
c.push(...N([
  '**Смещение (offset).** Файл — это длинная лента байтов. Любое место в ней можно назвать числом: «байт номер 4200». Если записи одинакового размера, то положение любой записи можно вычислить, а к нужному байту перейти мгновенно командой `seek`. Смещения — это «указатели» внутри файла.',
  '**Хеш-таблица с цепочками.** По ключу (`id`) мгновенно вычисляется «корзина» — `id % 1009`. В заголовке файла для каждой из 1009 корзин хранится смещение первой записи. Если в одну корзину попало несколько ключей, записи связаны цепочкой: каждая хранит смещение следующей. Поэтому искать приходится не по всему файлу, а только по короткой цепочке.',
  '**Список свободных слотов.** Удалённая запись не вырезается из файла (это пришлось бы сдвигать всё остальное). Её место помечается как свободное и запоминается в списке; следующая добавляемая запись займёт это место.',
]));
c.push(H2('Из каких слоёв состоит программа'));
c.push(IMG('/home/claude/fig_layers.png', 480, 331, 'Слои программы'));
c.push(CAPTION('Рисунок 1 — Слои программы: каждый слой вызывает только нижележащий'));
c.push(P('Такое разделение удобно объяснять и отлаживать: интерфейс ничего не знает о формате файла, а алгоритмы хеш-таблицы ничего не знают об окне.'));
c.push(H2('Карта кода'));
c.push(...TABLE([2300, 4300, 3038], ['Часть файла', 'Что в ней', 'Главные имена'], [
  ['Часть 1 (БД)', 'Структуры, работа с файлом, алгоритмы хеш-таблицы, поиск, экспорт', '`Header`, `Record`, `readAt`, `findOffset`, `addToFile`, `deleteFromFile`'],
  ['Часть 2 (интерфейс)', 'Окно, элементы, таблица, форма, обработчики кнопок, отрисовка', '`createControls`, `WndProc`, `cmd…`, `drawButton`'],
], { zebra: true }));
c.push(PB());

// ============================ 2 ============================
c.push(H1('2. Схема файла и путь одной операции'));
c.push(H2('2.1. Как выглядит файл'));
c.push(IMG('/home/claude/fig_file.png', 560, 313, 'Структура файла'));
c.push(CAPTION('Рисунок 2 — Файл базы после добавления записей с ключами 101 и 1110'));
c.push(P('Как читать рисунок:'));
c.push(...B([
