toc.forEach(t => c.push(P(t, { spacing: { after: 20 } })));
c.push(PB());

// ============================ 1 ============================
c.push(H1('1. Программа за пять минут'));
c.push(P('**Что это.** Windows-программа с окном, в которой можно вести журнал тренировок: добавлять, менять, искать и удалять записи. Все данные лежат в одном бинарном файле `trainings.db`. Программа не держит базу в памяти — каждое действие читает и пишет нужные байты прямо в файле.'));
c.push(P('**Главная трудность лабораторной.** Искать запись в файле «подряд» медленно: чем больше записей, тем дольше. Преподаватель оценивает выше, если поиск, добавление и удаление работают за время, почти не зависящее от размера базы. Для этого в файле построена **хеш-таблица**.'));
c.push(H2('Три идеи, на которых всё держится'));
c.push(...N([
  '**Смещение (offset).** Файл — это длинная лента байтов. Любое место в ней можно назвать числом: «байт номер 4200». Если записи одинакового размера, то положение любой записи можно вычислить, а к нужному байту перейти мгновенно командой `seek`. Смещения — это «указатели» внутри файла.',
